# roman.py

def to_roman(n: int) -> str:
    """
    Converts an integer (1 to 3999) to its standard Roman numeral representation.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if isinstance(n, bool):
        # Although bool is a subclass of int, the requirement specifically bans bools.
        raise TypeError("Input must be an integer, not a boolean.")
    if not 1 <= n <= 3999:
        raise ValueError("Input must be between 1 and 3999 inclusive.")

    mapping = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    result = []
    for value, numeral in mapping:
        while n >= value:
            result.append(numeral)
            n -= value

    return "".join(result)

def from_roman(s: str) -> int:
    """
    Converts a canonical Roman numeral string to its integer value.
    Raises ValueError for any non-canonical or invalid input.
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string.")

    if not s:
        raise ValueError("Input string cannot be empty.")

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 
        'C': 100, 'D': 500, 'M': 1000
    }

    # 1. Check for character validity and case
    for char in s:
        if char not in roman_map:
            raise ValueError(f"Invalid character in Roman numeral: '{char}'")

    # 2. Check for canonical form (enforces strict structure)
    # We leverage the fact that to_roman(value) must equal s.
    try:
        # Convert the input string back to an integer using the standard algorithm
        # to verify if it's a valid, canonical representation.
        # Since we already checked characters, we just need to verify structure.

        # The standard parsing logic:
        total = 0
        i = 0
        while i < len(s):
            current_value = roman_map[s[i]]
            if i + 1 < len(s):
                next_value = roman_map[s[i+1]]

                if current_value < next_value:
                    # Subtractive case (e.g., IV, IX)
                    total += (next_value - current_value)
                    i += 2
                    continue

            # Additive case
            total += current_value
            i += 1

        # 3. Final validation: ensure the parsed number is exactly what to_roman produces
        expected_roman = to_roman(total)
        if expected_roman != s:
            # This catches non-canonical forms like 'IIII', 'VX', 'CMCM', etc.
            raise ValueError("Input is not a canonical Roman numeral representation.")

        return total

    except ValueError as e:
        # Re-raise the specific ValueError generated by our checks or the internal logic
        if "Invalid character" in str(e) or "not a canonical" in str(e):
             raise e
        # If the internal loop failed in an unexpected way (shouldn't happen if checks are complete)
        raise ValueError("Input is not a valid canonical Roman numeral.")
    except Exception:
        # Catch any other unforeseen issue during parsing and treat it as invalid input
        raise ValueError("Input is not a valid canonical Roman numeral.")

if __name__ == '__main__':
    # --- Testing to_roman ---
    print("--- Testing to_roman ---")
    try:
        print(f"1: {to_roman(1)}")       # I
        print(f"4: {to_roman(4)}")       # IV
        print(f"9: {to_roman(9)}")       # IX
        print(f"58: {to_roman(58)}")     # LVIII
        print(f"1994: {to_roman(1994)}") # MCMXCIV
        print(f"3999: {to_roman(3999)}") # MMMCMXCIX

        # Testing errors
        try:
            to_roman(4000)
        except ValueError as e:
            print(f"Error Test (4000): Passed ({e})")

        try:
            to_roman(3.14)
        except TypeError as e:
            print(f"Error Test (Float): Passed ({e})")

        try:
            to_roman(True)
        except TypeError as e:
            print(f"Error Test (Bool): Passed ({e})")

    except Exception as e:
        print(f"Unexpected failure in to_roman test: {e}")

    print("\n" + "="*30 + "\n")

    # --- Testing from_roman ---
    print("--- Testing from_roman ---")
