    }
    for roman, expected in valid_cases.items():
        try:
            result = from_roman(roman)
            assert result == expected
            print(f"Success: {roman} -> {result}")
        except Exception as e:
            print(f"Failure: {roman} unexpectedly failed with {e}")

    # Testing invalid cases
    invalid_cases = [
