        "xiv",       # Lowercase
        "MCMXCIV ",  # Whitespace
        "IC",        # Non-canonical
        "IIII",      # Non-canonical
        "MMMM",      # Too large for standard representation check
        "VX",        # Non-canonical (V should not precede X)
