import csv
import io
from dataclasses import dataclass
from datetime import date as dt_date
from decimal import Decimal, InvalidOperation

# --- Custom Exceptions ---

class LedgerError(Exception):
    """Base exception for ledger errors."""
    def __init__(self, message: str, line: int):
        super().__init__(message)
        self.line = line

class OverdraftError(LedgerError):
    """Exception raised when a transaction causes an overdraft beyond the limit."""
    def __init__(self, transaction, account: str, balance: Decimal):
        message = f"Transaction on line {transaction.line} for account '{account}' would result in an overdraft."
        super().__init__(message, transaction.line)
        self.account = account
        self.balance = balance

# --- Data Structure ---

@dataclass(frozen=True)
class Transaction:
    """Represents a single bank transaction."""
    date: dt_date
    account: str
    amount: Decimal
    line: int

# --- Core Logic ---

def parse(text: str) -> list[Transaction]:
    """
    Parses CSV text into a list of Transaction objects.
    """
    lines = text.strip().splitlines()
    if not lines or not lines[0].strip():
        raise LedgerError("Input text is empty.", 1)

    # Use StringIO to treat the string as a file
    f = io.StringIO(text)
    reader = csv.reader(f)

    try:
        # Read header (Line 1)
        header = next(reader)
    except StopIteration:
        raise LedgerError("Input text is empty or only contains whitespace.", 1)

    # Determine required columns and their indices
    required_fields = {'date', 'account', 'amount'}
    header_map = {}
    for i, col_name in enumerate(header):
        col_name_stripped = col_name.strip().lower()
        if col_name_stripped in required_fields:
            header_map[col_name_stripped] = i

    if len(header_map) != 3:
        raise LedgerError(
            "Header must contain 'date', 'account', and 'amount' columns.", 1
        )

    transactions: list[Transaction] = []
    line_number = 1  # Start counting from the header line

    # Process data rows
    for row in reader:
        line_number += 1

        # Handle blank lines (they are skipped but count as a line in the original structure)
        if not any(cell.strip() for cell in row):
            # We don't store placeholder transactions for blank lines, just move the line count
            continue

        # Check if the row has enough columns based on the header size
        if len(row) < len(header):
            raise LedgerError(
                f"Row does not have enough fields. Expected at least {len(header)}.", line_number
            )

        try:
            # Extract fields using mapped indices
            date_str = row[header_map['date']].strip()
            account_str = row[header_map['account']].strip()
            amount_str = row[header_map['amount']].strip()

            # 1. Validate Date
            try:
                t_date = dt_date.fromisoformat(date_str)
            except ValueError:
                raise LedgerError(f"Invalid date format: {date_str}. Expected YYYY-MM-DD.", line_number)

            # 2. Validate Account
            if not account_str:
                raise LedgerError("Account name cannot be empty.", line_number)

            # 3. Validate Amount
            # Allow surrounding spaces, then parse
            amount_str_cleaned = amount_str.replace(' ', '')
            if not amount_str_cleaned:
                 raise LedgerError("Amount field cannot be empty.", line_number)

            try:
                # Check for at most two digits after the point (Decimal handles this implicitly 
                # if we strictly parse, but we check for basic structural compliance)
                d_amount = Decimal(amount_str_cleaned)

                # Optional strict check for precision (e.g., 1.234 should fail)
                if '.' in amount_str_cleaned:
                    _, fractional_part = amount_str_cleaned.split('.')
                    if len(fractional_part) > 2:
                         raise ValueError("Too many decimal places.")

            except (InvalidOperation, ValueError):
                raise LedgerError(f"Invalid amount format: {amount_str}", line_number)

            # Create transaction
            tx = Transaction(
                date=t_date, 
                account=account_str, 
                amount=d_amount, 
                line=line_number
            )
            transactions.append(tx)

        except LedgerError:
            # Re-raise structured ledger errors
            raise
        except Exception as e:
            # Catch any other unexpected parsing errors and wrap them as LedgerError
            raise LedgerError(f"Unexpected parsing error: {e}", line_number)


    return transactions

def running_balances(transactions: list[Transaction], opening: dict[str, Decimal] | None = None, limits: dict[str, Decimal] | None = None) -> list[tuple[Transaction, Decimal]]:
    """
    Computes running balances for transactions in date order, enforcing overdraft limits.
    """
    if opening is None:
        opening = {}
    if limits is None:
        limits = {}

    # 1. Sort transactions by date, then by original order (stable sort behavior)
    # Since the input transactions list maintains original order for same-day txs, 
    # standard sort is sufficient if we sort by date only.
    sorted_transactions = sorted(transactions, key=lambda tx: tx.date)

    balances: dict[str, Decimal] = {acc: opening.get(acc, Decimal('0')) for acc in set(opening.keys()) | set(t.account for t in transactions)}

    # Ensure all accounts present in transactions are initialized, even if not in opening
    for tx in sorted_transactions:
        if tx.account not in balances:
            balances[tx.account] = Decimal('0')
        # Also ensure limit exists for consistency, defaulting to 0
        if tx.account not in limits:
            limits[tx.account] = Decimal('0')

    results: list[tuple[Transaction, Decimal]] = []

    for tx in sorted_transactions:
        account = tx.account
        current_balance = balances[account]
        limit = limits[account]

        new_balance = current_balance + tx.amount

        # Check for overdraft
        # The account may go down to exactly -limit but not below.
        if new_balance < -limit:
            raise OverdraftError(
                transaction=tx,
                account=account,
                balance=new_balance
            )

        # Update balance and record result
        balances[account] = new_balance
        results.append((tx, new_balance))

    return results

def final_balances(transactions: list[Transaction], opening: dict[str, Decimal] | None = None, limits: dict[str, Decimal] | None = None) -> dict[str, Decimal]:
    """
    Returns the final balance of every account after all transactions, enforcing overdraft rules.
    """
    if opening is None:
        opening = {}
    if limits is None:
        limits = {}

    # We must run the full check sequence, even if we only need the final result.
    # We use running_balances internally to ensure overdrafts are caught during calculation.
    try:
        results = running_balances(transactions, opening, limits)
    except OverdraftError as e:
        # If an overdraft occurs, we must raise it, as per requirement.
        raise e

    # Collect the final balance from the results
    final_balances_map: dict[str, Decimal] = {}

    # Start with all accounts from opening, even if they had no transactions
    for acc, bal in opening.items():
        final_balances_map[acc] = bal

    # Update with the last calculated balance for accounts that had transactions
    for tx, balance in results:
        final_balances_map[tx.account] = balance

    return final_balances_map

if __name__ == '__main__':
    # --- Example Usage ---

    sample_csv = """date,account,amount,description
2023-01-15,Checking,1000.00,Initial Deposit
2023-01-20,Savings,-50.50,Transfer out
2023-01-25,Checking,-200.00,Online purchase
2023-01-25,Savings,50.00,Deposit
2023-02-01,Checking,10.00,Small fee
2023-02-10,Checking,-1500.00,Large withdrawal
"""

    print("--- 1. Parsing Test ---")
    try:
        tx_list = parse(sample_csv)
        print(f"Successfully parsed {len(tx_list)} transactions.")
        for tx in tx_list:
            print(f"  {tx.date} | {tx.account} | {tx.amount} | Line {tx.line}")
    except LedgerError as e:
        print(f"Parsing Error: {e}")

    print("\n--- 2. Running Balances Test (Standard) ---")
    try:
        # Open with Checking starting at 500
        opening_balances = {'Checking': Decimal('500.00')}

        results = running_balances(tx_list, opening=opening_balances)

        for tx, balance in results:
            print(f"Tx Date: {tx.date}, Account: {tx.account}, Amount: {tx.amount}, Balance After: {balance}")

    except OverdraftError as e:
        print(f"Running Balance Error: {e}")


    print("\n--- 3. Overdraft Test (Forcing Failure) ---")

    # Initial setup where Checking starts at 500, and the limit is 100.
    # The large withdrawal of -1500.00 should fail because 500 - 1500 = -1000, which is < -100.
    opening_for_fail = {'Checking': Decimal('500.00')}
    limit_for_fail = {'Checking': Decimal('-100.00')} 

    try:
        running_balances(tx_list, opening=opening_for_fail, limits=limit_for_fail)
    except OverdraftError as e:
        print("--- SUCCESSFULLY CAUGHT OVERDRAFT ---")
        print(f"Error Type: {type(e).__name__}")
        print(f"Caused by transaction on line: {e.line}")
        print(f"Account: {e.account}")
        print(f"Projected Balance: {e.balance}")


    print("\n--- 4. Final Balances Test (Success Case) ---")
    try:
        # Running balances successfully, so we check final balances
        final = final_balances(tx_list, opening={'Checking': Decimal('500.00')}, limits={'Checking': Decimal('-10000')})
        print("Final Balances:")
        for acc, bal in final.items():
            print(f"  {acc}: {bal}")

    except OverdraftError as e:
        print(f"Final Balance Check Failed unexpectedly: {e}")
