# jpath.py
import re
from typing import Any, List, Union, MutableMapping
from collections.abc import Mapping

class PathError(LookupError):
    """Raised when a path lookup fails due to syntax error or missing value."""
    def __init__(self, message: str, path: str):
        super().__init__(message)
        self.path = path

# --- Parsing Implementation ---

def parse(path: str) -> List[Union[str, int]]:
    """
    Parses a path string into a list of segments (strings for keys/quoted keys,
    integers for indices).

    Raises:
        PathError: If the path syntax is invalid.
    """
    if not path:
        return []

    segments: List[Union[str, int]] = []
    i = 0
    n = len(path)

    # State machine/Iterative parsing approach
    while i < n:
        segment_start = i

        # 1. Handle quoted string key: "..."
        if path[i] == '"':
            i += 1 # Skip opening quote
            content_start = i

            while i < n:
                if path[i] == '\\':
                    i += 1
                    if i >= n:
                        raise PathError("Unclosed escape sequence", path)

                    next_char = path[i]
                    if next_char == '"':
                        # Escaped quote inside string
                        i += 1
                        continue
                    elif next_char == '\\':
                        # Escaped backslash inside string
                        i += 1
                        continue
                    else:
                        # Any other backslash is a syntax error per requirements
                        raise PathError("Invalid escape sequence inside quoted string", path)
                elif path[i] == '"':
                    # End of quoted string
                    content = path[content_start:i]
                    segments.append(content)
                    i += 1 # Skip closing quote
                    break
                else:
                    i += 1
            else:
                # Loop finished without finding closing quote
                raise PathError("Unclosed quoted string", path)
            continue

        # 2. Handle bracketed index: [N] or [["..."]] (though quoted keys inside brackets are usually not expected based on the grammar, we handle the integer case strictly)
        if path[i] == '[':
            i += 1 # Skip opening bracket

            # Must start with an integer or another opening bracket (which is disallowed by strict grammar rules, but we look for integer)
            if i >= n or not path[i].isdigit() and path[i] != '-':
                 raise PathError("Invalid start of index segment", path)

            start_of_number = i

            # Parse integer N
            if path[i] == '-':
                i += 1 # Move past '-'

            while i < n and path[i].isdigit():
                i += 1

            num_str = path[start_of_number:i]
            try:
                index = int(num_str)
                segments.append(index)
            except ValueError:
                 # Should not happen if logic above is correct, but safe guard
                raise PathError(f"Invalid integer format in index: {num_str}", path)

            # Expect closing bracket ']'
            if i >= n or path[i] != ']':
                raise PathError("Unclosed bracket or invalid suffix after index", path)
            i += 1 # Skip closing bracket
            continue

        # 3. Handle bare name segment
        else:
            # Name consists of chars other than ., [, ], "
            start_of_name = i
            while i < n and path[i] not in ('.', '[', ']', '"'):
                i += 1

            name = path[start_of_name:i]

            if not name:
                # This catches cases like '..', '.a', or starting with '.' if not handled by [N]
                raise PathError("Empty segment name found", path)

            segments.append(name)
            continue

    # Final validation check:
    # Check for trailing characters that should have been consumed (e.g., trailing '.')
    # This is largely covered by the loop logic, but we ensure no dangling '.' or ']' etc.

    return segments


# --- Get Implementation ---

def get(obj: Any, path: str, default: Any = None) -> Any:
    """
    Retrieves a value from obj following the path string.
    """
    try:
        segments = parse(path)
    except PathError as e:
        # Syntax error always raises PathError, even with default
        raise PathError(f"Path syntax error: {e.args[0]}", path) from e

    current = obj

    for segment in segments:
        if isinstance(segment, str):
            # String segment: must look up in Mapping
            if not isinstance(current, Mapping):
                if default is not None:
                    return default
                raise PathError(f"Attempted dictionary/key lookup on non-mapping type", path)

            try:
                current = current[segment]
            except KeyError:
                if default is not None:
                    return default
                raise PathError(f"Key '{segment}' not found", path)

        elif isinstance(segment, int):
            # Integer segment: must index a sequence (list/tuple)
            if not isinstance(current, (list, tuple)):
                if default is not None:
                    return default
                raise PathError(f"Attempted index lookup on non-sequence type", path)

            try:
                current = current[segment]
            except IndexError:
                if default is not None:
                    return default
                raise PathError(f"Index '{segment}' out of bounds", path)

        else:
            # Should not happen if parsing is correct, but guards against weird segments
            if default is not None:
                return default
            raise PathError(f"Invalid segment type encountered during traversal", path)

    return current

if __name__ == '__main__':
    # --- Example Usage and Tests ---

    data = {
        "user": {
            "name": "Alice",
            "details": {
                "age": 30,
                "hobbies": ["reading", "coding", "hiking"]
            }
        },
        "metadata": [
            {"id": 1, "type": "A"},
            {"id": 2, "type": "B", "value": "hello"},
            {"id": 3, "type": "C"}
        ],
        "config": {
            "key.with.dot": 99
        },
        "empty_list": []
    }

    print("--- Testing GET Functionality ---")

    # Successful lookups
    print(f"user.name: {get(data, 'user.name')}")  # Alice
    print(f"metadata[1].value: {get(data, 'metadata[1].value')}")  # hello
    print(f"metadata[-1].type: {get(data, 'metadata[-1].type')}") # C
    print(f"config[\"key.with.dot\"]: {get(data, 'config[\"key.with.dot\"]')}") # 99
    print(f"root (empty path): {get(data, '')}") # data object
    print(f"empty_list[0] (default): {get(data, 'empty_list[0]', default='MISSING')}") # MISSING
    print(f"empty_list[] (default): {get(data, 'empty_list[]', default='MISSING')}") # MISSING (Parse failure caught before get)

    print("\n--- Testing Missing Value (Default provided) ---")
    print(f"user.address (default None): {get(data, 'user.address', default=None)}") # None
    print(f"metadata[5] (default 'N/A'): {get(data, 'metadata[5]', default='N/A')}") # N/A
    print(f"metadata[1].nonexistent (default 0): {get(data, 'metadata[1].nonexistent', default=0)}") # 0

    print("\n--- Testing Missing Value (No Default, expecting PathError) ---")
    try:
        get(data, 'user.nonexistent')
    except PathError as e:
        print(f"Caught expected error (No default): {e}")

    try:
        get(data, 'metadata[5]')
    except PathError as e:
        print(f"Caught expected error (Index OOB): {e}")

    # --- Testing Syntax Errors (PathError always raised) ---
    print("\n--- Testing Syntax Errors ---")

    # Empty path
    try:
        get(data, '') # This succeeds, should be handled above
    except PathError as e:
        print(f"Unexpected error on empty path: {e}")

    # Malformed
    error_paths = [
        "a..b",    # Empty name
        ".a",      # Starts with dot
        "a.",      # Ends with dot
        "a.[0]",   # Dot before bracket (though parse handles this structure, strict check might flag it)
        "a[]",     # Empty bracket
        "a[1.5]",  # Float index
        "a[x]",    # String index
        "a[0",     # Unclosed bracket
        'a["key\'' # Unclosed quote
    ]

    for p in error_paths:
        try:
            get(data, p)
        except PathError as e:
            print(f"Caught expected syntax error for '{p}': {e}")

    # Test path starting with bracket
    try:
        get(data, '[0].metadata') # Valid syntax start
        print("Successfully parsed and got '[0].metadata'")
    except PathError as e:
        print(f"Unexpected error on '[0].metadata': {e}")

    # Test quoted key starting path
    try:
        get(data, '["key.with.dot"]').path
        print("Successfully parsed path starting with quoted key")
    except PathError as e:
        print(f"Unexpected error on starting with quoted key: {e}")

