import re
from typing import Any, List, Union, MutableMapping, Iterator, TypeVar
from collections.abc import Mapping

T = TypeVar('T')

class PathError(LookupError):
    """Raised when a path lookup fails due to syntax error or missing value."""
    def __init__(self, message: str, path: str):
        super().__init__(message)
        self.path = path

# Unique constant for the wildcard segment
WILDCARD = object()

# --- Parsing Implementation ---

def parse(path: str) -> List[Union[str, int, object]]:
    """
    Parses a path string into a list of segments (strings for keys/quoted keys,
    integers for indices, or WILDCARD).

    Raises:
        PathError: If the path syntax is invalid.
    """
    if not path:
        return []

    segments: List[Union[str, int, object]] = []
    i = 0
    n = len(path)

    while i < n:
        segment_start = i

        # 1. Handle quoted string key: "..."
        if path[i] == '"':
            i += 1 # Skip opening quote
            content_start = i

            while i < n:
                if path[i] == '\\':
                    i += 1
                    if i >= n:
                        raise PathError("Unclosed escape sequence", path)

                    next_char = path[i]
                    if next_char == '"':
                        i += 1
                        continue
                    elif next_char == '\\':
                        i += 1
                        continue
                    else:
                        raise PathError("Invalid escape sequence inside quoted string", path)
                elif path[i] == '"':
                    content = path[content_start:i]
                    segments.append(content)
                    i += 1 # Skip closing quote
                    break
                else:
                    i += 1
            else:
                raise PathError("Unclosed quoted string", path)
            continue

        # 2. Handle wildcard segment: [*]
        if path[i] == '[' and i + 1 < n and path[i+1] == '*':
            if i + 2 < n and path[i+2] == ']':
                segments.append(WILDCARD)
                i += 3 # Skip [*]
                continue
            # Fall through if [*] syntax is incomplete

        # 3. Handle bracketed index: [N]
        if path[i] == '[':
            i += 1 # Skip opening bracket

            # Check if it's an integer index, not a wildcard already handled above
            if i >= n or not (path[i].isdigit() or path[i] == '-'):
                 raise PathError("Invalid segment start after '['", path)

            start_of_number = i

            # Parse integer N
            if path[i] == '-':
                i += 1 

            while i < n and path[i].isdigit():
                i += 1

            num_str = path[start_of_number:i]
            try:
                index = int(num_str)
                segments.append(index)
            except ValueError:
                raise PathError(f"Invalid integer format in index: {num_str}", path)

            # Expect closing bracket ']'
            if i >= n or path[i] != ']':
                raise PathError("Unclosed bracket or invalid suffix after index", path)
            i += 1 # Skip closing bracket
            continue

        # 4. Handle bare name segment
        else:
            # Name consists of chars other than ., [, ], "
            start_of_name = i
            while i < n and path[i] not in ('.', '[', ']', '"'):
                i += 1

            name = path[start_of_name:i]

            if not name:
                raise PathError("Empty segment name found", path)

            segments.append(name)
            continue

    return segments

# --- GET Functionality ---

def _recursive_get(current: Any, segments: List[Union[str, int, object]], 
                    current_path_segment: List[Union[str, int, object]], 
                    is_wildcard_present: bool) -> List[Any]:
    """
    Internal recursive helper for get, handles wildcards by returning a list of results.
    """
    if not segments:
        # Base case: reached the end of the path
        return [current]

    segment = segments[0]
    remaining_segments = segments[1:]
    results = []

    if segment == WILDCARD:
        # Wildcard expansion: iterate over all elements/keys
        if isinstance(current, Mapping):
            items = current.items()
        elif isinstance(current, (list, tuple)):
            items = enumerate(current)
        else:
            # Wildcard cannot expand on scalars
            return []

        for key, value in items:
            next_segment_path = current_path_segment + [WILDCARD]

            if isinstance(key, str):
                next_segment_path.append(key) # Map key to string segment for recursion
            elif isinstance(key, int):
                next_segment_path.append(key) # Map index to int segment for recursion

            # Recurse immediately, effectively treating the wildcard as the first step
            sub_results = _recursive_get(value, remaining_segments, next_segment_path, True)
            results.extend(sub_results)

        # Special handling for the last segment being a wildcard
        if not remaining_segments:
            return [current] if isinstance(current, (list, tuple)) else list(current.values())

        return results

    elif isinstance(segment, str):
        # Dictionary/Key lookup
        if not isinstance(current, Mapping):
            return [] # Cannot traverse further

        if segment not in current:
            return [] # Key missing

        next_segment_path = current_path_segment + [segment]

        # Check if this lookup is followed by a wildcard
        sub_results = _recursive_get(current[segment], remaining_segments, next_segment_path, is_wildcard_present)
        results.extend(sub_results)
        return results

    elif isinstance(segment, int):
        # List/Tuple index lookup
        if not isinstance(current, (list, tuple)):
            return [] # Cannot index a scalar

        if segment < 0:
            try:
                # Negative indexing is handled by Python runtime
                value = current[segment]
                next_segment_path = current_path_segment + [segment]
                sub_results = _recursive_get(value, remaining_segments, next_segment_path, is_wildcard_present)
                results.extend(sub_results)
            except IndexError:
                return []
        else:
            try:
                value = current[segment]
                next_segment_path = current_path_segment + [segment]
                sub_results = _recursive_get(value, remaining_segments, next_segment_path, is_wildcard_present)
                results.extend(sub_results)
            except IndexError:
                return []
        return results

    return []


def get(obj: Any, path: str, default: Any = None) -> Any:
    """
    Retrieves a value from obj following the path string.
    If wildcards are present, returns a list of matching values.
    """
    try:
        segments = parse(path)
    except PathError as e:
        raise PathError(f"Path syntax error: {e.args[0]}", path) from e

    if not segments:
        return obj

    has_wildcard = WILDCARD in segments

    if not has_wildcard:
        # Standard traversal (No wildcards)
        current = obj
        for segment in segments:
            if isinstance(segment, str):
                if not isinstance(current, Mapping):
                    if default is not None: return default
                    raise PathError(f"Key lookup on non-mapping type", path)
                try:
                    current = current[segment]
                except KeyError:
                    if default is not None: return default
                    raise PathError(f"Key '{segment}' not found", path)
            elif isinstance(segment, int):
                if not isinstance(current, (list, tuple)):
                    if default is not None: return default
                    raise PathError(f"Index lookup on non-sequence type", path)
                try:
                    current = current[segment]
                except IndexError:
                    if default is not None: return default
                    raise PathError(f"Index '{segment}' out of bounds", path)
            else:
                # Should be unreachable if parse is correct
                if default is not None: return default
                raise PathError("Invalid segment type encountered during traversal", path)
        return current
    else:
        # Wildcard traversal (Returns a list of results)
        results = _recursive_get(obj, segments, [], True)
        if not results:
            return [] # Wildcard paths never raise, return empty list if nothing found

        # If only one result, return it directly (maintaining compatibility if only one path matches)
        if len(results) == 1:
            return results[0]
        return results


# --- SET Functionality ---

def _traverse_for_set(obj: Any, segments: List[Union[str, int, object]], 
                      path_history: List[Any], parent_container: Any) -> tuple[Any, Any, str]:
    """
    Traverses to the parent container and the final segment to be set.
    Returns (parent_container, last_segment, remaining_segments).
    Raises PathError on failure.
    """
    if not segments:
        raise PathError("Cannot set on an empty path", "N/A")

    last_segment = segments[-1]
    path_to_parent = segments[:-1]

    current = obj

    for segment in path_to_parent:

        if isinstance(segment, str):
            # Key segment: must be in a Mapping
            if not isinstance(current, Mapping):
                raise PathError("Key segment requires a Mapping parent", "N/A")

            if segment not in current:
                # Missing key: determine structure for creation
                next_segment = path_to_parent[path_to_parent.index(segment) + 1]
                if isinstance(next_segment, int):
                    # Next is index -> create list
                    new_val = []
                    current[segment] = new_val
                    current = new_val
                else:
                    # Next is key/wildcard -> create dict
                    new_val = {}
                    current[segment] = new_val
                    current = new_val
            else:
                current = current[segment]

        elif isinstance(segment, int):
            # Index segment: must be in a Sequence
            if not isinstance(current, (list, tuple)):
                raise PathError("Index segment requires a Sequence parent", "N/A")

            idx = segment
            if idx < 0:
                idx += len(current)

            if idx < 0 or idx >= len(current):
                # Index out of bounds for existing structure
                raise PathError(f"Index {segment} out of bounds for existing structure", "N/A")

            # If we are creating a list, index 0 is the only valid creation point
            if len(current) == 0 and idx == 0:
                 # This logic path shouldn't be hit for path_to_parent traversal unless we are at the very start
                 pass

            current = current[idx]

        elif segment == WILDCARD:
            # Wildcards are not supported for setting/deleting
            raise PathError("Wildcards are not supported for setting or deleting", "N/A")

        else:
            raise PathError("Unexpected segment type during traversal", "N/A")

        path_history.append(current)
        parent_container = current # Keep track of the container leading to the current element

    # Final traversal step to isolate the parent container of the last segment
    # We need the container that holds the final item/slot

    if not path_to_parent:
        # The last segment is the first segment (e.g., set({}, 'a', 1))
        return obj, segments[0], segments

    # The parent container is the object referenced by the last element in path_history
    parent = path_history[-1]
    final_segment = last_segment
    return parent, final_segment, segments


def set(obj: Any, path: str, value: Any) -> None:
    """
    Stores value at path, changing obj in place.
    """
    try:
        segments = parse(path)
    except PathError as e:
        raise PathError(f"Path syntax error: {e.args[0]}", path) from e

    if not segments or WILDCARD in segments:
        raise PathError("Set operation requires a non-empty path without wildcards", path)

    try:
        # We use a slightly simplified traversal logic here because full path history tracking 
        # in _traverse_for_set is overly complex for the mutation rules defined. 
        # We track the parent container explicitly.

        current = obj
        parent = None
        parent_segment = None

        path_to_parent = segments[:-1]
        final_segment = segments[-1]

        for i, segment in enumerate(path_to_parent):
            is_last_in_parent_path = (i == len(path_to_parent) - 1)

            if isinstance(segment, str):
                # Key segment
                if not isinstance(current, Mapping):
                    raise PathError("Cannot set key on non-mapping type", path)

                if segment not in current:
                    # Create structure if missing
                    next_segment = segments[i + 1]

                    if isinstance(next_segment, int):
                        # Next is index -> create list
                        new_container = []
                        current[segment] = new_container
                        current = new_container
                    else:
                        # Next is key/wildcard -> create dict
                        new_container = {}
                        current[segment] = new_container
                        current = new_container
                else:
                    # Key exists
                    current = current[segment]

                parent = current # Current becomes the parent for the next step if we need to append
                parent_segment = segment

            elif isinstance(segment, int):
                # Index segment
                if not isinstance(current, (list, tuple)):
                    raise PathError("Cannot set index on non-sequence type", path)

                idx = segment
                if idx < 0:
                    idx += len(current)

                if idx < 0 or idx >= len(current):
                    raise PathError(f"Index {segment} out of bounds for existing structure", path)

                # If we are replacing an existing element, the parent remains 'current'
                current = current[idx]

                parent = current # Current is the item being replaced/updated
                parent_segment = segment


        # --- Handle the final segment ---
        if isinstance(final_segment, str):
            # Final operation is setting a key
            if not isinstance(current, Mapping):
                raise PathError("Final key segment requires a Mapping parent", path)
            current[final_segment] = value

        elif isinstance(final_segment, int):
            # Final operation is setting an index
            if not isinstance(current, (list, tuple)):
                raise PathError("Final index segment requires a Sequence parent", path)

            idx = final_segment

            # List specific logic: append if index == len, otherwise replace
            if idx < 0:
                idx += len(current)

            if idx < 0:
                 raise PathError(f"Final index {final_segment} out of bounds (negative)", path)

            if idx == len(current):
                # Append
                current.append(value)
            elif idx < len(current):
                # Replace
                current[idx] = value
            else:
                # Index too high for replacement
                raise PathError(f"Final index {final_segment} out of bounds (positive)", path)

        elif final_segment == WILDCARD:
            # Should have been caught earlier, but safety check
            raise PathError("Wildcards are not supported for setting", path)

    except PathError:
        # Re-raise PathError to ensure object is unchanged
        raise
    except Exception as e:
        # Catch unexpected errors during mutation and wrap as PathError
        raise PathError(f"Mutation failed due to internal error: {type(e).__name__}", path) from e


# --- DELETE Functionality ---

def delete(obj: Any, path: str) -> Any:
    """
    Removes the value at path and returns it.
    """
    try:
        segments = parse(path)
    except PathError as e:
        raise PathError(f"Path syntax error: {e.args[0]}", path) from e

    if not segments or WILDCARD in segments:
        raise PathError("Delete operation requires a non-empty path without wildcards", path)

    if len(segments) == 1:
        # Deleting the root element (only possible if obj is a dict/list)
        if isinstance(obj, Mapping):
            key = segments[0]
            if key in obj:
                return obj.pop(key)
            raise PathError(f"Key '{key}' not found for deletion", path)
        elif isinstance(obj, (list, tuple)):
            idx = segments[0]
            if idx < 0: idx += len(obj)
            if 0 <= idx < len(obj):
                return obj.pop(idx)
            raise PathError(f"Index '{idx}' out of bounds for deletion", path)
        else:
            raise PathError("Cannot delete from scalar object", path)

    # Multi-segment deletion
    parent_segments = segments[:-1]
    final_segment = segments[-1]

    current = obj
    parent = None

    # 1. Traverse to the parent container
    for segment in parent_segments:
        if isinstance(segment, str):
            if not isinstance(current, Mapping) or segment not in current:
                raise PathError(f"Parent key '{segment}' not found for deletion", path)
            parent = current
            current = current[segment]
        elif isinstance(segment, int):
            if not isinstance(current, (list, tuple)):
                raise PathError("Parent index requires a Sequence", path)

            idx = segment
            if idx < 0: idx += len(current)

            if not (0 <= idx < len(current)):
                raise PathError(f"Parent index {segment} out of bounds for deletion", path)

            parent = current
            current = current[idx]
        else:
            raise PathError("Invalid segment type during parent traversal", path)

    # 2. Perform deletion on the parent container
    if isinstance(parent, Mapping):
        key = final_segment
        if key not in parent:
            raise PathError(f"Key '{key}' not found for deletion", path)
        return parent.pop(key)

    elif isinstance(parent, (list, tuple)):
        idx = final_segment
        if idx < 0: idx += len(parent)

        if not (0 <= idx < len(parent)):
            raise PathError(f"Index '{idx}' out of bounds for deletion", path)

        return parent.pop(idx)

    else:
        raise PathError("Cannot delete: Parent container is not a dict or list", path)


