            if len(rows_candidates[d]) == 1:
                return (rows_candidates[d][0][0], rows_candidates[d][0][1], d, 'hidden single in row')

    # Check Columns
    for c in range(9):
        cols_candidates = {d: [] for d in range(1, 10)}
        for r in range(9):
            if grid[r][c] == 0:
                for d in candidates_grid[r][c]:
                    cols_candidates[d].append((r, c))

        for d in range(1, 10):
            if len(cols_candidates[d]) == 1:
                return (cols_candidates[d][0][0], cols_candidates[d][0][1], d, 'hidden single in column')

    # Check Boxes
    for box_id in range(9):
        start_row = (box_id // 3) * 3
        start_col = (box_id % 3) * 3

        boxes_candidates = {d: [] for d in range(1, 10)}

        # Collect candidates for all empty cells in this box
        for r_offset in range(3):
            for c_offset in range(3):
                r = start_row + r_offset
                c = start_col + c_offset
                if grid[r][c] == 0:
                    for d in candidates_grid[r][c]:
                        boxes_candidates[d].append((r, c))

        # Find hidden single digit within the box
        for d in range(1, 10):
            if len(boxes_candidates[d]) == 1:
                r, c = boxes_candidates[d][0]
                return (r, c, d, 'hidden single in box')

    return None


# --- Difficulty Function (New) ---

def difficulty(grid: Grid) -> Optional[Dict[str, int]]:
    """
    Calculates difficulty by iteratively applying hints until the grid is solved 
    or no further deterministic steps can be found.
    """
    working_grid = copy.deepcopy(grid)
    naked_steps = 0
    hidden_steps = 0

    while True:
        if all(working_grid[r][c] != 0 for r in range(9) for c in range(9)):
            # Grid is complete
            if is_valid(working_grid):
                return {'naked': naked_steps, 'hidden': hidden_steps}
            else:
                # Should not happen if starting grid was valid and hints were correct
                return None 

        try:
            # Hint function returns (r, c, digit, reason) or None
            hint_result = hint(working_grid)
        except ValueError:
            # If hint fails due to invalidity (which should only happen if the initial grid was bad)
            return None

        if hint_result is None:
            # No more deterministic steps found
            if not all(working_grid[r][c] != 0 for r in range(9) for c in range(9)):
                # Not complete, and no more hints => requires guessing (hard/impossible)
                return None
            # If complete, loop condition handles return

        r, c, digit, reason = hint_result

        # Apply the found hint
        working_grid[r][c] = digit

        # Tally step type
        if 'naked' in reason:
            naked_steps += 1
        elif 'hidden' in reason:
            hidden_steps += 1

