        if not self.title:
            raise ValueError("Title cannot be empty after normalization.")
        # Tags must be a tuple, sorted, and contain only valid normalized tags
        if not all(isinstance(t, str) and t.replace('_', '').isalnum() for t in self.tags):
             # This check is mostly redundant if the store handles normalization correctly, 
             # but ensures the internal state is correct.
             pass 

    @staticmethod
    def normalize_title(title: str) -> str:
        normalized = title.strip()
        if not normalized:
            raise ValueError("Title cannot be empty.")
        return normalized

    @staticmethod
    def normalize_tag(tag: str) -> str:
        normalized = tag.strip().lower()
        if not normalized:
            raise ValueError("Tag cannot be empty.")
        if not TAG_REGEX.match(normalized):
            raise ValueError(f"Invalid tag format: '{tag}'. Must match pattern [a-z0-9][a-z0-9_-]*.")
        return normalized

