        return {
            "id": self.id,
            "title": self.title,
            "tags": list(self.tags),
            "done": self.done
        }

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> 'Task':
        required_keys = ["id", "title", "tags", "done"]
        if not all(key in d for key in required_keys):
            raise ValueError(f"Missing required key in task dictionary. Found: {d.keys()}")

        try:
            task_id = int(d["id"])
            title_str = str(d["title"])
            tags_list = d["tags"]
            done_val = bool(d["done"])
        except (TypeError, ValueError) as e:
            raise ValueError(f"Type mismatch in task dictionary: {e}")

        if not isinstance(tags_list, list):
            raise ValueError("Tags must be a list.")
        if not all(isinstance(t, str) for t in tags_list):
            raise ValueError("All tags must be strings.")

        # Normalize title and tags upon loading
        try:
            normalized_title = cls.normalize_title(title_str)
        except ValueError as e:
            raise ValueError(f"Invalid title: {e}")

        normalized_tags = []
        for tag in tags_list:
            try:
                normalized_tags.append(cls.normalize_tag(tag))
            except ValueError as e:
                raise ValueError(f"Invalid tag found: {e}")

        # Deduplicate and sort tags
        unique_sorted_tags = sorted(list(set(normalized_tags)))

        return cls(
            id=task_id,
            title=normalized_title,
            tags=tuple(unique_sorted_tags),
            done=done_val
        )
