import json
import os
from pathlib import Path
from typing import List, Optional, Tuple, Union
from .model import Task, Task as TaskModel
from .model import Task as TaskType

class StoreError(Exception):
    pass

class TodoStore:
    def __init__(self, path: Union[str, Path]):
        self.path = Path(path)
        self._data: Optional[dict] = None
        self._next_id: int = 1
        self._tasks: dict[int, TaskType] = {}
        self._load()

    def _load(self):
        if not self.path.exists():
            self._data = {"version": 1, "next_id": 1, "tasks": []}
            self._next_id = 1
            self._tasks = {}
            return

        try:
            with open(self.path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except json.JSONDecodeError:
            raise StoreError(f"File is not valid JSON: {self.path}")
        except IOError as e:
            raise StoreError(f"Could not read store file: {e}")

        if data.get("version") != 1:
            raise StoreError(f"Unsupported store version: {data.get('version')}")

        try:
            self._next_id = data.get("next_id", 1)
            tasks_list_dicts = data.get("tasks", [])
        except TypeError:
            raise StoreError("Store structure is missing 'next_id' or 'tasks' list.")

        self._tasks = {}
        loaded_ids = set()

        # 1. Validate tasks and load them
        for task_dict in tasks_list_dicts:
            try:
                task = TaskType.from_dict(task_dict)
            except ValueError as e:
                raise StoreError(f"Task data invalid: {e}")

            if task.id in loaded_ids:
                raise StoreError(f"Duplicate task ID found: {task.id}")

            # Check ID consistency (must be less than next_id if next_id was derived from tasks)
            if task.id >= self._next_id:
                # This catches cases where tasks might be out of sequence relative to next_id
                 raise StoreError(f"Task ID {task.id} is too high relative to expected next_id {self._next_id}")

            self._tasks[task.id] = task
            loaded_ids.add(task.id)

        # 2. Determine the actual next_id based on loaded tasks
        if loaded_ids:
            max_id = max(loaded_ids)
            self._next_id = max_id + 1
        else:
            self._next_id = 1


    def _save(self):
        tasks_list = [task.to_dict() for task in self._tasks.values()]

        # Ensure tasks are ordered by ID before saving
        ordered_tasks = sorted(tasks_list, key=lambda d: d['id'])

        data_to_save = {
            "version": 1,
            "next_id": self._next_id,
            "tasks": ordered_tasks
        }

        temp_path = self.path.with_suffix('.tmp')

        try:
            with open(temp_path, 'w', encoding='utf-8') as f:
                json.dump(data_to_save, f, indent=4)

            # Atomically replace the old file
            os.replace(temp_path, self.path)
        except IOError as e:
            # Clean up temp file if replacement fails
            if temp_path.exists():
                os.remove(temp_path)
            raise StoreError(f"Failed to write store file: {e}")


    def add(self, title: str, tags: Tuple[str, ...] = ()) -> TaskType:
        normalized_title = TaskType.normalize_title(title)

        normalized_tags = []
        for tag in tags:
            try:
                normalized_tags.append(TaskType.normalize_tag(tag))
            except ValueError:
                # This case is handled by the caller if we wanted strict enforcement, 
                # but here we treat it as an error during internal operation if the CLI didn't catch it.
                raise ValueError(f"Invalid tag provided: {tag}")

        # Deduplicate and sort tags
        unique_sorted_tags = tuple(sorted(set(normalized_tags)))

        new_task = TaskType(
            id=self._next_id,
            title=normalized_title,
            tags=unique_sorted_tags,
            done=False
        )

        self._tasks[new_task.id] = new_task
        self._next_id += 1
        self._save()
        return new_task

    def get(self, task_id: int) -> TaskType:
        if task_id not in self._tasks:
            raise KeyError(f"No task with id {task_id}")
        return self._tasks[task_id]

    def list(self, status: str = "open", tags: Tuple[str, ...] = ()) -> List[TaskType]:
        if status not in ["open", "done", "all"]:
            raise ValueError("Invalid status. Must be 'open', 'done', or 'all'.")

        filtered_tasks: List[TaskType] = []

        target_status = {"open": False, "done": True, "all": True}.get(status, False)

        for task in self._tasks.values():
            if task.done != target_status and status != "all":
                continue

            # Tag matching logic: must have ALL provided tags
            if tags:
                tag_match = True
                for req_tag in tags:
                    try:
                        normalized_req_tag = TaskType.normalize_tag(req_tag)
                    except ValueError:
                        # Should not happen if CLI is correct, but defensive coding
                        raise ValueError("Invalid tag provided during listing.")

                    if normalized_req_tag not in task.tags:
                        tag_match = False
                        break
                if not tag_match:
                    continue

            filtered_tasks.append(task)

        # Return in increasing ID order
        return sorted(filtered_tasks, key=lambda t: t.id)

    def mark_done(self, task_id: int) -> TaskType:
        if task_id not in self._tasks:
            raise KeyError(f"No task with id {task_id}")

        task = self._tasks[task_id]
        if task.done:
            return task # No change

        # Since Task is frozen, we must replace it in the store
        updated_task = task.__class__(task.id, task.title, task.tags, done=True)
        self._tasks[task_id] = updated_task
        self._save()
        return updated_task

    def remove(self, task_id: int) -> TaskType:
        if task_id not in self._tasks:
            raise KeyError(f"No task with id {task_id}")

        task_to_remove = self._tasks[task_id]
        del self._tasks[task_id]
        self._save()
        return task_to_remove

    def edit(self, task_id: int, title: Optional[str] = None, add_tags: Tuple[str, ...] = (), remove_tags: Tuple[str, ...] = ()) -> TaskType:
        if task_id not in self._tasks:
            raise KeyError(f"No task with id {task_id}")

        original_task = self._tasks[task_id]

        # 1. Validate inputs before modification
        if title is not None:
            try:
                new_title = TaskType.normalize_title(title)
            except ValueError as e:
                raise ValueError(f"Invalid title: {e}")
        else:
            new_title = original_task.title

        # Validate add_tags
        validated_add_tags = []
        for tag in add_tags:
            try:
                normalized_tag = TaskType.normalize_tag(tag)
                validated_add_tags.append(normalized_tag)
            except ValueError:
                raise ValueError(f"Invalid tag in add_tags: {tag}")

        # 2. Apply changes to build new state
        current_tags_set = set(original_task.tags)

        # Remove specified tags
        for tag in remove_tags:
            try:
                normalized_tag = TaskType.normalize_tag(tag)
                current_tags_set.discard(normalized_tag)
            except ValueError:
                # Ignore invalid removal tags as per requirement
                pass 

        # Add new tags
        current_tags_set.update(validated_add_tags)

        # Recreate task (if title changed or tags changed)
        if new_title != original_task.title or current_tags_set != set(original_task.tags):

            new_tags_tuple = tuple(sorted(current_tags_set))

            updated_task = original_task.__class__(
                id=original_task.id,
                title=new_title,
                tags=new_tags_tuple,
                done=original_task.done
            )

            self._tasks[task_id] = updated_task
            self._save()
            return updated_task

        return original_task
