    for task_id in ids_to_mark:
        try:
            store.get(task_id)
        except KeyError:
            # Exit code 1: first missing ID
            print(f"error: no task with id {task_id}", file=sys.stderr)
            sys.exit(1)

    # If all exist, mark them all
    for task_id in ids_to_mark:
