    except SystemExit as e:
        # Catches SystemExit from argparse or manual exits (like in handlers)
        return e.code
    except Exception as e:
        # Catch any remaining unexpected errors
        print(f"error: An unexpected error occurred: {e}", file=sys.stderr)
        return 1


if __name__ == '__main__':
    # This block allows direct execution for testing, though the requirement is python -m todo.cli
