        except IOError as e:
            raise StoreError(f"Could not read store file: {e}")

        version = data.get("version")
        if version not in [1, 2]:
            raise StoreError(f"Unsupported store version: {version}. Only versions 1 and 2 are supported.")

        try:
            self._next_id = data.get("next_id", 1)
            tasks_list_dicts = data.get("tasks", [])
        except TypeError:
            raise StoreError("Store structure is missing 'next_id' or 'tasks' list.")

        self._tasks = {}
        loaded_ids = set()

        # 1. Validate tasks and load them
        for task_dict in tasks_list_dicts:
            try:
                task = TaskType.from_dict(task_dict)
            except ValueError as e:
                raise StoreError(f"Task data invalid: {e}")

            if task.id in loaded_ids:
                raise StoreError(f"Duplicate task ID found: {task.id}")

            if task.id >= self._next_id:
                 raise StoreError(f"Task ID {task.id} is too high relative to expected next_id {self._next_id}")

            self._tasks[task.id] = task
            loaded_ids.add(task.id)

        # 2. Determine the actual next_id based on loaded tasks
        if loaded_ids:
            max_id = max(loaded_ids)
            self._next_id = max_id + 1
        else:
            self._next_id = 1

        # If V1, prepare to upgrade on next save
        if version == 1:
            self._data = {"version": 2, "next_id": self._next_id, "tasks": []}


    def _save(self):
        tasks_list = [task.to_dict() for task in self._tasks.values()]

        # Ensure tasks are ordered by ID before saving
        ordered_tasks = sorted(tasks_list, key=lambda d: d['id'])

        # If we loaded V1, ensure the structure is V2 before saving
        current_version = 2 if self._data and self._data.get("version") == 2 else 1

        data_to_save = {
            "version": 2, # Always write as V2
            "next_id": self._next_id,
            "tasks": ordered_tasks
        }

        temp_path = self.path.with_suffix('.tmp')

        try:
            with open(temp_path, 'w', encoding='utf-8') as f:
                json.dump(data_to_save, f, indent=4)

            os.replace(temp_path, self.path)
        except IOError as e:
            if temp_path.exists():
                os.remove(temp_path)
            raise StoreError(f"Failed to write store file: {e}")


    def add(self, title: str, tags: Tuple[str, ...] = (), priority: str = "normal", due: Optional[date] = None) -> TaskType:
        # Validation handled by model methods, which raise ValueError on bad input
        normalized_title = TaskType.normalize_title(title)

        normalized_tags = []
        for tag in tags:
            normalized_tags.append(TaskType.normalize_tag(tag))

        unique_sorted_tags = tuple(sorted(set(normalized_tags)))

        normalized_priority = TaskType.normalize_priority(priority)

        # Handle due date conversion if provided as date object
        final_due = due if isinstance(due, date) else None

        new_task = TaskType(
            id=self._next_id,
            title=normalized_title,
            tags=unique_sorted_tags,
            done=False,
            priority=normalized_priority,
            due=final_due
        )

        self._tasks[new_task.id] = new_task
        self._next_id += 1
        self._save()
        return new_task

    def get(self, task_id: int) -> TaskType:
        if task_id not in self._tasks:
            raise KeyError(f"No task with id {task_id}")
        return self._tasks[task_id]

    def list(self, status: str = "open", tags: Tuple[str, ...] = (), overdue: bool = False, today: Optional[date] = None, sort: str = "id") -> List[TaskType]:
        if status not in ["open", "done", "all"]:
            raise ValueError("Invalid status. Must be 'open', 'done', or 'all'.")
        if sort not in ["id", "priority", "due"]:
            raise ValueError("Invalid sort option. Must be 'id', 'priority', or 'due'.")

        if overdue and today is None:
            raise ValueError("The 'overdue' filter requires the 'today' argument.")

        filtered_tasks: List[TaskType] = []

        target_status_match = (status == "all") or (status == "open" and not task.done) or (status == "done" and task.done)

        for task in self._tasks.values():

            # 1. Status and Tag filtering
            if not target_status_match:
                continue

            if tags:
                tag_match = True
                for req_tag in tags:
                    try:
                        normalized_req_tag = TaskType.normalize_tag(req_tag)
                    except ValueError:
                        raise ValueError("Invalid tag provided during listing.")

                    if normalized_req_tag not in task.tags:
                        tag_match = False
                        break
                if not tag_match:
                    continue

            # 2. Overdue filtering (Only applies to open tasks)
            if overdue and task.done == False and today is not None:
                if task.due is None or task.due >= today:
                    continue # Not overdue

            filtered_tasks.append(task)

        # 3. Sorting Logic
        if sort == "id":
            sorted_tasks = sorted(filtered_tasks, key=lambda t: t.id)
        elif sort == "priority":
            # High (1), Normal (2), Low (3)
            priority_map = {"high": 1, "normal": 2, "low": 3}
            # Sort by priority value, then by ID as tie-breaker
            sorted_tasks = sorted(filtered_tasks, key=lambda t: (priority_map[t.priority], t.id))
        elif sort == "due":
            # Primary sort: due date (None last). Secondary sort: ID.
            def due_sort_key(t: TaskType):
                # Assign a very large date for tasks with no due date to push them to the end
                return (t.due if t.due else date.max, t.id)
            sorted_tasks = sorted(filtered_tasks, key=due_sort_key)
        else:
            # Should be unreachable due to check above
            sorted_tasks = filtered_tasks 

        return sorted_tasks

    def mark_done(self, task_id: int) -> TaskType:
        if task_id not in self._tasks:
            raise KeyError(f"No task with id {task_id}")

        task = self._tasks[task_id]
        if task.done:
            return task

        # Create new immutable task instance with done=True
        updated_task = task.__class__(task.id, task.title, task.tags, done=True, priority=task.priority, due=task.due)
        self._tasks[task_id] = updated_task
        self._save()
        return updated_task

    def remove(self, task_id: int) -> TaskType:
        if task_id not in self._tasks:
            raise KeyError(f"No task with id {task_id}")

        task_to_remove = self._tasks[task_id]
        del self._tasks[task_id]
        self._save()
        return task_to_remove

    def edit(self, task_id: int, title: Optional[str] = None, add_tags: Tuple[str, ...] = (), remove_tags: Tuple[str, ...] = (), priority: Optional[str] = None, due: Optional[date] = None, clear_due: bool = False) -> TaskType:
        if task_id not in self._tasks:
            raise KeyError(f"No task with id {task_id}")

        original_task = self._tasks[task_id]

        # 1. Check for conflicting edits (due vs clear_due)
        if due is not None and clear_due:
            raise ValueError("Cannot specify a new due date while requesting to clear the due date.")

        # 2. Prepare new values (only change if provided/requested)
        new_title = title if title is not None else original_task.title

        new_priority = priority if priority is not None else original_task.priority

        new_due: Optional[date] = None
        if clear_due:
            new_due = None
        elif due is not None:
            new_due = due
        else:
            new_due = original_task.due

        # 3. Tag management (unchanged logic)
        current_tags_set = set(original_task.tags)

        for tag in remove_tags:
            try:
                normalized_tag = TaskType.normalize_tag(tag)
                current_tags_set.discard(normalized_tag)
            except ValueError:
                pass 

        validated_add_tags = []
        for tag in add_tags:
            try:
                normalized_tag = TaskType.normalize_tag(tag)
                validated_add_tags.append(normalized_tag)
            except ValueError:
                raise ValueError(f"Invalid tag in add_tags: {tag}")
        current_tags_set.update(validated_add_tags)
        new_tags_tuple = tuple(sorted(current_tags_set))


        # 4. Determine if an update is necessary
        changed = (
            new_title != original_task.title or
            new_priority != original_task.priority or
            new_due != original_task.due or
            new_tags_tuple != original_task.tags
        )

        if not changed:
            return original_task

        # Create and store the updated task
        updated_task = original_task.__class__(
            id=original_task.id,
            title=new_title,
            tags=new_tags_tuple,
            done=original_task.done,
            priority=new_priority,
            due=new_due
        )

        self._tasks[task_id] = updated_task
        self._save()
        return updated_task
