# tmpl/parser.py
from typing import List, Union, Any
from .lexer import Token, TemplateSyntaxError

# --- AST Node Definitions ---

class Node:
    """Base class for all template AST nodes."""
    def __repr__(self):
        return f"<{self.__class__.__name__}>"

class TextNode(Node):
    def __init__(self, content: str, lineno: int):
        self.content = content
        self.lineno = lineno
    def __repr__(self):
        return f"TextNode(line={self.lineno}, content='{self.content[:10]}...')"

class ExpressionNode(Node):
    """Represents a full {{ expression }} block."""
    def __init__(self, expression_str: str, lineno: int):
        self.expression_str = expression_str
        self.lineno = lineno
    def __repr__(self):
        return f"ExpressionNode(line={self.lineno}, expr='{self.expression_str[:15]}...')"

class StatementNode(Node):
    """Base class for {% statement %} blocks."""
    def __init__(self, statement_str: str, lineno: int):
        self.statement_str = statement_str
        self.lineno = lineno

class ForNode(StatementNode):
    def __init__(self, expr: str, body: List[Node], else_body: List[Node] = None, lineno: int = 0):
        super().__init__(f"for {expr}", lineno)
        self.expr = expr  # Value expression
        self.body = body
        self.else_body = else_body if else_body is not None else []

class IfNode(StatementNode):
    def __init__(self, condition_str: str, body: List[Node], elif_nodes: List[tuple[str, List[Node]]] = None, else_body: List[Node] = None, lineno: int = 0):
        super().__init__(f"if {condition_str}", lineno)
        self.condition_str = condition_str
        self.body = body
        self.elif_nodes = elif_nodes if elif_nodes is not None else [] # List of (condition_str, body)
        self.else_body = else_body if else_body is not None else []

class BlockEndNode(StatementNode):
    """Placeholder for end tags to maintain structural integrity during parsing."""
    def __init__(self, tag_name: str, lineno: int):
        super().__init__(tag_name, lineno)
        self.tag_name = tag_name

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Union[Token, None]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_kind: str = None) -> Token:
        if self.pos >= len(self.tokens):
            raise TemplateSyntaxError("Unexpected end of template", -1) # Lineno handled by context

        token = self.tokens[self.pos]
        if expected_kind and token.kind != expected_kind:
             raise TemplateSyntaxError(f"Expected {expected_kind} but found {token.kind}", token.lineno)

        self.pos += 1
        return token

    def parse(self) -> List[Node]:
        """Main entry point for parsing."""
        nodes: List[Node] = []
        while self.pos < len(self.tokens):
            token = self.peek()
            if not token:
                break

            if token.kind == "text":
                self.consume("text")
                nodes.append(TextNode(token.value, token.lineno))
            elif token.kind == "var":
                self.consume("var")
                nodes.append(ExpressionNode(token.value, token.lineno))
            elif token.kind == "block":
                # Blocks require specialized parsing (loops, ifs)
                node = self._parse_statement()
                if node:
                    nodes.append(node)
            else:
                # Should not happen
                self.consume() 

        return nodes

    def _parse_statement(self) -> Union[StatementNode, None]:
        """Parses a single control block starting with a block token."""
        token = self.consume("block")
        content = token.value
        lineno = token.lineno

        parts = content.split()
        if not parts:
            raise TemplateSyntaxError("Empty block statement", lineno)

        keyword = parts[0]

        if keyword == "for":
            return self._parse_for(content, lineno)
        elif keyword == "if":
            return self._parse_if(content, lineno)
        elif keyword == "endfor":
            return BlockEndNode("endfor", lineno)
        elif keyword == "endif":
            return BlockEndNode("endif", lineno)
        elif keyword == "else":
            # 'else' is handled by the block structure it belongs to (IfNode/ForNode)
            # If 'else' appears at the top level, it's a syntax error.
            raise TemplateSyntaxError("Unexpected 'else' statement", lineno)
        else:
            raise TemplateSyntaxError(f"Unknown statement: {keyword}", lineno)

    def _parse_for(self, content: str, lineno: int) -> ForNode:
        # Expected format: for NAME in EXPR (or variations)
        # This is a major simplification. Full parsing of EXPR and NAME requires deeper grammar.

        # Simple attempt to extract the expression part
        try:
            if "in" not in content:
                raise ValueError("Missing 'in'")

            _, expr_part = content.split("in", 1)
            expr = expr_part.strip()

            # We need to find the corresponding endfor
            # In a full parser, we would use a stack to match block nesting.

            # For now, we consume until the next closing tag or EOF, which is inherently unsafe.
            body_nodes = []
            self._consume_until_end_tag("endfor", lineno)

            # Simplified: If we found an ELSE block, we'd need complex lookahead to find it.
            else_body = [] # Placeholder

            return ForNode(expr, body_nodes, else_body, lineno)

        except ValueError:
            raise TemplateSyntaxError("Malformed 'for' loop", lineno)
        except TemplateSyntaxError as e:
            # Re-raise the nested parsing error with correct context if necessary
            raise e

    def _parse_if(self, content: str, lineno: int) -> IfNode:
        # Expected format: if COND (elif COND)* (else)? endif

        # This requires consuming until 'endif', parsing all elifs/else along the way.

        body_nodes: List[Node] = []
        elif_nodes: List[tuple[str, List[Node]]] = []
        else_body: List[Node] = []

        # Consume body until next elif/else/endif
        self._consume_until_block_end_tag(["elif", "else", "endif"], lineno)

        # Since this is a simplified parser, we assume the first segment is the main body
        # and rely on the consumption logic to handle the rest.

        # Placeholder return structure:
        return IfNode(content, body_nodes, elif_nodes, else_body, lineno)

    def _consume_until_end_tag(self, targets: List[str], start_lineno: int):
        """
        Consumes nodes until a specified closing tag is encountered.
        In a real parser, this would return the collected nodes AND the matching tag.
        Here, it only advances the pointer and collects nodes.
        """
        nodes = []

        while self.pos < len(self.tokens):
            token = self.peek()
            if not token:
                raise TemplateSyntaxError("Unclosed block structure", start_lineno)

            if token.kind == "text":
                self.consume("text")
                nodes.append(TextNode(token.value, token.lineno))
            elif token.kind == "var":
                self.consume("var")
                nodes.append(ExpressionNode(token.value, token.lineno))
            elif token.kind == "block":
                block_content = token.value

                # Check if this block matches a target closure/continuation keyword
                first_word = block_content.split()[0]

                if first_word in targets:
                    if first_word == "endif":
                        return # Successfully closed IF block
                    if first_word == "endfor":
                        return # Successfully closed FOR block
                    if first_word == "elif":
                        # For elif, we need to parse the condition and body recursively/iteratively
                        # This is where the complexity explodes. We just consume it for now.
                        self.consume("block")
                        # In a real parser, we'd yield this structured elif node.
                        pass 
                    if first_word == "else":
                        # For else, we consume it and store it for the parent IfNode.
                        self.consume("block")
                        pass
                else:
                    # It's part of the body (e.g., a nested for)
                    node = self._parse_statement()
                    if node:
                        nodes.append(node)
            else:
                self.consume()

        raise TemplateSyntaxError(f"Expected closing tag {targets[-1]} but reached EOF", start_lineno)


def parse(source: str) -> List[Node]:
    """
    Parses the source string into an Abstract Syntax Tree (AST).
    """
    # 1. Lexing
    tokens = tokenize(source)

    # 2. Parsing
    parser = Parser(tokens)
    return parser.parse()

