            except ValueError:
                # Should not happen if part.isdigit() is true, but defensive coding.
                return None
        else:
            # Name segment: Mapping key or Object attribute
            if isinstance(current_value, collections.abc.Mapping):
                # Look up key as string
                if str(part) in current_value:
                    current_value = current_value[str(part)]
                else:
