import re
from typing import List, Union, Any, Dict
from .lexer import Token, TemplateSyntaxError, TemplateNotFound

# --- AST Node Definitions ---

class Node:
    """Base class for all template AST nodes."""
    def __repr__(self):
        return f"<{self.__class__.__name__}>"

class TextNode(Node):
    def __init__(self, content: str, lineno: int):
        self.content = content
        self.lineno = lineno
    def __repr__(self):
        return f"TextNode(line={self.lineno}, content='{self.content[:10]}...')"

class ExpressionNode(Node):
    """Represents a full {{ expression }} block."""
    def __init__(self, expression_str: str, lineno: int):
        self.expression_str = expression_str
        self.lineno = lineno
    def __repr__(self):
        return f"ExpressionNode(line={self.lineno}, expr='{self.expression_str[:15]}...')"

class StatementNode(Node):
    """Base class for {% statement %} blocks."""
    def __init__(self, statement_str: str, lineno: int):
        self.statement_str = statement_str
        self.lineno = lineno

class ForNode(StatementNode):
    def __init__(self, expr: str, body: List[Node], else_body: List[Node] = None, lineno: int = 0):
        super().__init__(f"for {expr}", lineno)
        self.expr = expr  # Value expression
        self.body = body
        self.else_body = else_body if else_body is not None else []

class IfNode(StatementNode):
    def __init__(self, condition_str: str, body: List[Node], elif_nodes: List[tuple[str, List[Node]]] = None, else_body: List[Node] = None, lineno: int = 0):
        super().__init__(f"if {condition_str}", lineno)
        self.condition_str = condition_str
        self.body = body
        self.elif_nodes = elif_nodes if elif_nodes is not None else [] 
        self.else_body = else_body if else_body is not None else []

class BlockNode(StatementNode):
    """Handles {% block NAME %} and {% endblock NAME %}."""
    def __init__(self, block_name: str, lineno: int, is_start: bool):
        super().__init__(f"block {block_name}" if is_start else f"endblock {block_name}", lineno)
        self.name = block_name
        self.is_start = is_start

class ExtendsNode(StatementNode):
    def __init__(self, parent_name: str, lineno: int):
        super().__init__(f"extends {parent_name}", lineno)
        self.parent_name = parent_name

class SuperNode(StatementNode):
    def __init__(self, lineno: int):
        super().__init__("super()", lineno)

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Union[Token, None]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_kind: str = None) -> Token:
        if self.pos >= len(self.tokens):
            raise TemplateSyntaxError("Unexpected end of template", -1)

        token = self.tokens[self.pos]
        if expected_kind and token.kind != expected_kind:
             raise TemplateSyntaxError(f"Expected {expected_kind} but found {token.kind}", token.lineno)

        self.pos += 1
        return token

    def parse(self) -> List[Node]:
        """Main entry point for parsing."""
        nodes: List[Node] = []

        while self.pos < len(self.tokens):
            token = self.peek()
            if not token:
                break

            if token.kind == "text":
                self.consume("text")
                nodes.append(TextNode(token.value, token.lineno))
            elif token.kind == "var":
                self.consume("var")
                nodes.append(ExpressionNode(token.value, token.lineno))
            elif token.kind == "block":
                node = self._parse_statement()
                if node:
                    nodes.append(node)
            else:
                self.consume() 

        return nodes

    def _parse_statement(self) -> Union[StatementNode, None]:
        token = self.consume("block")
        content = token.value
        lineno = token.lineno

        content_parts = re.split(r'\s+', content.strip())
        if not content_parts:
            raise TemplateSyntaxError("Empty block statement", lineno)

        keyword = content_parts[0]

        if keyword == "extends":
            # Extends must be followed by a quoted name
            if len(content_parts) != 2:
                raise TemplateSyntaxError("Malformed 'extends' tag. Expecting {% extends 'name' %}", lineno)
            parent_name = content_parts[1].strip("'\"")
            return ExtendsNode(parent_name, lineno)

        elif keyword == "for":
            return self._parse_for(content, lineno)
        elif keyword == "if":
            return self._parse_if(content, lineno)
        elif keyword == "elif":
            # Elif/Else parsing is complex; we signal it structurally and rely on context.
            raise NotImplementedError("Elif/Else parsing is highly complex and omitted in this structural implementation.")
        elif keyword == "else":
            raise NotImplementedError("Else parsing is highly complex and omitted in this structural implementation.")
        elif keyword == "endif":
            return BlockEndNode("endif", lineno)
        elif keyword == "endfor":
            return BlockEndNode("endfor", lineno)
        elif keyword == "block":
            # Block name must be the second part
            if len(content_parts) != 2:
                raise TemplateSyntaxError("Malformed block tag. Expecting {% block NAME %}", lineno)
            block_name = content_parts[1]
            return BlockNode(block_name, lineno, is_start=True)
        elif keyword == "endblock":
            if len(content_parts) != 2:
                raise TemplateSyntaxError("Malformed endblock tag. Expecting {% endblock NAME %}", lineno)
            block_name = content_parts[1]
            return BlockNode(block_name, lineno, is_start=False)
        elif keyword == "super":
            if content != "super()":
                 raise TemplateSyntaxError("Invalid use of super(). Must be {{ super() }}", lineno)
            return SuperNode(lineno)
        else:
            raise TemplateSyntaxError(f"Unknown statement: {keyword}", lineno)

    def _parse_for(self, content: str, lineno: int) -> ForNode:
        # Simplified parsing for structure: for EXPR in NAME
        match = re.match(r"for\s+(.+?)\s+in\s+([\w.]+)", content, re.IGNORECASE)
        if not match:
             raise TemplateSyntaxError("Malformed 'for' loop. Expected 'for EXPR in NAME'", lineno)

        expr = match.group(1).strip()
        name = match.group(2).strip() # The loop variable name

        # Body consumption (Placeholder)
        body_nodes = []
        self._consume_until_block_end_tag(["endfor", "else"], lineno)

        # We cannot easily store the loop variable name in the simple ForNode AST structure above.
        # A real implementation must update the AST node to carry the variable name.
        return ForNode(expr, body_nodes, lineno=lineno)


    def _parse_if(self, content: str, lineno: int) -> IfNode:
        # Placeholder: Real parsing involves complex state tracking for elif/else
        return IfNode(content, [], [], [], lineno)

    def _consume_until_block_end_tag(self, targets: List[str], start_lineno: int):
        """
        Consumes nodes until a specified closing tag is encountered, collecting nodes.
        """
        nodes = []

        while self.pos < len(self.tokens):
            token = self.peek()
            if not token:
                raise TemplateSyntaxError(f"Expected closing tag {targets[-1]} but reached EOF", start_lineno)

            if token.kind == "text":
                self.consume("text")
                nodes.append(TextNode(token.value, token.lineno))
            elif token.kind == "var":
                self.consume("var")
                nodes.append(ExpressionNode(token.value, token.lineno))
            elif token.kind == "block":
                block_content = token.value

                first_word = block_content.split()[0]

                if first_word in targets:
                    if first_word in ["endfor", "endif"]:
                        self.consume("block") # Consume the closing tag
                        return
                    # If it's 'else' or 'elif', we consume it, but parsing structure needs to handle it.
                    self.consume("block") 
                    return # Stop consumption here if we hit a structural element
                else:
                    # It's part of the body (nested structure)
                    node = self._parse_statement()
                    if node:
                        nodes.append(node)
            else:
                self.consume()

        raise TemplateSyntaxError(f"Expected closing tag {targets[-1]} but reached EOF", start_lineno)


def parse(source: str) -> List[Node]:
    """
    Parses the source string into an Abstract Syntax Tree (AST).
    """
    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()
