from __future__ import annotations
from dataclasses import dataclass, field
from typing import List, Optional, Any, Callable, Dict, Union, Tuple

# --- Exceptions ---

class MachineError(Exception):
    """Base exception for FSM machine errors."""
    pass

class InvalidTransition(MachineError):
    """Raised when no transition matches the event from the current state."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"InvalidTransition: No transition for event '{event}' in state '{state}'")

class GuardRejected(MachineError):
    """Raised when all applicable transitions for an event are rejected by their guards."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"GuardRejected: All transitions for event '{event}' in state '{state}' were rejected by guards")

# --- Data Classes ---

@dataclass(frozen=True)
class State:
    name: str
    on_enter: Optional[Callable[['Machine', 'Event'], None]] = None
    on_exit: Optional[Callable[['Machine', 'Event'], None]] = None

@dataclass(frozen=True)
class Transition:
    event: str
    source: Union[str, List[str], Tuple[str, ...]]
    target: Optional[str]
    guard: Optional[Callable[['Machine', 'Event'], bool]] = None
    action: Optional[Callable[['Machine', 'Event'], None]] = None

@dataclass(frozen=True)
class Event:
    name: str
    source: str
    target: str
    data: Dict[str, Any]

# --- Machine ---

class Machine:
    """
    A Finite State Machine implementation.
    """
    def __init__(self, 
                 states: Union[List[State], List[str]], 
                 transitions: List[Transition], 
                 initial: str, 
                 context: Optional[Any] = None):

        self._initial_state = initial
        self._transitions = transitions
        self._state_definitions: Dict[str, State] = {}
        self._state_names: Dict[str, State] = {}
        self._listeners: List[Callable[['Machine', 'Event', str, str], None]] = []
        self._is_firing = False

        self.context = context
        self.history: List[Tuple[str, str, str]] = []

        self._setup_states(states)
        self._validate_initial_state()
        self._validate_transitions()

        self.state = initial

    def _setup_states(self, states_input: Union[List[State], List[str]]):
        """Converts state definitions to internal State objects."""
        state_map = {}
        for item in states_input:
            if isinstance(item, str):
                state_name = item
                self._state_definitions[state_name] = State(name=state_name)
            elif isinstance(item, State):
                self._state_definitions[item.name] = item
            else:
                raise TypeError("States must be State objects or strings.")

            if state_name in state_map:
                raise ValueError(f"Duplicate state name found: {state_name}")
            state_map[state_name] = True

    def _validate_initial_state(self):
        if self._initial_state not in self._state_definitions:
            raise ValueError(f"Initial state '{self._initial_state}' is not defined.")

    def _validate_transitions(self):
        defined_states = set(self._state_definitions.keys())

        for t in self._transitions:
            # Validate source
            source_candidates = []
            if isinstance(t.source, str):
                source_candidates = [t.source]
            elif isinstance(t.source, (list, tuple)):
                source_candidates = list(t.source)

            for src in source_candidates:
                if src not in defined_states and src != '*':
                    raise ValueError(f"Transition source '{src}' references undefined state.")

            # Validate target
            if t.target is not None:
                if t.target not in defined_states:
                    raise ValueError(f"Transition target '{t.target}' references undefined state.")

    def fire(self, event_name: str, **data: Any) -> str:
        """
        Processes an event, updates the state, and runs associated hooks.
        """
        if self._is_firing:
            raise MachineError("Cannot fire: Machine is already executing a fire call.")

        self._is_firing = True

        # 1. Find candidates
        candidates: List[Transition] = []
        current_state_name = self.state

        for t in self._transitions:
            if t.event != event_name:
                continue

            source_match = False

            if isinstance(t.source, str):
                if t.source == '*' or t.source == current_state_name:
                    source_match = True
            elif isinstance(t.source, (list, tuple)):
                if any(src == '*' or src == current_state_name for src in t.source):
                    source_match = True

            if source_match:
                candidates.append(t)

        if not candidates:
            self._is_firing = False
            raise InvalidTransition(state=current_state_name, event=event_name)

        # 2. Prepare Event structure (sharing data dict)
        event = Event(
            name=event_name, 
            source=current_state_name, 
            target=candidates[0].target if candidates[0].target else current_state_name,
            data=data
        )

        # 3. Evaluate guards
        chosen_transition: Optional[Transition] = None
        for t in candidates:
            can_proceed = True
            if t.guard:
                try:
                    if not t.guard(self, event):
                        can_proceed = False
                except Exception as e:
                    # If guard throws, propagate immediately
                    self._is_firing = False
                    raise e

            if can_proceed:
                chosen_transition = t
                break

        if not chosen_transition:
            self._is_firing = False
            raise GuardRejected(state=current_state_name, event=event_name)

        # --- Transition Execution ---

        transition = chosen_transition
        source = current_state_name
        target = transition.target if transition.target is not None else source

        old_state = self.state

        try:
            # 4. Normal transition execution
            if transition.target is not None:
                # Exit hook of source state
                if self._state_definitions[source].on_exit:
                    self._state_definitions[source].on_exit(self, event)

                # Action hook of transition
                if transition.action:
                    transition.action(self, event)

                # State change
                self.state = target

                # Record history
                self.history.append((source, event_name, target))

                # Enter hook of target state
                if self._state_definitions[target].on_enter:
                    self._state_definitions[target].on_enter(self, event)
            else:
                # 5. Internal transition execution (target=None)
                if transition.action:
                    transition.action(self, event)

                # Record history
                self.history.append((source, event_name, source))
                # State remains the same

            # 4. Listener execution (runs after state change/internal action)
            for listener in self._listeners:
                listener(self, event, source, target)

            return self.state

        except Exception as e:
            # 6. Exception handling
            if hasattr(e, '__name__') and e.__name__ in ('GuardRejected', 'InvalidTransition'):
                # This should not happen if logic is correct, but defensive coding
                pass
            elif self.state == old_state and transition.target is not None:
                # If state didn't change (e.g., exception in guard/action), roll back state if needed, 
                # but since we only change state *after* guard/action pass, we only need to ensure
                # history/state are clean if the exception happened *before* state update.
                # In this design, if an exception occurs after state update (on_enter/listener),
                # the state change sticks. If it occurs before (action/on_exit), it doesn't.
                # Since the state change only happens *after* action, we revert history if needed.
                if transition.target is not None:
                    self.history.pop() 

                # State remains old_state if exception occurred before state update
                self.state = old_state

            # Re-raise the exception
            self._is_firing = False
            raise e
        finally:
            self._is_firing = False

    def can_fire(self, event_name: str, **data: Any) -> bool:
        """Checks if a transition is possible without changing state or running complex hooks."""
        current_state_name = self.state

        candidates: List[Transition] = []
        for t in self._transitions:
            if t.event != event_name:
                continue

            source_match = False
            if isinstance(t.source, str):
                if t.source == '*' or t.source == current_state_name:
                    source_match = True
            elif isinstance(t.source, (list, tuple)):
                if any(src == '*' or src == current_state_name for src in t.source):
                    source_match = True

            if source_match:
                candidates.append(t)

        if not candidates:
            return False

        for t in candidates:
            if t.guard is None:
                return True
            try:
                # Guards must be side-effect free, so we trust this call.
                if t.guard(self, Event(event_name, current_state_name, "", data)):
                    return True
            except Exception:
                # If guard fails due to exception, we treat it as rejection for can_fire's purpose
                pass 

        return False

    def available_events(self) -> List[str]:
        """Returns sorted, de-duplicated names of events applicable from the current state."""
        current_state_name = self.state
        applicable_events = set()

        for t in self._transitions:
            if t.event == 'internal': continue # Skip internal events for this view

            source_match = False
            if isinstance(t.source, str):
                if t.source == '*' or t.source == current_state_name:
                    source_match = True
            elif isinstance(t.source, (list, tuple)):
                if any(src == '*' or src == current_state_name for src in t.source):
                    source_match = True

            if source_match:
                applicable_events.add(t.event)

        return sorted(list(applicable_events))

    def on_transition(self, listener: Callable[['Machine', 'Event', str, str], None]):
        """Adds a listener hook that runs after a transition completes."""
        self._listeners.append(listener)

    def reset(self):
        """Resets the machine state and history without running hooks."""
        self.state = self._initial_state
        self.history = []

    @property
    def initial_state(self) -> str:
        return self._initial_state

