from typing import List, Dict, Tuple, Optional
from fsm import Machine, State, Transition, Event, InvalidTransition, GuardRejected

# --- Custom Exceptions ---

class VendingError(Exception):
    """Base exception for Vending Machine operations."""
    pass

class SoldOut(VendingError):
    """Raised when a selected product is out of stock."""
    pass

class InsufficientCredit(VendingError):
    """Raised when the inserted credit is less than the product price."""
    pass

# --- Vending Machine Implementation ---

class VendingMachine:
    """
    A Vending Machine implemented using an FSM.
    """

    # Coin denominations used for change/refund
    CHANGE_COINS = [100, 25, 10, 5]

    def __init__(self, products: Dict[str, Tuple[int, int]]):
        # products: {code: (price_cents, stock)}

        # Internal state tracking
        self._products = {}  # {code: (price, stock)}
        self._sales: Dict[str, int] = {} # {code: count}
        self._total_revenue: int = 0 # in cents

        # FSM Context and Setup
        self.context = {
            'credit': 0,
            'products': products,
            'sales': self._sales,
            'total_revenue': self._total_revenue
        }
        self.machine = self._setup_fsm(products)

        # Initialize product tracking based on initial input
        for code, (price, stock) in products.items():
            self._products[code] = {'price': price, 'stock': stock}


    def _create_state(self, name: str, on_enter=None, on_exit=None) -> State:
        return State(name=name, on_enter=on_enter, on_exit=on_exit)

    def _setup_fsm(self, initial_products: Dict[str, Tuple[int, int]]) -> Machine:

        # State definitions
        states_list = [
            self._create_state('idle'),
            self._create_state('credit'),
            self._create_state('maintenance')
        ]

        # Transitions Definition (Note: Transition sources are state names)
        transitions: List[Transition] = []

        # --- IDLE State Transitions ---
        # 1. Insert coin -> credit
        transitions.append(Transition(
            event='insert',
            source='idle',
            target='credit',
            action=lambda m, e: m.context['credit'].__iadd__(e.data['coin']), # Add coin
            guard=lambda m, e: e.data['coin'] in {5, 10, 25, 100}
        ))
        # 2. Service -> maintenance
        transitions.append(Transition(
            event='service',
            source='idle',
            target='maintenance',
            action=None
        ))

        # --- CREDIT State Transitions ---
        # 1. Select product -> idle (Success)
        transitions.append(Transition(
            event='select',
            source='credit',
            target='idle',
            guard=lambda m, e: m.context['products'][e.data['code']]['stock'] > 0 and m.context['credit'] >= m.context['products'][e.data['code']]['price'],
            action=lambda m, e: m._handle_purchase(e.data['code']) # Custom action to handle side effects
        ))
        # 2. Cancel -> idle
        transitions.append(Transition(
            event='cancel',
            source='credit',
            target='idle',
            action=lambda m, e: m._refund(e.data.get('credit', m.context['credit']))
        ))
        # 3. Insert coin (Allowed in credit) -> credit (Self-loop/re-entry)
        transitions.append(Transition(
            event='insert',
            source='credit',
            target='credit',
            action=lambda m, e: m.context['credit'].__iadd__(e.data['coin']),
            guard=lambda m, e: e.data['coin'] in {5, 10, 25, 100}
        ))

        # --- MAINTENANCE State Transitions ---
        # 1. Restock (Internal Transition - State remains maintenance)
        transitions.append(Transition(
            event='restock',
            source='maintenance',
            target=None,
            action=lambda m, e: m._handle_restock(e.data['code'], e.data['qty'], e.data.get('price'))
        ))
        # 2. Resume -> idle
        transitions.append(Transition(
            event='resume',
            source='maintenance',
            target='idle',
            action=None
        ))

        # --- Event Listener ---
        def transition_listener(m: Machine, e: Event, source: str, target: str):
            if target == 'idle':
                # Reset credit when returning to idle state (if not already handled by purchase/cancel)
                if source == 'credit' and e.name not in ('cancel', 'select'):
                     m.context['credit'] = 0

        # Add listener to the machine
        machine = Machine(states_list, transitions, 'idle', context=self.context)
        machine.on_transition(transition_listener)

        return machine

    # --- Private Handlers (Called by FSM actions) ---

    def _handle_purchase(self, code: str):
        """Handles stock reduction, revenue update, and change calculation."""
        product = self._products[code]

        # State transition succeeded, so stock is definitely > 0 and credit is sufficient.
        product['stock'] -= 1
        self._sales[code] = self._sales.get(code, 0) + 1
        self._total_revenue += product['price']

        change_needed = self.context['credit'] - product['price']
        self.context['credit'] = 0

        # Change is returned via the action's implicit effect, but we must ensure 
        # the machine logic reflects the zeroing of credit.
        # The actual coin return logic must be handled externally or via a dedicated 'change' event, 
        # but per prompt, the action must handle side effects. Here, we just calculate it.
        # The FSM logic ensures the state transitions to 'idle' and credit is 0.
        self.context['change_to_return'] = change_needed
        # Note: The actual coin issuance for change happens when the machine moves to idle/handles the transaction end.

    def _refund(self, amount: int):
        """Calculates and resets credit to zero."""
        self.context['credit'] = 0
        self.context['change_to_return'] = amount

    def _handle_restock(self, code: str, qty: int, price: Optional[int]):
        """Handles restocking logic."""
        if qty < 1:
            raise ValueError("Restock quantity must be >= 1.")

        if code not in self._products:
            if price is None:
                raise KeyError(f"Cannot restock new code '{code}': price must be provided.")
            # New product
            self._products[code] = {'price': price, 'stock': qty}
        else:
            # Existing product, update stock and price if provided
            self._products[code]['stock'] += qty
            if price is not None:
                self._products[code]['price'] = price

    # --- Public Interface ---

    @property
    def state(self) -> str:
        return self.machine.state

    @property
    def credit(self) -> int:
        return self.context['credit']

    def stock(self, code: str) -> int:
        return self._products[code]['stock']

    def price(self, code: str) -> int:
        return self._products[code]['price']

    @property
    def sales(self) -> Dict[str, int]:
        return self._sales

    @property
    def revenue(self) -> int:
        return self._total_revenue

    def _dispense_coins(self, amount: int) -> List[int]:
        """Greedily calculates coins for change/refund."""
        if amount <= 0:
            return []

        change_given = []
        remaining = amount

        for coin in self.CHANGE_COINS:
            count = remaining // coin
            if count > 0:
                change_given.extend([coin] * count)
                remaining -= count * coin

        return change_given

    def insert(self, coin: int) -> int:
        # Attempt transition from current state
        try:
            # Fire using the 'insert' event
            self.machine.fire('insert', coin=coin)
            return self.credit
        except InvalidTransition:
            # Event not allowed from current state (e.g., maintenance)
            raise InvalidTransition(state=self.state, event='insert')
        except Exception as e:
            # Check if the coin was rejected by the guard (only happens if coin is invalid)
            if isinstance(e, GuardRejected):
                # Since the guard rejected it, no state change occurred.
                raise ValueError(f"Coin {coin} is not accepted.")
            raise e

    def select(self, code: str) -> List[int]:
        if self.state != 'credit':
            raise InvalidTransition(state=self.state, event='select')

        try:
            # Fire using the 'select' event. The action handles side effects (stock/revenue)
            self.machine.fire('select', code=code)

            # Transaction succeeded, now dispense change/refund
            change_amount = self.context.pop('change_to_return')
            return self._dispense_coins(change_amount)

        except InvalidTransition:
            # Should be caught by state check, but kept for robustness
            raise InvalidTransition(state=self.state, event='select')
        except KeyError:
            # Unknown code
            raise KeyError(f"Unknown product code: {code}")
        except SoldOut:
            # Stock check failed (guard failure on stock)
            raise SoldOut(f"Product {code} is sold out.")
        except InsufficientCredit:
            # Credit check failed (guard failure on price)
            raise InsufficientCredit(f"Insufficient credit for product {code}.")
        except GuardRejected:
             # This means the guard failed, but the specific exception wasn't raised internally 
             # (e.g., if the guard check logic was complex).
             # Since we checked for these errors in the FSM setup, this usually implies 
             # a logic error in the guard if it reaches here. For safety, re-raise the specific errors.
             # If it's GuardRejected, we assume no change occurred, so we re-raise based on state.
             # If the FSM raises GuardRejected, it means the specific VendingError wasn't triggered.
             # We must assume the failure was due to one of the internal checks, or it's an internal FSM issue.
             raise InvalidTransition(state=self.state, event='select')


    def cancel(self) -> List[int]:
        if self.state != 'credit':
            raise InvalidTransition(state=self.state, event='cancel')

        try:
            self.machine.fire('cancel', credit=self.credit)

            # Transaction succeeded, dispense refund
            refund_amount = self.context.pop('change_to_return')
            return self._dispense_coins(refund_amount)
        except InvalidTransition:
            raise InvalidTransition(state=self.state, event='cancel')

    def service(self) -> None:
        if self.state != 'idle':
            raise InvalidTransition(state=self.state, event='service')

        try:
            self.machine.fire('service')
        except InvalidTransition:
            raise InvalidTransition(state=self.state, event='service')

    def restock(self, code: str, qty: int, price: Optional[int] = None) -> None:
        if self.state != 'maintenance':
            raise InvalidTransition(state=self.state, event='restock')

        try:
            self.machine.fire('restock', code=code, qty=qty, price=price)
        except InvalidTransition:
            # This should not happen if state check passed, but kept for consistency
            raise InvalidTransition(state=self.state, event='restock')
        except GuardRejected:
            # This should not happen either, but if it does, the operation fails silently in FSM logic
            raise VendingError("Restock failed validation.")


    def resume(self) -> None:
        if self.state != 'maintenance':
            raise InvalidTransition(state=self.state, event='resume')

        try:
            self.machine.fire('resume')
        except InvalidTransition:
            raise InvalidTransition(state=self.state, event='resume')

