import json
from dataclasses import dataclass, field
from typing import Any, Iterator, List, Tuple, Dict

# --- Errors ---

class HTTPError(Exception):
    def __init__(self, status: int, reason: str):
        super().__init__(f"{status} {reason}")
        self.status = status
        self.reason = reason

class BadRequest(HTTPError):
    def __init__(self, message: str = None):
        super().__init__(400, "Bad Request")
        self.message = message

# --- Constants ---

REASON_PHRASES = {
    200: "OK", 201: "Created", 204: "No Content", 400: "Bad Request",
    401: "Unauthorized", 404: "Not Found", 405: "Method Not Allowed", 500: "Internal Server Error"
}

def get_reason(status: int) -> str:
    return REASON_PHRASES.get(status, "Unknown")

# --- Headers ---

class Headers:
    def __init__(self, pairs: Tuple[Tuple[str, str], ...] = ()):
        self._fields: List[Tuple[str, str]] = list(pairs)

    def add(self, name: str, value: str):
        self._fields.append((name, value))

    def set(self, name: str, value: str):
        lower_name = name.lower()
        found = False
        new_fields = []

        # Find the first occurrence to replace
        for i, (n, v) in enumerate(self._fields):
            if n.lower() == lower_name:
                new_fields.append((name, value)) # Use provided case for replacement
                found = True
            else:
                new_fields.append((n, v))

        if not found:
            new_fields.append((name, value))

        self._fields = new_fields

    def get(self, name: str, default: Any = None) -> Any:
        for n, v in self._fields:
            if n.lower() == name.lower():
                return v
        return default

    def __getitem__(self, name: str) -> str:
        for n, v in self._fields:
            if n.lower() == name.lower():
                return v
        raise KeyError(f"Header {name} not found")

    def get_all(self, name: str) -> List[str]:
        return [v for n, v in self._fields if n.lower() == name.lower()]

    def __contains__(self, name: str) -> bool:
        return any(n.lower() == name.lower() for n, _ in self._fields)

    def __len__(self) -> int:
        return len(self._fields)

    def items(self) -> List[Tuple[str, str]]:
        return list(self._fields)

# --- Request ---

@dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: Dict[str, Any] = field(default_factory=dict)
    state: Dict[str, Any] = field(default_factory=dict)

    @property
    def query(self) -> Dict[str, List[str]]:
        if not self.query_string:
            return {}

        query_dict: Dict[str, List[str]] = {}

        # Split on &
        pairs = self.query_string.split('&')

        for pair in pairs:
            if not pair:
                continue

            parts = pair.split('=', 1)
            name_encoded = parts[0]
            value_encoded = parts[1] if len(parts) > 1 else ''

            # Decode name and value
            name, value = self._decode_percent_escape(name_encoded, is_value=False)

            # If value is present, decode it. If not, it's an empty string.
            if value_encoded:
                value = self._decode_percent_escape(value_encoded, is_value=True)
            else:
                value = ''

            if name not in query_dict:
                query_dict[name] = []
            query_dict[name].append(value)

        return query_dict

    @property
    def content_type(self) -> Tuple[str, Dict[str, str]]:
        ct_header = self.headers.get('Content-Type')
        if not ct_header:
            return ('', {})

        parts = [p.strip() for p in ct_header.split(';')]

        # First piece is media type
        media_type = parts[0].lower()
        params: Dict[str, str] = {}

        for part in parts[1:]:
            if '=' in part:
                try:
                    name, value = part.split('=', 1)
                    name_lower = name.strip().lower()
                    value_stripped = value.strip()

                    # Remove surrounding quotes if present
                    if value_stripped.startswith('"') and value_stripped.endswith('"'):
                        value_cleaned = value_stripped[1:-1]
                    else:
                        value_cleaned = value_stripped

                    params[name_lower] = value_cleaned
                except ValueError:
                    # Should not happen if '=' is checked, but for safety
                    pass

        return (media_type, params)

    def _decode_percent_escape(self, encoded: str, is_value: bool) -> str:
        """Decodes %XX sequences, treating '+' as space, and handling UTF-8 errors."""

        # 1. Replace '+' with ' ' (Space)
        temp_str = encoded.replace('+', ' ')

        # 2. Percent decoding
        decoded_bytes = bytearray()
        i = 0
        while i < len(temp_str):
            char = temp_str[i]
            if char == '%':
                i += 1
                if i + 1 >= len(temp_str):
                    raise BadRequest("Malformed percent escape sequence.")

                hex_pair = temp_str[i:i+2]
                try:
                    byte_val = int(hex_pair, 16)
                    decoded_bytes.append(byte_val)
                    i += 2
                except ValueError:
                    raise BadRequest(f"Invalid hex digits in percent escape: %{hex_pair}")
            else:
                # Append characters directly if not '%'
                decoded_bytes.append(ord(char))
                i += 1

        # 3. Decode bytes as UTF-8
        try:
            return decoded_bytes.decode('utf-8')
        except UnicodeDecodeError as e:
            raise BadRequest(f"Invalid UTF-8 sequence in request part: {e}")


    def text(self, charset: str = 'utf-8') -> str:
        """Decodes the body bytes using the specified charset or UTF-8."""
        try:
            return self.body.decode(charset)
        except UnicodeDecodeError as e:
            raise BadRequest(f"Failed to decode body with {charset}: {e}")

    def json(self) -> Any:
        """Parses the body as JSON."""
        content_type, params = self.content_type
        charset = params.get('charset', 'utf-8')

        try:
            text_body = self.text(charset)
            return json.loads(text_body)
        except json.JSONDecodeError:
            raise BadRequest("Body is not valid JSON.")


