        if len(body) != expected_len:
            raise BadRequest(f"Content-Length mismatch. Expected {expected_len}, got {len(body)}.")
        body_data = body
    else:
        # No headers, body is empty
        body_data = b''

    # Final validation: No bytes left over after the body (This check is complex because the body *was* the rest of data, 
    # but if chunked, the iteration consumed it). We rely on the loop completion for chunked.

    return Request(
        method=method,
        target=target,
        path=target.lstrip('/'), # Path is target without leading '/'
        query_string=target.split('?', 1)[-1] if '?' in target else '',
        version=version,
        headers=headers,
        body=body_data,
    )
