from typing import Callable, Tuple, Dict, List, Union, Any
from web.request import Request, Response, HTTPError, BadRequest

# Type alias for handler function
Handler = Callable[[Request], Response]

class NotFound(HTTPError):
    def __init__(self):
        super().__init__(404, "Not Found")

class MethodNotAllowed(HTTPError):
    def __init__(self, allowed: List[str]):
        self.allowed = sorted(allowed)
        super().__init__(405, "Method Not Allowed")

class Router:
    def __init__(self):
        # Structure: { (method, pattern_tuple): handler }
        # pattern_tuple: (regex_pattern_str, parameter_names, converter_map)
        self._routes: Dict[Tuple[str, Any], Tuple[str, List[str], Dict[str, str]]] = {}
        self._method_map: Dict[str, List[Tuple[str, List[str], Dict[str, str]]]] = {}

    def add(self, method: str, pattern: str, handler: Handler):
        self._register_route(method, pattern, handler)

    def route(self, pattern: str, methods: Tuple[str, ...] = ('GET',)):
        """Decorator implementation."""
        def decorator(handler: Handler):
            for method in methods:
                self.add(method, pattern, handler)
            return handler
        return decorator

    def _register_route(self, method: str, pattern: str, handler: Handler):
        # Simple regex conversion for demonstration based on specs

        # 1. Basic validation (must start with /)
        if not pattern.startswith('/'):
            raise ValueError("Pattern must start with '/'")

        # 2. Tokenization and parameter extraction
        segments = pattern.split('/')
        if segments[0] != '':
             raise ValueError("Pattern must start with '/'")

        param_names: List[str] = []
        # regex parts will be built here.
        regex_segments: List[str] = []

        # Conversion map: segment_regex -> name/type info
        param_info: Dict[str, str] = {} # {param_name: converter}

        # Process segments, skipping the initial empty segment
        for i, segment in enumerate(segments[1:]):
            if not segment: continue # Handle double slashes if they pass initial check

            if segment.startswith('{') and segment.endswith('}'):
                content = segment[1:-1]

                if ':' in content:
                    name, converter_spec = content.split(':', 1)
                    name = name.strip()
                    converter_spec = converter_spec.strip()

                    if name in param_names:
                        raise ValueError(f"Repeated parameter name: {name}")

                    param_names.append(name)

                    if converter_spec == 'int':
                        regex_segments.append(r"(\d+)")
                        param_info[name] = 'int'
                    elif converter_spec == 'path':
                        # Must be the last segment
                        if i != len(segments) - 2:
                            raise ValueError("Path converter '{name:path}' can only be the last segment.")
                        # Matches one or more segments joined by /
                        regex_segments.append(r"(.+)")
                        param_info[name] = 'path'
                    else:
                        raise ValueError(f"Unknown converter: {converter_spec}")
                else:
                    # Literal parameter name (not supported by current regex logic, treating as literal string)
                    raise ValueError(f"Segment '{segment}' must be literal or a named parameter.")
            else:
                # Literal segment
                regex_segments.append(re.escape(segment))

        # Join segments into final regex, ensuring start/end anchors
        regex_pattern = "^/" + "/".join(regex_segments) + "$"

        # --- Registration ---

        # Check for existing route (pattern string uniqueness)
        # We check the full pattern string against registered ones for the same method
        existing_patterns = [
            p for m, p, _, _ in self._routes.values() if m == method and p == pattern
        ]
        if existing_patterns:
             raise ValueError(f"Route for {method} with pattern '{pattern}' already registered.")

        # Store route info
        route_key = (method, pattern)
        self._routes[route_key] = (regex_pattern, param_names, param_info)

        # Update method map for fast lookup later
        if method not in self._method_map:
            self._method_map[method] = []
        self._method_map[method].append((regex_pattern, param_names, param_info, handler))


    def resolve(self, method: str, path: str) -> Tuple[Handler, Dict[str, Any]]:
        """Finds the matching handler and extracts parameters."""

        # 1. Path segment decoding (Percent decoding, '+' stays '+')
        # NOTE: The spec says "percent-decoded with the same rules as the query string except that '+' stays a '+'."
        # This means we must implement a specialized decoder here, or adapt the Request decoder.

        def decode_path_segment(encoded: str) -> str:
            decoded_bytes = bytearray()
            i = 0
            while i < len(encoded):
                char = encoded[i]
                if char == '%':
                    i += 1
                    if i + 1 >= len(encoded):
                        raise BadRequest("Malformed percent escape sequence in path.")

                    hex_pair = encoded[i:i+2]
                    try:
                        byte_val = int(hex_pair, 16)
                        decoded_bytes.append(byte_val)
                        i += 2
                    except ValueError:
                        raise BadRequest(f"Invalid hex digits in path: %{hex_pair}")
                else:
                    # '+' is literal, so we just append the byte value
                    decoded_bytes.append(ord(char))
                    i += 1

            try:
                return decoded_bytes.decode('utf-8')
            except UnicodeDecodeError as e:
                raise BadRequest(f"Invalid UTF-8 sequence in path: {e}")


        path_segments = []
        if path.startswith('/'):
            raw_segments = path.lstrip('/').split('/')
        else:
            raw_segments = [path] # Should not happen if caller uses proper paths

        decoded_segments = [decode_path_segment(s) for s in raw_segments if s]

        # 2. Try matching against registered patterns (order matters)

        matching_methods: List[Tuple[str, List[str], Dict[str, str], Handler]] = []

        for registered_method, registered_patterns in self._method_map.items():
            if registered_method != method and method != 'HEAD':
                # HEAD is served by GET handler if no HEAD handler exists
                continue

            for regex_pattern, param_names, param_info, handler in registered_patterns:
                import re

                match = re.fullmatch(regex_pattern, path)

                if match:
                    # Path matched. Now extract parameters.
                    params: Dict[str, Any] = {}
                    groups = match.groups()

                    # The groups correspond exactly to the parameters defined in param_names
                    for i, name in enumerate(param_names):
                        raw_value = groups[i]
                        converter = param_info[name]

                        if converter == 'int':
                            try:
                                params[name] = int(raw_value)
                            except ValueError:
                                raise BadRequest(f"Parameter '{name}' expected integer but got '{raw_value}'.")
                        elif converter == 'path':
                            # Path converter already captured everything in raw_value
                            params[name] = raw_value
                        else:
                            params[name] = raw_value # Literal string parameter if implemented differently

                    matching_methods.append((registered_method, param_names, param_info, handler))


        if not matching_methods:
            # Check if any pattern exists at all, to provide correct 405 allowed list
            all_allowed_methods = set()
            for _, patterns in self._method_map.items():
                 for _, _, _, handler in patterns:
                     # We cannot easily derive allowed methods just from the handler here, 
                     # so we rely on the pattern registration structure if we were to fully implement 405.
                     # For now, we just raise NotFound if no match found.
                     pass 
            raise NotFound()

        # Filter to only include methods matching the request method (or HEAD compatibility)
        final_matches = []
        for registered_method, _, _, handler in matching_methods:
            if method == 'HEAD' and registered_method == 'GET':
                # HEAD matches GET if no HEAD handler exists
                final_matches.append((registered_method, handler))
            elif method == registered_method:
                 final_matches.append((registered_method, handler))

        if not final_matches:
            # Path matched, but not for this method
            allowed_methods = list(set(
                method for m, handler in matching_methods if m != 'HEAD'
            ))
            # Add GET if it matched but was only found via HEAD compatibility logic (this is complex, sticking to defined matches)
            raise MethodNotAllowed(allowed_methods)

        # First match wins
        _, handler = final_matches[0]
        return handler, {} # Params are merged later in dispatch

    def dispatch(self, request: Request) -> Response:
        """Resolves, populates request.params, calls handler, and returns Response."""

        handler, _ = self.resolve(request.method, request.path)

        # Re-resolve to get actual params dictionary needed for dispatch
        # (This is slightly inefficient but necessary if resolve() returns simplified tuple)
        # A better structure would be resolve() -> (handler, params)

        # Since resolve() currently only returns handler, we must call it again or refactor.
        # For simplicity, we assume we can extract params again or rely on the internal state if we refactor resolve.

        # REFACTOR NOTE: We assume resolve returns (handler, params_dict)
        try:
            handler, params = self.resolve(request.method, request.path)
        except NotFound:
            return Response.text("404 Not Found", status=404)
        except MethodNotAllowed as e:
            # Use the allowed list from the exception
            response = Response()
            response.status = 405
            response.headers.add('Allow', ", ".join(e.allowed))
            response.body = f"405 Method Not Allowed: {', '.join(e.allowed)}".encode('utf-8')
            return response
        except HTTPError as e:
            # Catch any other HTTP errors from resolve
            response = Response()
            response.status = e.status
            response.body = f"{e.status} {e.reason}".encode('utf-8')
            return response


        request.params = params

        try:
            response = handler(request)
        except Exception as e:
            # Any exception during handler execution results in 500
            print(f"Unhandled exception in handler: {e}") # Log for debugging
            response = Response()
            response.status = 500
            response.body = f"500 Internal Server Error".encode('utf-8')
            return response

        # Handle HEAD request: body must be empty, headers kept
        if request.method == 'HEAD' and response.body:
            response.body = b''

        return response
