import base64
from typing import Callable, List, Dict, Any
from web.request import Request, Response, BadRequest, HTTPError, NotFound, MethodNotAllowed
from web.router import Router

# Type alias for middleware and application handle
Middleware = Callable[[Request, Callable[[Request], Response]], Response]
Handler = Callable[[Request], Response]

class App:
    def __init__(self, router: Router, middleware: List[Middleware] = None):
        self.router = router
        self.middleware = middleware if middleware is not None else []

    def use(self, mw: Middleware):
        self.middleware.append(mw)

    def handle(self, request: Request) -> Response:
        """Runs the middleware chain."""

        def call_router(req: Request) -> Response:
            # Innermost call: Router dispatch
            return self.router.dispatch(req)

        # Middleware chain execution (outermost first)
        # We wrap the router call in a try/except block to ensure all middleware gets a Response

        # The last step in the chain is call_router

        def chain(req: Request) -> Response:
            try:
                return call_router(req)
            except HTTPError as e:
                # Convert HTTPError to an error response
                response = Response()
                response.status = e.status
                reason = e.reason

                body_text = f"{e.status} {reason}"
                if isinstance(e, MethodNotAllowed):
                    response.headers.add('Allow', ", ".join(e.allowed))
                    body_text = f"Method Not Allowed. Allowed: {', '.join(e.allowed)}"

                response.body = response.text(body_text, status=e.status).body
                return response
            except Exception as e:
                # Convert any other exception to 500 error response
                response = Response()
                response.status = 500
                response.body = Response.text("500 Internal Server Error").body
                return response

        # Chain the middleware: mw1(req, mw2(req, ... call_router))
        current_call = chain(request)

        # Iterate backward over middleware to build the stack from the outside in
        for mw in reversed(self.middleware):
            # Wrap the current response/chain result into the next step for this middleware
            next_call = lambda req=request: current_call 
            current_call = mw(request, next_call)

        return current_call

    def handle_bytes(self, data: bytes) -> bytes:
        """Parses raw bytes, handles it, and returns response bytes."""
        try:
            request = parse_request(data)
        except BadRequest as e:
            # BadRequest from parsing skips middleware entirely
            response = Response()
            response.status = 400
            response.body = Response.text(f"400 Bad Request: {getattr(e, 'message', 'Unknown error')}").body
            return response.to_bytes()

        response = self.handle(request)
        return response.to_bytes()


# --- Middleware Factories ---

def logger(lines: List[str]) -> Middleware:
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        response = call_next(request)
        lines.append(f"{request.method} {request.path} {response.status}")
        return response
    return mw

def cookies() -> Middleware:
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        cookies_state: Dict[str, str] = {}

        cookie_header = request.headers.get('Cookie')
        if cookie_header:
            # Treat cookie parsing exactly like Content-Type parameter parsing
            parts = [p.strip() for p in cookie_header.split(';')]
            for part in parts:
                if '=' in part:
                    try:
                        name, value = part.split('=', 1)
                        name_stripped = name.strip()
                        value_stripped = value.strip()

                        # Cookies keep case, so name isn't lowercased

                        # Remove surrounding quotes if present
                        if value_stripped.startswith('"') and value_stripped.endswith('"'):
                            value_cleaned = value_stripped[1:-1]
                        else:
                            value_cleaned = value_stripped

                        cookies_state[name_stripped] = value_cleaned
                    except ValueError:
                        pass

        request.state['cookies'] = cookies_state
        return call_next(request)
    return mw

def basic_auth(users: Dict[str, str], realm: str = 'app') -> Middleware:
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        auth_header = request.headers.get('Authorization')

        if not auth_header or not auth_header.startswith('Basic '):
            return call_next(request)

        encoded_creds = auth_header[len('Basic '):].strip()

        try:
            decoded_creds = base64.b64decode(encoded_creds).decode('ascii')

            if ':' not in decoded_creds:
                raise ValueError("Credentials format invalid.")

            username, password = decoded_creds.split(':', 1)

            if username in users and users[username] == password:
                request.state['user'] = username
                return call_next(request)
            else:
                # Authentication failed
                response = Response()
                response.status = 401
                response.headers.add('WWW-Authenticate', f'Basic realm="{realm}"')
                response.body = "401 Unauthorized".encode('utf-8')
                return response

        except Exception:
            # Any decoding or parsing error results in 401
            response = Response()
            response.status = 401
            response.headers.add('WWW-Authenticate', f'Basic realm="{realm}"')
            response.body = "401 Unauthorized".encode('utf-8')
            return response

    return mw
