### `sheet/formula.py`

```python
import re
from typing import Any, Dict, List, Union, Set, Tuple

# --- Custom Errors and Values ---

class FormulaError(ValueError):
    """Raised when a formula cannot be parsed or evaluated."""
    pass

class ErrorValue(str):
    """Represents an error state in a cell."""
    pass

ERROR_GENERAL = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- AST Node Definitions ---

class Node:
    """Base class for AST nodes."""
    pass

class NumberNode(Node):
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode(Node):
    def __init__(self, name: str):
        self.name = name # Stored upper case

class BinaryOpNode(Node):
    def __init__(self, left: Node, op: str, right: Node):
        self.left = left
        self.op = op
        self.right = right

class UnaryOpNode(Node):
    def __init__(self, op: str, operand: Node):
        self.op = op
        self.operand = operand

# --- Parsing ---

# Token definition: numbers (including decimals), references (letters+digits), operators, parentheses
TOKEN_SPECIFICATION = [
    ('NUMBER', r'\d+(\.\d*)?'),
    ('REF', r'[A-Z][A-Z0-9]*'), # References are letters followed by digits. We normalize case later.
    ('PLUS', r'\+'),
    ('MINUS', r'-'),
    ('MUL', r'\*'),
    ('DIV', r'/'),
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    ('SKIP', r'[ \t]+'),
    ('MISMATCH', r'.'),
]

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

def tokenize(source: str) -> List[Token]:
    tokens = []
    token_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPECIFICATION)

    for mo in re.finditer(token_regex, source):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Illegal character: {value}")
        elif kind == 'REF':
            # Normalize reference to uppercase during tokenization
            tokens.append(Token('REF', value.upper()))
        else:
            tokens.append(Token(kind, value))
    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_type: str | None = None, expected_value: str | None = None) -> Token:
        token = self.peek()
        if not token:
            raise FormulaError("Unexpected end of expression.")
        if expected_type and token.type != expected_type:
            raise FormulaError(f"Expected token type {expected_type}, got {token.type} ('{token.value}')")
        if expected_value and token.value != expected_value:
            raise FormulaError(f"Expected token value '{expected_value}', got '{token.value}'")
        self.pos += 1
        return token

    def parse_number(self) -> NumberNode:
        token = self.consume('NUMBER')
        try:
            if '.' in token.value:
                return NumberNode(float(token.value))
            else:
                return NumberNode(int(token.value))
        except ValueError:
            raise FormulaError(f"Invalid number format: {token.value}")

    def parse_ref(self) -> RefNode:
        token = self.consume('REF')
        return RefNode(token.value)

    def parse_primary(self) -> Node:
        token = self.peek()
        if not token:
            raise FormulaError("Expected primary expression, got end of input.")

        # Handle Unary Sign
        if token.type == 'MINUS' or token.type == 'PLUS':
            op_token = self.consume()
            operand = self.parse_primary()
            return UnaryOpNode(op_token.value, operand)

        if token.type == 'LPAREN':
            self.consume('LPAREN')
            node = self.expr()
            self.consume('RPAREN')
            return node

        # Number or Reference
        if token.type == 'NUMBER':
            return self.parse_number()
        elif token.type == 'REF':
            return self.parse_ref()
        else:
            raise FormulaError(f"Unexpected token in primary expression: {token}")

    # Grammar implementation: expr -> term {(+ | -) term}
    def expr(self) -> Node:
        node = self.term()
        while self.peek() and self.peek().type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            right = self.term()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    # Grammar implementation: term -> unary {(* | /) unary}
    def term(self) -> Node:
        node = self.unary()
        while self.peek() and self.peek().type in ('MUL', 'DIV'):
            op_token = self.consume()
            right = self.unary()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    # Grammar implementation: unary -> (+ | -) unary | number | ref | ( expr )
    # NOTE: We handled unary signs at the start of parse_primary, so this only handles literals/parentheses
    # For simplicity and matching the precedence rules, we reuse parse_primary structure slightly adjusted.
    def unary(self) -> Node:
        # Since parse_primary already handles leading signs, we just delegate for the rest of the term structure
        return self.parse_primary()


def parse_formula(source: str) -> Node:
    """Parses the text after '=' and returns the syntax tree."""
    if not source.strip():
        raise FormulaError("Formula source cannot be empty.")

    tokens = tokenize(source)
    parser = Parser(tokens)
    ast = parser.expr()

    if parser.peek() is not None:
        raise FormulaError(f"Unparsed tokens remaining: {parser.tokens[parser.pos:]}")

    return ast

# --- Reference Extraction ---

def references(tree: Node) -> Set[str]:
    """Returns the set of all upper-case cell names referenced by the AST."""
    found_refs: Set[str] = set()

    if isinstance(tree, RefNode):
        found_refs.add(tree.name)
    elif isinstance(tree, BinaryOpNode):
        found_refs.update(references(tree.left))
        found_refs.update(references(tree.right))
    elif isinstance(tree, UnaryOpNode):
        found_refs.update(references(tree.operand))
    # NumberNode contributes nothing
    return found_refs

# --- Evaluation ---

def _safe_float(value: Any) -> Union[int, float]:
    """Converts a numeric type to int or float based on presence of '.'."""
    if isinstance(value, (int, float)):
        return int(value) if value == int(value) else float(value)
    raise TypeError(f"Cannot convert {value} to number.")

def evaluate(tree: Node, lookup: Dict[str, Any]) -> Any:
    """
    Computes the formula's value.
    lookup: maps cell name (str) -> cell value (int, float, str, None, ErrorValue)
    """

    if isinstance(tree, NumberNode):
        return tree.value

    elif isinstance(tree, RefNode):
        name = tree.name
        cell_value = lookup.get(name)

        if cell_value is None:
            # Empty cell acts as 0 for arithmetic
            return 0

        if isinstance(cell_value, ErrorValue):
            return cell_value

        if isinstance(cell_value, str):
            # If it's text, and we are only evaluating a reference, return text itself (e.g., =A1 where A1="hi")
            if not any(isinstance(child, (NumberNode, RefNode, UnaryOpNode, BinaryOpNode)) for child in [tree]):
                 # This condition is slightly tricky based on the rule: 
                 # "A formula that is only a reference therefore returns text unchanged"
                return cell_value

        # If it's a number, return the value.
        return cell_value

    elif isinstance(tree, UnaryOpNode):
        operand_value = evaluate(tree.operand, lookup)
        op = tree.op

        if isinstance(operand_value, ErrorValue):
            return operand_value

        if op == '+':
            return operand_value
        elif op == '-':
            # Unary minus: negate if numeric
            if isinstance(operand_value, (int, float)):
                return -operand_value
            else:
                return ERROR_GENERAL

        # Division and multiplication are not unary operators in this grammar context
        raise FormulaError(f"Invalid unary operator: {op}")

    elif isinstance(tree, BinaryOpNode):
        left_val = evaluate(tree.left, lookup)
        right_val = evaluate(tree.right, lookup)
        op = tree.op

        # Rule 3: Error propagation
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            return left_val if isinstance(left_val, ErrorValue) else right_val

        # Rule 3: Text interaction
        if isinstance(left_val, str) or isinstance(right_val, str):
            return ERROR_GENERAL

        # Numeric Operations (Rule 4)

        # Convert operands to numeric type if they came from a ref that returned 0 (None)
        l_num = left_val if isinstance(left_val, (int, float)) else 0
        r_num = right_val if isinstance(right_val, (int, float)) else 0

        if op == '+':
            if isinstance(l_num, int) and isinstance(r_num, int):
                return l_num + r_num
            return l_num + r_num # float addition

        elif op == '-':
            if isinstance(l_num, int) and isinstance(r_num, int):
                return l_num - r_num
            return l_num - r_num # float subtraction

        elif op == '*':
            if isinstance(l_num, int) and isinstance(r_num, int):
                return l_num * r_num
            return l_num * r_num # float multiplication

        elif op == '/':
            if r_num == 0:
                return ERROR_GENERAL

            # Division always results in float
            return float(l_num) / float(r_num)

    raise FormulaError("Unknown AST node encountered during evaluation.")
