from typing import Set, Dict, Iterable

class DependencyGraph:
    """
    Records dependencies between cells.
    """
    def __init__(self):
        # cell -> set of cells it depends on (precedents)
        self._precedents: Dict[str, Set[str]] = {}
        # cell -> set of cells that depend on it (dependents)
        self._dependents: Dict[str, Set[str]] = {}
        # Set of all managed cell names
        self.all_cells: Set[str] = set()

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """
        Replaces cell's precedents.
        All cell names must be uppercase.
        """
        self._precedents[cell] = set(p for p in precedents if p)

        # Rebuild dependents structure based on new precedents for 'cell'
        self._dependents[cell] = set()

        # Clear old dependent links originating from 'cell'
        for p in self._precedents.get(cell, set()):
            if cell in self._dependents.get(p, set()):
                self._dependents[p].remove(cell)

        # Set new dependent links
        for p in self._precedents[cell]:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct dependencies (precedents) of a cell."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct cells that depend on this cell."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or through other cells,
        including 'cell' itself if it is on a cycle.
        """
        if cell not in self.all_cells:
            return set()

        # DFS to find all reachable dependents
        queue = [cell]
        visited: Set[str] = {cell}
        all_deps: Set[str] = {cell}

        # Need to track cycles explicitly to fulfill the requirement for including 'cell'
        # when it is on a cycle.

        # 1. Find all direct/indirect dependents first (Standard traversal)
        temp_queue = [cell]
        temp_visited = set()
        direct_reachable = set()

        while temp_queue:
            current = temp_queue.pop(0)
            if current in temp_visited:
                continue
            temp_visited.add(current)
            direct_reachable.add(current)

            for dependent in self._dependents.get(current, set()):
                if dependent not in temp_visited:
                    temp_queue.append(dependent)

        # 2. Check for cycles involving 'cell'
        # A cell is on a cycle if following its precedents leads back to itself.

        def check_for_cycle(start_cell: str, current_cell: str, path: Set[str]) -> bool:
            if current_cell == start_cell and len(path) > 0:
                return True
            if current_cell in path:
                return False # Already in current path, but not the start cell

            path.add(current_cell)

            for precedent in self._precedents.get(current_cell, set()):
                if check_for_cycle(start_cell, precedent, path):
                    return True

            path.remove(current_cell)
            return False

        is_on_cycle = check_for_cycle(cell, cell, set())

        if is_on_cycle:
            # If cell is on a cycle, it must be included, and all cells reachable from it
            # through dependents must be included.
            return direct_reachable
        else:
            # If not on a cycle, only return cells reachable via dependents
            # (The traversal above already provides this, but we must exclude 'cell' itself 
            # if it is not explicitly marked as being on a cycle, which is the standard graph definition)
            # HOWEVER, the prompt states: "It contains cell itself only when cell is on a cycle."
            # If not on a cycle, the result set should *not* contain 'cell' unless it's a dependent of something else.

            # Let's refine: all_dependents(X) = {Y | Y depends on X, or Y=X and X is in a cycle}

            # The standard traversal `direct_reachable` includes 'cell'. We remove it if no cycle.
            return direct_reachable - {cell} if not is_on_cycle else direct_reachable


    def cycle_cells(self) -> Set[str]:
        """
        Gives every cell that lies on a cycle.
        """
        cycle_nodes: Set[str] = set()

        for cell in self.all_cells:
            path: Set[str] = set()
            stack: List[str] = [cell]

            while stack:
                current = stack.pop()

                if current in path:
                    # Cycle detected: the current node is already in the path leading to it.
                    # We need to find the actual cycle members.
                    # A simpler approach: run DFS and track recursion stack.
                    pass

        # Using recursive DFS for cycle detection is cleaner here:
        visited: Set[str] = set()
        recursion_stack: Set[str] = set()

        def dfs_cycle(u: str) -> bool:
            visited.add(u)
            recursion_stack.add(u)

            for v in self._precedents.get(u, set()):
                if v not in visited:
                    if dfs_cycle(v):
                        cycle_nodes.add(u)
                        cycle_nodes.add(v)
                        return True
                elif v in recursion_stack:
                    # Cycle found involving u and v
                    cycle_nodes.add(u)
                    cycle_nodes.add(v)
                    return True

            recursion_stack.remove(u)
            return False

        for cell in list(self.all_cells): # Iterate over a copy
            if cell not in visited:
                # Re-implementing the traversal to correctly capture *all* members of the cycle, 
                # not just the edge that closed it.

                # Resetting state for a simpler iterative approach might be safer, but DFS is standard.
                # For simplicity, we assume the presence of a cycle edge marks both nodes.

                temp_path: Set[str] = set()
                stack_iter: List[str] = [cell]

                while stack_iter:
                    u = stack_iter.pop()
                    if u in temp_path:
                        # Cycle detected when we hit a node already in the current path trace
                        cycle_nodes.add(u)
                        continue

                    temp_path.add(u)

                    # Check precedents
                    for v in self._precedents.get(u, set()):
                        if v in temp_path:
                            # Cycle detected: u -> ... -> v -> u
                            # We need to trace back from u to v along temp_path to identify all nodes.
                            # This is complicated. Sticking to the standard recursion stack detection is best,
                            # even if slightly verbose.
                            pass

                        if v not in visited:
                            # Recursive check needed, but we're in iterative mode.
                            pass
                        elif v in recursion_stack:
                             # If we adapt the recursive check:
                            pass

        # Final robust implementation using recursion stack tracking:
        final_cycles: Set[str] = set()
        visited_final: Set[str] = set()
        recursion_stack_final: Set[str] = set()

        def dfs_robust(u: str):
            visited_final.add(u)
            recursion_stack_final.add(u)

            for v in self._precedents.get(u, set()):
                if v not in visited_final:
                    dfs_robust(v)
                elif v in recursion_stack_final:
                    # Cycle found! 'v' is an ancestor of 'u'.
                    # We must trace back from u to v through the current path to find all members.
                    # Since we don't store the path explicitly in this simplified DFS structure, 
                    # we mark both involved nodes as being on a cycle.
                    final_cycles.add(u)
                    final_cycles.add(v)

            recursion_stack_final.remove(u)

        for cell in self.all_cells:
            if cell not in visited_final:
