from typing import Any, List, Dict, Set
from .graph import DependencyGraph
from .formula import (
    FormulaError, parse_formula, ErrorValue, ERROR_GENERAL, ERROR_CYCLE,
    evaluate, references, NumberNode, RefNode
)

# Constants
MAX_COL = 26
MAX_ROW = 999

class Sheet:
    def __init__(self):
        # cell_name (e.g., 'A1') -> raw_input_string (e.g., '=SUM(A1:A2)') or ''
        self._raw_data: Dict[str, str] = {}
        # cell_name -> calculated_value (int, float, str, None, ErrorValue)
        self._values: Dict[str, Any] = {}
        # cell_name -> AST Node for formulas
        self._formula_trees: Dict[str, Any] = {}
        # cell_name -> set of cells it refers to
        self._parsed_refs: Dict[str, Set[str]] = {}

        self.graph = DependencyGraph()
        self.evaluations: int = 0

    def _validate_name(self, name: str):
        """Validates if a name is within the sheet bounds."""
        if not name:
            raise ValueError("Cell name cannot be empty.")

        name = name.upper()

        # Column validation (A-Z)
        col_part = "".join(filter(str.isalpha, name))
        if not col_part or len(col_part) > MAX_COL:
            raise ValueError(f"Invalid column part in cell name: {name}")

        # Row validation (must be digits)
        row_part = "".join(filter(str.isdigit, name))
        if not row_part:
            raise ValueError(f"Invalid row part in cell name: {name}")

        try:
            row = int(row_part)
            if not (1 <= row <= MAX_ROW):
                raise ValueError

            # Check for leading zeros constraint (unless the number is '0', which isn't possible here)
            if len(row_part) > 1 and row_part.startswith('0'):
                raise ValueError("Row number cannot have leading zeros.")

        except ValueError:
            raise ValueError(f"Invalid row number in cell name: {name}")

    def _get_all_valid_cells(self) -> List[str]:
        """Returns all valid cell names in row-major order (A1, B1, ..., Z1, A2, ...)."""
        cells = []
        for r in range(1, MAX_ROW + 1):
            for c in range(1, MAX_COL + 1):
                col_char = chr(ord('A') + c - 1)
                cells.append(f"{col_char}{r}")
        return cells

    def _row_major_sort(self, cells: List[str]) -> List[str]:
        """Sorts cells by row, then by column."""
        def sort_key(name):
            col_str = "".join(filter(str.isalpha, name)).upper()
            row_str = "".join(filter(str.isdigit, name))
            # Sort key: (Row Number, Column Index)
            return (int(row_str), len(col_str)) 

        # Since we are building the list row by row in the helper above, 
        # this might be redundant if we used the helper, but it's safer.
        return sorted(cells, key=lambda x: (int("".join(filter(str.isdigit, x))), x))

    def get(self, name: str) -> Any:
        """Returns the cell's current calculated value."""
        self._validate_name(name)
        return self._values.get(name)

    def raw(self, name: str) -> str:
        """Returns the input string stored in the cell."""
        self._validate_name(name)
        return self._raw_data.get(name, "")

    def cells(self) -> List[str]:
        """Returns the non-empty cells in row-major order."""
        all_cells = self._get_all_valid_cells()
        non_empty = [name for name in all_cells if self._raw_data.get(name) and self._raw_data[name].strip() != '']
        return self._row_major_sort(non_empty)

    def set(self, name: str, raw: str) -> List[str]:
        """
        Stores the cell's input and triggers recalculation.
        Returns list of cells whose value may have changed, in row-major order.
        """
        self._validate_name(name)
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        old_raw = self._raw_data.get(name, "")
        if old_raw == raw:
            return []

        self._raw_data[name] = raw

        # 1. Parse and determine cell type/formula
        new_value: Any = None
        formula_tree: Any = None
        parsed_refs: Set[str] = set()
        is_formula = False

        stripped_raw = raw.strip()

        if stripped_raw.startswith('='):
            is_formula = True
            formula_source = stripped_raw[1:]
            try:
                formula_tree = parse_formula(formula_source)
                parsed_refs = references(formula_tree)
                self._formula_trees[name] = formula_tree
                self._parsed_refs[name] = parsed_refs
            except FormulaError as e:
                # If formula parsing fails, the cell value remains whatever it was (or None if new)
                # Per spec: "If parse_formula raises FormulaError, set re-raises it and the sheet is left completely unchanged."
                raise e
        else:
            # Not a formula, check for number vs text
            if stripped_raw.startswith('-'):
                numeric_part = stripped_raw[1:]
                if '.' in numeric_part:
                    try:
                        new_value = float(stripped_raw)
                    except ValueError:
                        pass # Fall through to text
                else:
                    try:
                        new_value = int(stripped_raw)
                    except ValueError:
                        pass # Fall through to text

            if new_value is None:
                # Treat as text if it wasn't a recognizable number, or if it's empty string
                if stripped_raw == "":
                    new_value = None
                else:
                    # Store text exactly as given (spaces included)
                    new_value = raw 

        if is_formula:
            # We don't set the value yet; evaluation happens in recalculate
            self._values[name] = None 
        else:
            # Set literal value immediately
            self._values[name] = new_value

        # Update graph structure BEFORE recalculation (essential for cycle detection during calculation)
        # We must ensure all cells referenced are known in the graph structure, even if they are currently None/empty.
        self.graph.all_cells.add(name)
        for ref_name in parsed_refs:
            self.graph.all_cells.add(ref_name)

        self.graph.set_dependencies(name, parsed_refs)

        # 2. Recalculate
        changed_cells = self._recalculate_affected(name)

        return changed_cells

    def _recalculate_affected(self, changed_source_cell: str) -> List[str]:
        """
        Performs the dependency-aware recalculation starting from the changed cell.
        Returns the list of cells whose values were updated, sorted row-major.
        """

        # 1. Determine the full set of cells that might need recalculation (self + all dependents)
        dependents = self.graph.all_dependents(changed_source_cell)
        cells_to_recalc: Set[str] = dependents.union({changed_source_cell})

        # Ensure we only calculate cells that have formulas or were just changed to a literal.
        cells_to_recalc = {c for c in cells_to_recalc if self._raw_data.get(c) and self._raw_data[c].strip().startswith('=')}

        # Add the source cell if it was a literal change, so its value is finalized for dependents
        if not self._raw_data.get(changed_source_cell, "").strip().startswith('='):
            cells_to_recalc.add(changed_source_cell)

        # 2. Iterative calculation based on dependency order (Topological Sort simulation)

        # We must process cells whose dependencies are finalized first.
        recalculated_this_pass: Set[str] = set()
        final_updated_cells: Set[str] = set()

        # Loop until no new cells are successfully evaluated in a pass
        while True:
            updated_in_pass = set()

            # Sort cells to ensure deterministic order if multiple are ready in one pass
            current_recalc_list = sorted([c for c in cells_to_recalc if c not in final_updated_cells and c not in recalculated_this_pass])

            if not current_recalc_list:
                break # Nothing new to calculate this pass

            for cell_name in current_recalc_list:
                if cell_name in final_updated_cells:
                    continue

                tree = self._formula_trees[cell_name]
                is_on_cycle = cell_name in self.graph.cycle_cells()

                if is_on_cycle:
                    new_value = ERROR_CYCLE
                    # Cycle cells are never evaluated and are marked as updated for propagation
                    updated_in_pass.add(cell_name)
                else:
                    # Check if all precedents are finalized (either literal, or calculated value)
                    precedents = self.graph.precedents(cell_name)
                    all_deps_ready = True

                    for pred in precedents:
                        if pred in self._formula_trees:
                            # Precedent is also a formula cell; check if it has a final value
                            if pred not in final_updated_cells and pred not in recalculated_this_pass:
                                all_deps_ready = False
                                break
                        # If predecessor is not a formula cell, its value is finalized in _values

                    if all_deps_ready:
                        # Perform evaluation
                        lookup = {name: self._values.get(name) for name in self.graph.all_cells}

                        try:
                            new_value = evaluate(tree, lookup)

                            # Check if value actually changed
                            old_value = self._values.get(cell_name)

                            if old_value != new_value:
                                self._values[cell_name] = new_value
                                updated_in_pass.add(cell_name)

                        except Exception:
                            # Catch any calculation failure during evaluation
                            new_value = ERROR_GENERAL
                            self._values[cell_name] = ERROR_GENERAL
                            updated_in_pass.add(cell_name)
                    # Else: Not ready, skip for this pass

            if not updated_in_pass:
                break # Stabilization point reached

            # Update tracking sets
            recalculated_this_pass.update(updated_in_pass)
            final_updated_cells.update(updated_in_pass)

        # 3. Finalize results
        self.evaluations += len(final_updated_cells)

        # Return the updated cells in row-major order
        result_list = sorted(list(final_updated_cells), key=lambda x: (int("".join(filter(str.isdigit, x))), x))
        return result_list


