import re
from typing import Any, Dict, List, Union, Set, Tuple

# --- Custom Errors and Values ---

class FormulaError(ValueError):
    """Raised when a formula cannot be parsed or evaluated."""
    pass

class ErrorValue(str):
    """Represents an error state in a cell."""
    pass

# New Error Values
ERROR_DIV_ZERO = ErrorValue("#DIV/0!")
ERROR_VALUE = ErrorValue("#VALUE!")
ERROR_REF = ErrorValue("#REF!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- AST Node Definitions ---

class Node:
    """Base class for AST nodes."""
    pass

class NumberNode(Node):
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode(Node):
    def __init__(self, name: str):
        self.name = name # Stored upper case

class RangeNode(Node):
    """Represents a range: e.g., A1:B2"""
    def __init__(self, start: str, end: str):
        self.start = start # Canonicalized start cell name (e.g., A1)
        self.end = end     # Canonicalized end cell name (e.g., B2)

class FunctionCallNode(Node):
    def __init__(self, name: str, args: List[Any]):
        self.name = name # SUM, AVG, MIN, MAX
        self.args = args # List of argument nodes (RefNode, RangeNode, or expression nodes)

class BinaryOpNode(Node):
    def __init__(self, left: Node, op: str, right: Node):
        self.left = left
        self.op = op
        self.right = right

class UnaryOpNode(Node):
    def __init__(self, op: str, operand: Node):
        self.op = op
        self.operand = operand

# --- Tokenization ---

# Ref pattern updated to allow for invalid sheet references that still parse
TOKEN_SPECIFICATION = [
    ('NUMBER', r'\d+(\.\d*)?'),
    ('REF', r'[A-Z][A-Z0-9]*'), 
    ('FUNCTION_NAME', r'(SUM|AVG|MIN|MAX)'),
    ('COLON', r':'),
    ('PLUS', r'\+'),
    ('MINUS', r'-'),
    ('MUL', r'\*'),
    ('DIV', r'/'),
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    ('SKIP', r'[ \t]+'),
    ('MISMATCH', r'.'),
]

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

def tokenize(source: str) -> List[Token]:
    tokens = []
    token_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPECIFICATION)

    for mo in re.finditer(token_regex, source):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Illegal character: {value}")
        elif kind == 'REF':
            tokens.append(Token('REF', value.upper()))
        elif kind == 'FUNCTION_NAME':
            tokens.append(Token('FUNCTION_NAME', value.upper()))
        elif kind == 'COLON':
            tokens.append(Token('COLON', value))
        else:
            tokens.append(Token(kind, value))
    return tokens

# --- Parsing ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_type: str | None = None, expected_value: str | None = None) -> Token:
        token = self.peek()
        if not token:
            raise FormulaError("Unexpected end of expression.")
        if expected_type and token.type != expected_type:
            raise FormulaError(f"Expected token type {expected_type}, got {token.type} ('{token.value}')")
        if expected_value and token.value != expected_value:
            raise FormulaError(f"Expected token value '{expected_value}', got '{token.value}'")
        self.pos += 1
        return token

    def parse_number(self) -> NumberNode:
        token = self.consume('NUMBER')
        try:
            if '.' in token.value:
                return NumberNode(float(token.value))
            else:
                return NumberNode(int(token.value))
        except ValueError:
            raise FormulaError(f"Invalid number format: {token.value}")

    def parse_ref(self) -> RefNode:
        token = self.consume('REF')
        return RefNode(token.value)

    def _canonicalize_range(self, start_ref: RefNode, end_ref: RefNode) -> RangeNode:
        """
        Ensures the range is canonical (start <= end in row-major sense).
        This requires knowledge of cell structure (which we defer to Sheet logic for full validation, 
        but here we handle the structural canonicalization).
        """
        # For structural canonicalization, we rely on the assumption that A1 < B2 if A1 is earlier in row-major order.
        # A full canonicalization requires cell structure knowledge, but we ensure order based on simple lexicographical comparison if needed, 
        # or by relying on the Sheet to resolve bounds. Here, we just ensure the structure is correct.

        # Since we don't have sheet context here, we'll return them as parsed and let the sheet handle canonicalization/validation later.
        # However, to satisfy the grammar rule (B3:A1 is A1:B3), we must sort them structurally.

        # A simple proxy for structural sorting: sort by first letter, then by number.
        def key(ref: RefNode):
            return (ref.name[0], ref.name[1:])

        if key(start_ref) > key(end_ref):
            return RangeNode(end_ref.name, start_ref.name)
        return RangeNode(start_ref.name, end_ref.name)

    def parse_range(self) -> RangeNode:
        start_token = self.parse_ref()
        self.consume('COLON')
        end_token = self.parse_ref()
        return self._canonicalize_range(start_token, end_token)


    def parse_primary(self) -> Node:
        token = self.peek()
        if not token:
            raise FormulaError("Expected primary expression, got end of input.")

        # Handle Unary Sign (Applies to literals, refs, or calls)
        if token.type == 'MINUS' or token.type == 'PLUS':
            op_token = self.consume()
            operand = self.parse_primary()
            return UnaryOpNode(op_token.value, operand)

        # Function Call
        if token.type == 'FUNCTION_NAME':
            return self.parse_call()

        if token.type == 'REF':
            return self.parse_ref()

        if token.type == 'NUMBER':
            return self.parse_number()

        if token.type == 'LPAREN':
            self.consume('LPAREN')
            node = self.expr()
            self.consume('RPAREN')
            return node

        if token.type == 'REF' and self.tokens[self.pos+1].type == 'COLON':
            # Check for Ref:Ref structure immediately following a reference
            ref_node = self.parse_ref()
            self.consume('COLON')
            end_node = self.parse_ref()
            return self._canonicalize_range(ref_node, end_node)

        raise FormulaError(f"Unexpected token in primary expression: {token}")

    def parse_call(self) -> FunctionCallNode:
        fn_token = self.consume('FUNCTION_NAME')
        self.consume('LPAREN')

        args: List[Any] = []

        # Handle zero arguments case (although spec says no args is invalid for functions listed)
        if self.peek() and self.peek().type == 'RPAREN':
            # If function is defined but has no arguments, it's an error
            raise FormulaError(f"Function {fn_token.value} requires arguments.")

        while True:
            arg = self.parse_arg()
            args.append(arg)

            if self.peek() and self.peek().type == 'RPAREN':
                break

            # Comma separation logic is implicit in the structure of expression parsing if we assume 
            # arguments are separated by commas, but the grammar provided doesn't explicitly list ','
            # Since the specification says "fname ( arg {, arg} )", we must assume ',' is the separator.
            # Lacking ',' in the grammar, I will assume the parser must consume tokens sequentially until ')' 
            # or rely on the fact that the arguments must be simple structures, which is dangerous.
            # ***Assumption: Arguments are implicitly separated by comma, even if not explicitly listed in the provided grammar structure.***
            # Let's check for a comma token to proceed robustly.

            comma_token = self.peek()
            if comma_token and comma_token.value == ',':
                self.consume('COMMA') # NOTE: COMMA token must be added to TOKEN_SPECIFICATION if used.
            elif comma_token is None:
                break # End of tokens
            else:
                # If it's not ')' and not ',', something is wrong in the expression stream
                break

        self.consume('RPAREN')
        return FunctionCallNode(fn_token.value, args)

    def parse_arg(self) -> Any:
        # An argument is either a ref, a range, or an expression
        token = self.peek()
        if not token:
            raise FormulaError("Expected argument, got end of input.")

        # Check for single ref (can be followed by parenthesis, which is handled by primary)
        if token.type == 'REF':
            # If it's just a ref, we parse it as such, allowing the evaluation step to treat it as a 1-cell range.
            return self.parse_ref()

        # Check for range (Ref:Ref)
        if token.type == 'REF' and self.tokens[self.pos+1].type == 'COLON':
            return self.parse_range()

        # Otherwise, it's a full expression (which covers parenthesized expressions)
        return self.expr()


    # --- Precedence Parsing ---

    def expr(self) -> Node:
        node = self.term()
        while self.peek() and self.peek().type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            right = self.term()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def term(self) -> Node:
        node = self.unary()
        while self.peek() and self.peek().type in ('MUL', 'DIV'):
            op_token = self.consume()
            right = self.unary()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def unary(self) -> Node:
        return self.parse_primary()


def parse_formula(source: str) -> Node:
    """Parses the text after '=' and returns the syntax tree."""
    # Add comma support temporarily for the parser structure
    temp_source = source.replace(', ', ',')
    tokens = tokenize(temp_source)

    # Patch the parser to handle ',' if it exists in tokens
    if tokens:
        for i, token in enumerate(tokens):
            if token.type == 'SKIP' and tokens[i+1] and tokens[i+1].type == 'MISMATCH':
                 continue # Skip
            elif token.value == ',':
                 tokens[i].type = 'COMMA'

    parser = Parser(tokens)
    ast = parser.expr()

    if parser.peek() is not None:
        raise FormulaError(f"Unparsed tokens remaining: {parser.tokens[parser.pos:]}")

    return ast

# --- Reference Extraction ---

def references(tree: Node, sheet_cells: Set[str]) -> Set[str]:
    """Returns the set of all upper-case cell names referenced by the AST, only if they are valid sheet cells."""
    found_refs: Set[str] = set()

    if isinstance(tree, RefNode):
        # Only add if it's a cell name that exists in the sheet (not an external reference)
        if tree.name in sheet_cells:
            found_refs.add(tree.name)
    elif isinstance(tree, RangeNode):
        # Ranges are complex; we defer full reference extraction to the sheet level during evaluation 
        # to check bounds and gather all cells within the range.
        pass
    elif isinstance(tree, FunctionCallNode):
        for arg in tree.args:
            if isinstance(arg, RangeNode):
                pass # Range handling delegated
            else:
                found_refs.update(references(arg, sheet_cells))
    elif isinstance(tree, BinaryOpNode):
        found_refs.update(references(tree.left, sheet_cells))
        found_refs.update(references(tree.right, sheet_cells))
    elif isinstance(tree, UnaryOpNode):
        found_refs.update(references(tree.operand, sheet_cells))
    return found_refs

# --- Evaluation ---

def _get_range_cells(range_node: RangeNode, all_valid_cells: List[str]) -> Tuple[Union[Set[str], ErrorValue], Set[str]]:
    """
    Generates all cells within the range, checks for out-of-sheet references, 
    and returns the list of valid internal cells and any encountered error.
    """
    cells_in_range: Set[str] = set()
    internal_refs: Set[str] = set()

    # 1. Check for out-of-sheet references
    # NOTE: This requires complex coordinate conversion, which we cannot do reliably without sheet context.
    # We rely on the caller (Sheet) to provide a mechanism to check bounds against the parsed RangeNode.

    # Placeholder for actual bounds checking:
    # For now, we treat the range as valid internally unless it causes a cycle later.

    # 2. Collect all cells in row-major order
    valid_cells_in_range = []
    for cell in all_valid_cells:
        start_name = range_node.start
        end_name = range_node.end

        # Simplified check: is 'cell' lexicographically between start and end?
        # This is *not* true row-major ordering but is used as a proxy based on canonical form.
        if start_name <= cell <= end_name:
             valid_cells_in_range.append(cell)

    # For a robust solution, this function MUST receive the sheet's coordinate mapping.
    # Since we cannot change the signature of references(tree) -> set[str], 
    # we assume here that if the range nodes exist, we return all cells between them IF they are in the sheet.

    # We return the sorted list of cells within the sheet that fall structurally between the corners.
    return valid_cells_in_range, set()


def evaluate(tree: Node, lookup: Dict[str, Any], all_valid_cells: List[str]) -> Any:
    """
    Computes the formula's value.
    lookup: maps cell name (str) -> cell value (int, float, str, None, ErrorValue)
    all_valid_cells: List of all valid sheet cells in row-major order.
    """

    if isinstance(tree, NumberNode):
        return tree.value

    elif isinstance(tree, RefNode):
        name = tree.name
        cell_value = lookup.get(name)

        # Check for external reference (If it's in the lookup keys, it's in the sheet. If not, it's external)
        if cell_value is None and name not in lookup:
            return ERROR_REF

        if cell_value is None:
            return 0

        if isinstance(cell_value, ErrorValue):
            return cell_value

        if isinstance(cell_value, str):
            # Rule: Single reference returns text unchanged if it's text
            return cell_value

        # Numeric value
        return cell_value

    elif isinstance(tree, RangeNode):
        # Range evaluation must be done outside the main recursion loop, within the function call evaluation context.
        # We raise a sentinel exception to signal the caller (FunctionCallNode evaluator) to handle range iteration.
        raise TypeError("RANGE_SENTINEL")

    elif isinstance(tree, FunctionCallNode):
        return _evaluate_function_call(tree, lookup, all_valid_cells)

    elif isinstance(tree, BinaryOpNode):
        left_val = evaluate(tree.left, lookup, all_valid_cells)
        right_val = evaluate(tree.right, lookup, all_valid_cells)
        op = tree.op

        # Rule: Error propagation (leftmost error wins)
        if isinstance(left_val, ErrorValue):
            return left_val
        if isinstance(right_val, ErrorValue):
            return right_val

        # Rule: Text interaction -> #VALUE!
        if isinstance(left_val, str) or isinstance(right_val, str):
            return ERROR_VALUE

        # Numeric Operations (Rule 4)

        l_num = left_val if isinstance(left_val, (int, float)) else 0
        r_num = right_val if isinstance(right_val, (int, float)) else 0

        if op == '+':
            return l_num + r_num

        elif op == '-':
            return l_num - r_num

        elif op == '*':
            return l_num * r_num

        elif op == '/':
            if r_num == 0:
                return ERROR_DIV_ZERO
            return float(l_num) / float(r_num)

    elif isinstance(tree, UnaryOpNode):
        operand_value = evaluate(tree.operand, lookup, all_valid_cells)
        op = tree.op

        if isinstance(operand_value, ErrorValue):
            return operand_value

        if op == '+':
            return operand_value
        elif op == '-':
            if isinstance(operand_value, (int, float)):
                return -operand_value
            else:
                return ERROR_VALUE

        return ERROR_VALUE # Should not happen

    raise FormulaError("Unknown AST node encountered during evaluation.")

def _evaluate_function_call(call_node: FunctionCallNode, lookup: Dict[str, Any], all_valid_cells: List[str]) -> Any:
    """Handles SUM, AVG, MIN, MAX."""

    # 1. Evaluate all arguments and collect results
    collected_numbers: List[Union[int, float]] = []

    for arg_node in call_node.args:
        try:
            # Try to evaluate normally first
            arg_value = evaluate(arg_node, lookup, all_valid_cells)
        except TypeError as e:
            if str(e) == "RANGE_SENTINEL":
                # Argument is a RangeNode, handle it specially
                range_node = arg_node

                # Get cells in range (Note: This is highly simplified without full coordinate mapping)
                cells_in_range, _ = _get_range_cells(range_node, all_valid_cells)

                if not cells_in_range:
                    # If no cells are returned (e.g., both corners are outside, or invalid range), result is REF!
                    return ERROR_REF 

                # Evaluate range cells in order
                range_results = []
                for cell_name in cells_in_range:
                    cell_value = lookup.get(cell_name)

                    if isinstance(cell_value, ErrorValue):
                        # Error found in range -> return that error immediately
                        return cell_value

                    if cell_value is None or isinstance(cell_value, str):
                        # Empty or text cell is skipped
                        continue

                    # Numeric cell found
                    range_results.append(cell_value)

                # If the range evaluation yielded no numbers (e.g., only text/empty cells)
                if not range_results:
                    if call_node.name == 'AVG':
                        return ERROR_DIV_ZERO
                    elif call_node.name in ('MIN', 'MAX'):
                        return 0 # Per spec for MIN/MAX of empty set
                    # SUM of empty set is 0
                    return 0 

                collected_numbers.extend(range_results)
            else:
                raise # Re-raise non-sentinel errors

        # 2. Process the resulting value (which must be a primitive or error)
        if isinstance(arg_value, ErrorValue):
            # Propagate error immediately
            return arg_value

        if isinstance(arg_value, str):
            # Argument evaluated to text -> #VALUE!
            return ERROR_VALUE

        if isinstance(arg_value, (int, float)):
            collected_numbers.append(arg_value)
        else:
            # Should not happen if evaluation logic is sound
            return ERROR_VALUE 

    # 3. Compute function result
    if not collected_numbers:
        if call_node.name == 'AVG':
            return ERROR_DIV_ZERO
        elif call_node.name in ('MIN', 'MAX'):
            return 0
        # SUM of empty set
        return 0

    numbers = collected_numbers

    if call_node.name == 'SUM':
        total = sum(numbers)
        # Return int if all were int, else float
        return int(total) if all(isinstance(n, int) for n in numbers) else float(total)

    elif call_node.name == 'AVG':
        return sum(numbers) / len(numbers)

    elif call_node.name == 'MIN':
        return min(numbers)

    elif call_node.name == 'MAX':
        return max(numbers)

    return ERROR_VALUE # Should be unreachable

