class TicTacToe:
    """
    Immutable state object for Tic-Tac-Toe.
    """
    def __init__(self, board: str = '.........'):
        if len(board) != 9:
            raise ValueError("TicTacToe board must be 9 characters long.")

        valid_chars = {'X', 'O', '.'}
        if not all(c in valid_chars for c in board):
            raise ValueError("TicTacToe board must only contain 'X', 'O', or '.'")

        x_count = board.count('X')
        o_count = board.count('O')

        if not (x_count == o_count or x_count == o_count + 1):
            raise ValueError("Impossible counts of 'X' and 'O' on the board.")

        self._board = board
        self._x_count = x_count
        self._o_count = o_count
        self._player = 'X' if x_count == o_count else 'O'

    @property
    def board(self) -> str:
        return self._board

