class ConnectFour:
    """
    Immutable state object for Connect Four.
    Rows are indexed 0 (bottom) to rows-1 (top).
    """
    def __init__(self, columns: int = 7, rows: int = 6):
        if columns < 1 or rows < 1:
            raise ValueError("Columns and rows must be at least 1.")
        self.columns = columns
        self.rows = rows
        self._board = [['.' for _ in range(columns)] for _ in range(rows)]
        self._is_empty = True

    @property
    def columns(self) -> int:
        return self._columns

    @property
    def rows(self) -> int:
        return self._rows

    def __eq__(self, other):
        if not isinstance(other, ConnectFour):
            return NotImplemented
        return self._board == other._board

    def __hash__(self):
        # Hashing based on the tuple representation of the board
        return hash(tuple(tuple(row) for row in self._board))

    def player(self) -> str:
        # Determine player based on piece count (X starts first)
        x_count = sum(row.count('X') for row in self._board)
        o_count = sum(row.count('O') for row in self._board)
        return 'X' if x_count == o_count else 'O'

    def moves(self) -> list[int]:
        # Legal moves are columns that are not full
        return [c for c in range(self.columns) if self.height(c) < self.rows]

    def play(self, col: int) -> 'ConnectFour':
        if col not in self.moves():
            raise ValueError("Illegal move in ConnectFour.")

        # Find the lowest empty row in that column
        row = self.height(col)

        # Create a deep copy of the board
        new_board = [row[:] for row in self._board]

        # Place the piece
        player_piece = self.player()
        new_board[row][col] = player_piece

        # Create and return the new state
        new_state = ConnectFour(self.columns, self.rows)
        new_state._board = new_board
        return new_state

    def cell(self, column: int, row: int) -> str:
        if 0 <= column < self.columns and 0 <= row < self.rows:
            return self._board[row][column]
        raise IndexError("Coordinates out of board bounds.")

    def height(self, col: int) -> int:
        """Returns the 0-indexed row of the next available slot in the column."""
        for r in range(self.rows):
            if self._board[r][col] == '.':
                return r
        return self.rows # Column is full

    def winner(self) -> str | None:
        player_pieces = { 'X': 'X', 'O': 'O' }

        for player in ['X', 'O']:
            if self._check_win(player):
                return player
        return None

    def _check_win(self, player: str) -> bool:
        # Check horizontally, vertically, and two diagonals

        # 1. Horizontal check
        for r in range(self.rows):
            for c in range(self.columns - 3):
                if all(self._board[r][c+i] == player for i in range(4)):
                    return True

        # 2. Vertical check
        for c in range(self.columns):
            for r in range(self.rows - 3):
                if all(self._board[r+i][c] == player for i in range(4)):
                    return True

        # 3. Diagonal (Top-Left to Bottom-Right)
        for r in range(self.rows - 3):
            for c in range(self.columns - 3):
                if all(self._board[r+i][c+i] == player for i in range(4)):
                    return True

        # 4. Diagonal (Bottom-Left to Top-Right)
        for r in range(3, self.rows):
            for c in range(self.columns - 3):
                if all(self._board[r-i][c+i] == player for i in range(4)):
                    return True

        return False


    def is_over(self) -> bool:
        return self.winner() is not None or not self.moves()

    def __str__(self) -> str:
        # Show top row first (row rows-1 down to 0)
        lines = []
        for r in range(self.rows - 1, -1, -1):
            lines.append(" ".join(self._board[r]))
        return '\n'.join(lines)

    @classmethod
    def from_moves(cls, moves: list[int], columns: int = 7, rows: int = 6):
        state = cls(columns, rows)
        for move_col in moves:
            try:
                state = state.play(move_col)
            except ValueError as e:
                raise ValueError(f"Illegal move {move_col} encountered while building state: {e}")
        return state

def evaluate(state: ConnectFour) -> int:
    """Heuristic evaluation for ConnectFour."""
    opponent = 'O' if state.player == 'X' else 'X'
    score = 0

    # Helper to check a line of 4 (window)
    def check_window(window: list[str]) -> int:
        counts = {'X': 0, 'O': 0, '.': 0}
        for cell in window:
            counts[cell] += 1

        # Empty windows or windows with mixed players/four pieces are worth 0
        if counts['X'] + counts['O'] == 0 or counts['X'] + counts['O'] == 4:
            return 0

        # Score based on player who is 'state.player'
        if counts[state.player] > 0 and counts[opponent] > 0:
            # Mixed pieces -> 0
            return 0

        # Only one player present
        n = counts[state.player]
        return n * n

    # 1. Horizontal windows
    for r in range(state.rows):
        for c in range(state.columns - 3):
            window = [state.cell(c+i, r) for i in range(4)]
            score += check_window(window)

    # 2. Vertical windows
    for c in range(state.columns):
        for r in range(state.rows - 3):
            window = [state.cell(c, r+i) for i in range(4)]
            score += check_window(window)

    # 3. Diagonal (TL-BR) windows
    for r in range(state.rows - 3):
        for c in range(state.columns - 3):
            window = [state.cell(c+i, r+i) for i in range(4)]
            score += check_window(window)

    # 4. Diagonal (BL-TR) windows
    for r in range(3, state.rows):
        for c in range(state.columns - 3):
            window = [state.cell(c+i, r-i) for i in range(4)]
            score += check_window(window)

    return score
