# Define type hints for clarity
State = Any # Any object conforming to the game interface
Move = Any

@dataclass(frozen=True)
class SearchResult:
    score: float
    move: Optional[Move]
    nodes: int

T = TypeVar('T')

# --- Core Search Logic ---

def search(state: State, depth: Optional[int] = None, evaluate: Optional[Callable[[State], float]] = None) -> SearchResult:
    """
    Negamax search with alpha-beta pruning.
    """

    # Memoization for state evaluation (optional, but good practice for tree search)
    # Since the requirement implies state equality based on board structure, we use that.
    # A dictionary mapping state hashes to results/values could be added here if needed for performance, 
    # but we adhere strictly to the functional description without external cache management for simplicity.

    def negamax(current_state: State, current_depth: int, alpha: float, beta: float, is_root: bool) -> tuple[float, Optional[Move], int]:
        """
        Returns (value, best_move, nodes_examined)
        Value is relative to the player *whose turn it is in current_state*.
        """
        nodes_count = 1

        # 1. Check for terminal state or depth limit
        if current_state.is_over() or (depth is not None and current_depth >= depth):
            if current_state.is_over():
                # Terminal state: Score relative to the player who *was* supposed to move here (the opponent of the player whose turn it is now)

                # Determine ply (distance from root, assumed 0 at root)
                # In this structure, we don't track ply easily, so we must estimate based on depth.
                # If depth is None, the game length is the true ply. If depth is set, the final ply is related to current_depth.

                # Since the prompt specifies scoring for the player to move *in it* (current_state), 
                # if it's terminal, the score is calculated for the player who *just moved* (i.e., the previous player).
                # This is complex for Negamax implementation without explicit ply tracking.

                # Let's interpret "scored for the player to move in it" as: 
                # If terminal, score is for the player *who won* (the previous player), scaled by the depth achieved.

                winner = current_state.winner()
                if winner is None: # Draw
                    return 0.0, None, nodes_count

                # If player X won (winner == 'X'), and it is now O's turn (current_state.player == 'O'), 
                # the score must reflect the advantage for O.

                # If current_state.player is P, the score must be relative to P.

                # If P won (P == winner), score should be high.
                # If Opponent won (P != winner), score should be low (negative).

                # Let's use the standard definition: score is for the player whose turn it is (current_state.player).

                # If current_state.player won (impossible if is_over() is true and winner() is set, unless the game state is ill-defined):
                # Assume the *last* player to move (the winner) was the one whose turn it was *before* this state was reached.

                # Simplified interpretation based on prompt:
                # "A finished game is scored for the player to move in it: 0 for a draw, and -(1000 - ply) for a loss"

                # If current_state is terminal, ply = total moves made.
                # We use (MAX_DEPTH - current_depth) as a proxy for ply if depth is set, or use a large fixed value if depth is None.

                MAX_PLY = 100 # A sufficiently large number for non-depth limited games

                if depth is None:
                    # If no depth limit, we don't know ply accurately from the state alone, so we use a large constant.
                    ply = MAX_PLY 
                else:
                    # If depth was set, the number of moves made is depth - current_depth, but this is complex.
                    # We assume 'ply' in the prompt means the actual depth reached from the root.
                    # If we reached depth D, ply = D.
                    ply = depth

                if winner == current_state.player:
                    # Win for the current player (rare/impossible if logic is perfect, but safety)
                    return 1000 - ply, None, nodes_count
                elif winner is not None:
                    # Loss for the current player
                    return -(1000 - ply), None, nodes_count
                else: # Draw
                    return 0.0, None, nodes_count

            elif evaluate:
                # Depth limit reached
                score = evaluate(current_state)
                return score, None, nodes_count
            else:
                # Depth limit reached, no evaluation function
                return 0.0, None, nodes_count

        # 2. Recursive step (Negamax)
        best_val = -float('inf')
        best_move_found = None
        nodes_examined = 0

        moves_list = current_state.moves()

        for move in moves_list:
            next_state = current_state.play(move)

            # Recursive call: switch perspective by negating the result
            # The returned value is relative to next_state.player. We negate it to get the value relative to current_state.player.
            val, _, sub_nodes = negamax(next_state, current_depth + 1, -beta, -alpha, False)

            # Negate value for the current player's perspective
            negated_val = -val

            nodes_examined += sub_nodes

            # Update best value (choosing the first move in case of ties)
            if negated_val > best_val:
                best_val = negated_val
                best_move_found = move

            # Alpha-Beta Pruning Update
            alpha = max(alpha, best_val)
            if alpha >= beta:
                break # Beta cutoff

        return best_val, best_move_found, nodes_examined

    # --- Root Call Setup ---

    # For the root node, we must iterate through all moves to find the true best move, 
    # and track the total node count accurately.

    root_state = state
    initial_player = root_state.player()

    best_val = -float('inf')
    best_move_found = None
    total_nodes = 0

    moves_list = root_state.moves()

    for move in moves_list:
        next_state = root_state.play(move)

        # Initial call to negamax from the next state. 
        # The returned value is relative to next_state.player (i.e., the opponent of initial_player).
        # We negate it to get the value relative to initial_player.

        # Start with initial alpha/beta: (-inf, +inf)
        val, _, sub_nodes = negamax(next_state, 1, -float('inf'), float('inf'), False)

        negated_val = -val

        total_nodes += sub_nodes

        # Update best move (choosing the first move in case of ties)
        if negated_val > best_val:
            best_val = negated_val
            best_move_found = move

    return SearchResult(
        score=best_val, 
        move=best_move_found, 
        nodes=total_nodes
    )


def best_move(state: State, depth: Optional[int] = None, evaluate: Optional[Callable[[State], float]] = None) -> Move:
    """Returns the move that achieves the highest score."""
    result = search(state, depth, evaluate)
    if result.move is None:
        raise ValueError("Game is already over or no moves are possible.")
    return result.move

# --- Agent Functions ---

def search_agent(depth: Optional[int] = None, evaluate: Optional[Callable[[State], float]] = None) -> Callable[[State], Move]:
    """Returns an agent that plays best_move."""
    return lambda state: best_move(state, depth, evaluate)

def random_agent(seed: int) -> Callable[[State], Move]:
    """Returns an agent that plays a random legal move."""
    import random
    rng = random.Random(seed)

    def agent(state: State) -> Move:
        moves = state.moves()
        if not moves:
            raise ValueError("Cannot move, game is over.")
        return rng.choice(moves)

    return agent

# --- Game Play ---

def play_game(state: State, agents: Dict[str, Callable[[State], Move]]) -> tuple[State, list[Move]]:
    """
    Plays the game turn by turn using the provided agents.
    Returns the final state and the list of moves played.
    """
    current_state = state
    moves_history = []

    while not current_state.is_over():
        player = current_state.player()
        if player not in agents:
            raise ValueError(f"No agent provided for player {player}.")

        agent_func = agents[player]

        try:
            move = agent_func(current_state)
        except ValueError as e:
            raise ValueError(f"Agent for {player} attempted illegal move: {e}")

        try:
            next_state = current_state.play(move)
        except ValueError as e:
            # This catches errors from state.play() if the move was somehow deemed legal by agent but not by state rules
            raise ValueError(f"Move {move} is illegal in the current game state: {e}")

        current_state = next_state
        moves_history.append(move)

    return current_state, moves_history
