# --- NFA Structures ---

class State:
    """Represents a state in the NFA."""
    def __init__(self):
        self.transitions: Dict[str, List['State']] = {}
        self.is_accepting: bool = False

class NFA:
    """Thompson's NFA structure."""
    def __init__(self, start_state: State, accept_state: State):
        self.start = start_state
        self.accept = accept_state

    def _epsilon_closure(self, states: Set[State]) -> Set[State]:
        """Computes the epsilon closure for a set of states."""
        closure = set(states)
        stack = list(states)
        while stack:
            state = stack.pop()
            if 'epsilon' in state.transitions:
                for next_state in state.transitions['epsilon']:
                    if next_state not in closure:
                        closure.add(next_state)
                        stack.append(next_state)
        return closure

    def match(self, text: str) -> bool:
        """Checks if the entire text matches the NFA."""
        initial_states = {self.start}
        current_states = self._epsilon_closure(initial_states)

        for char in text:
            next_states: Set[State] = set()
            for state in current_states:
                # Process transitions for the current character
                if char in state.transitions:
                    for next_state in state.transitions[char]:
                        next_states.add(next_state)

                # Process epsilon transitions (handled implicitly by closure calculation)

            # Combine with epsilon closure for the next step
            current_states = self._epsilon_closure(next_states)

        return bool(current_states.intersection({self.accept}))

    def search(self, text: str, start: int = 0) -> Optional[Tuple[int, int]]:
        """
        Finds the leftmost, longest match starting at or after 'start'.
        Returns (start_index, end_index), or None.
        """
        N = len(text)
        best_match: Optional[Tuple[int, int]] = None
        max_length = -1

        # Iterate through all possible start positions
        for i in range(start, N + 1):
            # Initialize state tracking for this potential match starting at i

            # We use a simplified, iterative simulation adapted for searching.
            # Since we must find the *longest* match starting at *i*, we simulate 
            # the NFA from i forward, tracking the set of active states at each position j.

            # State set at the beginning of the simulation
            current_states: Set[State] = {self.start}
            current_states = self._epsilon_closure(current_states)

            # Track all positions j where an accepting state is reachable
            possible_ends: Set[int] = set()

            # Initial check for zero-length match at i
            if self.accept in current_states:
                 possible_ends.add(i)

            # Simulate character by character from i
            for j in range(i, N):
                char = text[j]
                next_states: Set[State] = set()

                for state in current_states:
                    # Process transitions for the current character
                    if char in state.transitions:
                        for next_state in state.transitions[char]:
                            next_states.add(next_state)

                # Calculate closure for the next position j+1
                current_states = self._epsilon_closure(next_states)

                # Check if any accepting state is reached at position j+1
                if self.accept in current_states:
                    possible_ends.add(j + 1)

            # After processing all text, determine the longest match found starting at i
            if possible_ends:
                end_j = max(possible_ends)
                length = end_j - i

                # Update best match based on requirements: leftmost, then longest
                if best_match is None or i < best_match[0] or (i == best_match[0] and length > max_length):
                    best_match = (i, end_j)
                    max_length = length

        return best_match


    def findall(self, text: str) -> List[str]:
        """
        Finds all non-overlapping matches.
        """
        results: List[str] = []
        current_pos = 0
        N = len(text)

        while current_pos <= N:
            # Search for the next match starting at current_pos
            match = self.search(text, current_pos)

            if match is None:
                break

            start_i, end_j = match
            matched_string = text[start_i:end_j]
            results.append(matched_string)

            # Advance position based on matching rules
            if end_j > start_i:
                # Non-empty match: continue search after the match ends
                current_pos = end_j
            else:
                # Empty match: continue search from the position immediately after the start
                current_pos = start_i + 1

        return results


