        return NFA(s, a)

    elif isinstance(node, Concat):
        # Concatenation: Run NFA1 followed by NFA2, connecting NFA1's accept to NFA2's start via epsilon.
        nfa_parts = []
        for item in node.items:
            nfa_parts.append(_compile_ast(item))

        if not nfa_parts:
             return NFA(_new_state(), _new_state()) # Should be covered by Empty()

        start_nfa = nfa_parts[0]
        current_end_state = nfa_parts[0].accept

        for i in range(1, len(nfa_parts)):
            next_nfa = nfa_parts[i]
            # Connect previous end state to next start state via epsilon
            _add_transition(current_end_state, 'epsilon', next_nfa.start)
            current_end_state = next_nfa.accept

        return NFA(start_nfa.start, current_end_state)

    elif isinstance(node, Alt):
        # Alternation: New start state, new accept state. 
        # Epsilon transitions from start to all options' starts, and all options' accepts to the new accept state.
        s = _new_state()
        a = _new_state()

        for option in node.options:
            nfa_opt = _compile_ast(option)

            # Connect new start to option start
            _add_transition(s, 'epsilon', nfa_opt.start)
            # Connect option accept to new accept
            _add_transition(nfa_opt.accept, 'epsilon', a)

        return NFA(s, a)

    elif isinstance(node, Star):
        # Star: New start/accept. Epsilon from start to accept, start to self via loop, and accept to self via loop.
        # (Simplified: s -> a, s -> s, a -> a)
        s = _new_state()
        a = _new_state()
        nfa_body = _compile_ast(node.node)

        # 1. s -> a (zero occurrences)
        _add_transition(s, 'epsilon', a)
        # 2. s -> body start
        _add_transition(s, 'epsilon', nfa_body.start)
        # 3. body accept -> a (loop back)
        _add_transition(nfa_body.accept, 'epsilon', a)
        # 4. body accept -> body start (looping)
        _add_transition(nfa_body.accept, 'epsilon', nfa_body.start)

        return NFA(s, a)

    # Plus and Optional would follow similar patterns to Star

    else:
        raise TypeError(f"Unsupported AST node type during compilation: {type(node)}")


def compile(pattern_or_ast: Union[str, ASTNode]) -> NFA:
    """Compiles a pattern string or an AST into an NFA."""
    if isinstance(pattern_or_ast, str):
        try:
            ast = parse(pattern_or_ast)
            return _compile_ast(ast)
        except RegexError as e:
            raise e
        except Exception as e:
            raise RegexError(f"Compilation failed: {e}", 0)
    elif isinstance(pattern_or_ast, ASTNode):
        return _compile_ast(pattern_or_ast)
    else:
        raise TypeError("Input must be a pattern string or an ASTNode.")


# --- Module Level Wrappers ---

def match(pattern: str, text: str) -> bool:
    """Matches if the entire text matches the pattern."""
    nfa = compile(pattern)
    return nfa.match(text)

def search(pattern: str, text: str, start: int = 0) -> Optional[Tuple[int, int]]:
    """Searches for the leftmost, longest match."""
    nfa = compile(pattern)
    return nfa.search(text, start)

def findall(pattern: str, text: str) -> List[str]:
    """Finds all non-overlapping matches."""
    nfa = compile(pattern)
    return nfa.findall(text)
