```python
from typing import NamedTuple, List, Iterator

class JSONError(ValueError):
    """Custom error for JSON parsing issues."""
    def __init__(self, msg: str, line: int, column: int):
        self.msg = msg
        self.line = line
        self.column = column
        super().__init__(f"{msg} at line {line} column {column}")

class Token(NamedTuple):
    kind: str
    value: any
    line: int
    column: int

def tokenize(text: str, *, allow_nan: bool = False) -> List[Token]:
    """
    Scans the input text and returns a list of Tokens.
    """
    tokens: List[Token] = []
    line = 1
    column = 1
    i = 0
    n = len(text)

    def advance(offset=1):
        nonlocal i, line, column
        if i < n:
            char = text[i]
            i += offset
            if char == '\n':
                line += 1
                column = 1
            else:
                column += offset
        else:
            i += offset

    def get_position(offset=0):
        """Returns the line and column of the character *at* index i+offset."""
        return line, column

    while i < n:
        char = text[i]

        # Skip whitespace
        if char in ' \t\n\r':
            if char == '\n':
                line += 1
                column = 1
            elif char == '\r':
                column += 1
            else: # ' ' or '\t'
                column += 1
            i += 1
            continue

        # Check for structural characters
        if char in '{[]:,}':
            kind = char
            tokens.append(Token(kind, None, line, column))
            i += 1
            continue

        # String literal
        if char == '"':
            start_line, start_column = line, column
            i += 1
            value_parts = []

            while i < n:
                char = text[i]

                if char == '"':
                    tokens.append(Token('STRING', "".join(value_parts), start_line, start_column))
                    i += 1
                    break

                elif char == '\\':
                    i += 1
                    if i >= n:
                        raise JSONError("Unterminated string: missing escape sequence end", start_line, start_column)

                    escape_char = text[i]

                    if escape_char in ('"', '\\', '/', 'b', 'f', 'n', 'r', 't'):
                        if escape_char == 'b':
                            value_parts.append('\b')
                        elif escape_char == 'f':
                            value_parts.append('\f')
                        elif escape_char == 'n':
                            value_parts.append('\n')
                        elif escape_char == 'r':
                            value_parts.append('\r')
                        elif escape_char == 't':
                            value_parts.append('\t')
                        elif escape_char == '"':
                            value_parts.append('"')
                        elif escape_char == '\\':
                            value_parts.append('\\')
                        elif escape_char == '/':
                            value_parts.append('/')
                        i += 1

                    elif escape_char == 'u':
                        # Unicode escape \uXXXX
                        if i + 4 >= n:
                            raise JSONError("Invalid Unicode escape sequence: incomplete hex code", start_line, start_column)

                        hex_digits = text[i+1 : i+5]
                        if not all(c in '0123456789abcdefABCDEF' for c in hex_digits):
                            raise JSONError("Invalid Unicode escape sequence: non-hex character", start_line, start_column)

                        try:
                            code_point = int(hex_digits, 16)
                        except ValueError:
                             raise JSONError("Invalid Unicode escape sequence: hex conversion failed", start_line, start_column)

                        i += 5 # Skip \uXXXX

                        # Surrogate pair handling logic (simplified for scanner based on spec constraints)
                        # We decode the character as is, trusting that if it's a high surrogate, 
                        # the context requires the low surrogate to follow in the source string, 
                        # and the parser/serializer will handle the final validation if needed.
                        # However, to adhere to the strict check:

                        if 0xD800 <= code_point <= 0xDBFF: # High surrogate
                            # Check if the next sequence *is* a low surrogate escape
                            # This requires lookahead beyond the current token, which is complex.
                            # We decode the high surrogate now, and the parser must accept it if it's part of a sequence.
                            value_parts.append(chr(code_point))
                        elif 0xDC00 <= code_point <= 0xDFFF: # Low surrogate on its own
                            raise JSONError("Unexpected lone low surrogate", start_line, start_column)
                        else:
                            # Valid scalar code point
                            value_parts.append(chr(code_point))

                    else:
                        raise JSONError(f"Unknown escape sequence '\\{escape_char}'", start_line, start_column)
                    i += 1
                else:
                    # Raw control character check (U+0000–U+001F)
                    if 0x00 <= ord(char) <= 0x1F and char not in ['\b', '\f', '\n', '\r', '\t']:
                        # If it's a control character and wasn't one of the predefined escapes
                        raise JSONError(f"Raw control character U+{ord(char):04X} found inside string", start_line, start_column)

                    value_parts.append(char)
                    i += 1

            else:
                # Loop finished without hitting 'break' -> Unterminated string
                raise JSONError("Unterminated string literal", start_line, start_column)

            continue

        # Number literal
        if char in '-0123456789':
            start_line, start_column = line, column
            j = i

            # Read sequence of allowed characters
            while j < n and text[j] in '0123456789+-eE.':
                j += 1

            num_str = text[i:j]
            i = j

            try:
                if num_str == "NaN" and allow_nan:
                    value = float('nan')
                elif num_str == "Infinity" and allow_nan:
                    value = float('inf')
                elif num_str == "-Infinity" and allow_nan:
                    value = float('-inf')
                elif '.' in num_str or 'e' in num_str or 'E' in num_str:
                    # Float parsing path
                    value = float(num_str)
                else:
                    # Integer parsing path
                    value = int(num_str)

                # Special case: -0 is int 0
                if value == 0.0 and num_str.strip().startswith("-0"):
                    value = 0

                # If NaN/Inf handling is disabled, these keywords are treated as invalid literals/numbers
                if not allow_nan and num_str in ("NaN", "Infinity", "-Infinity"):
                    raise JSONError("Literal 'NaN' or 'Infinity' is not allowed in strict mode", start_line, start_column)

                # Check structural validity for JSON numbers
                if ('.' in num_str and num_str.count('.') > 1) or \
                   ('e' in num_str or 'E' in num_str) and (num_str.count('e') > 1 or num_str.count('E') > 1):
                    raise JSONError("Invalid number format", start_line, start_column)

                tokens.append(Token('NUMBER', value, start_line, start_column))
                continue

            except ValueError:
                # Catches float conversion errors, or the explicit check for disallowed keywords
                raise JSONError("Invalid number format", start_line, start_column)

        # Literal (true, false, null, NaN, Infinity)
        if char in 'tfn':
            start_line, start_column = line, column
            j = i
            while j < n and text[j].isalnum():
                j += 1
            literal_str = text[i:j]
            i = j

            if literal_str == "true":
                tokens.append(Token('TRUE', True, start_line, start_column))
            elif literal_str == "false":
                tokens.append(Token('FALSE', False, start_line, start_column))
            elif literal_str == "null":
                tokens.append(Token('NULL', None, start_line, start_column))
            elif literal_str == "NaN" and allow_nan:
                tokens.append(Token('NUMBER', float('nan'), start_line, start_column))
            elif literal_str == "Infinity" and allow_nan:
                tokens.append(Token('NUMBER', float('inf'), start_line, start_column))
            elif literal_str == "-Infinity" and allow_nan:
                 # This case should ideally be caught by the number block if starting with '-'
                 raise JSONError("Invalid literal syntax for -Infinity", start_line, start_column)
            else:
                # Invalid literal (e.g., "trueX", "nul")
                raise JSONError("Invalid literal", start_line, start_column)
            continue

        # Unexpected character
        raise JSONError(f"Unexpected character '{char}'", line, column)

    # End of File
    tokens.append(Token('EOF', None, line, column))
    return tokens
