### `js/parser.py`

```python
from typing import List, Any
from .scanner import tokenize, Token, JSONError

# Define expected token types for clarity
EOF = 'EOF'
STRING = 'STRING'
NUMBER = 'NUMBER'
TRUE = 'TRUE'
FALSE = 'FALSE'
NULL = 'NULL'
LBRACE = '{'
RBRACE = '}'
LBRACK = '['
RBRACK = ']'
COLON = ':'
COMMA = ','

class Parser:
    def __init__(self, tokens: List[Token], duplicate_keys_policy: str, max_depth: Optional[int]):
        self.tokens = tokens
        self.pos = 0
        self.duplicate_keys_policy = duplicate_keys_policy
        self.max_depth = max_depth

    def peek(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        raise IndexError("Attempted to peek past EOF")

    def consume(self, expected_kind: str = None, expected_value: Any = None) -> Token:
        token = self.peek()
        if expected_kind and token.kind != expected_kind:
            raise JSONError(
                f"Expected token type '{expected_kind}', but got '{token.kind}' ('{token.value}')",
                token.line, token.column
            )
        if expected_value is not None and token.value != expected_value:
            raise JSONError(
                f"Expected token value '{expected_value}', but got '{token.value}'",
                token.line, token.column
            )
        self.pos += 1
        return token

    def parse(self) -> Any:
        # Start parsing at depth 1 for the top-level structure
        value = self._parse_value(1)

        # Rule: Nothing but whitespace after the top-level value
        if self.peek().kind != EOF:
            raise JSONError(
                f"Unexpected token '{self.peek().kind}' after top-level value",
                self.peek().line, self.peek().column
            )
        return value

    def _parse_value(self, current_depth: int) -> Any:
        token = self.peek()

        if token.kind == STRING:
            self.consume(STRING)
            return token.value
        elif token.kind == NUMBER:
            self.consume(NUMBER)
            return token.value
        elif token.kind == TRUE:
            self.consume(TRUE)
            return True
        elif token.kind == FALSE:
            self.consume(FALSE)
            return False
        elif token.kind == NULL:
            self.consume(NULL)
            return None
        elif token.kind == LBRACE:
            return self._parse_object(current_depth)
        elif token.kind == LBRACK:
            return self._parse_array(current_depth)
        else:
            if token.kind == EOF:
                 raise JSONError("Unexpected end of input while parsing value", token.line, token.column)
            raise JSONError(f"Unexpected token '{token.kind}' where value was expected", token.line, token.column)

    def _parse_array(self, current_depth: int) -> List[Any]:
        self.consume(LBRACK)
        arr = []

        if self.max_depth is not None and current_depth + 1 > self.max_depth:
            # Error points at the opening bracket
            raise JSONError("Nesting depth limit exceeded", self.tokens[self.pos - 1].line, self.tokens[self.pos - 1].column)

        # Check for empty array
        if self.peek().kind == RBRACK:
            self.consume(RBRACK)
            return arr

        while True:
            value = self._parse_value(current_depth + 1)
            arr.append(value)

            next_token = self.peek()

            if next_token.kind == COMMA:
                self.consume(COMMA)
            elif next_token.kind == RBRACK:
                self.consume(RBRACK)
                break
            else:
                raise JSONError(f"Expected ',' or ']' in array, but got '{next_token.kind}'", next_token.line, next_token.column)

        return arr

    def _parse_object(self, current_depth: int) -> dict:
        self.consume(LBRACE)
        obj = {}

        if self.max_depth is not None and current_depth + 1 > self.max_depth:
            # Error points at the opening brace
            raise JSONError("Nesting depth limit exceeded", self.tokens[self.pos - 1].line, self.tokens[self.pos - 1].column)

        # Check for empty object
        if self.peek().kind == RBRACE:
            self.consume(RBRACE)
            return obj

        while True:
            key_token = self.consume(STRING)
            key = key_token.value

            # Key validation (checked against policy before proceeding to value)
            if self.duplicate_keys_policy == 'error':
                if key in obj:
                    raise JSONError(f"Duplicate key found: '{key}'", key_token.line, key_token.column)

            # Handle key insertion based on policy
            if self.duplicate_keys_policy == 'first' and key in obj:
                # Ignore subsequent values, just consume the rest of the pair
                self.consume(COLON)
                self._skip_value()
                continue # Move to next potential key/comma

            if self.duplicate_keys_policy == 'last' and key in obj:
                # Last value wins, overwrite
                pass

            # Must be followed by a colon
            self.consume(COLON)

            # Parse value, using depth + 1
            value = self._parse_value(current_depth + 1)
            obj[key] = value

            next_token = self.peek()

            if next_token.kind == COMMA:
                self.consume(COMMA)
            elif next_token.kind == RBRACE:
                self.consume(RBRACE)
                break
            else:
                raise JSONError(f"Expected ',' or '}}' in object, but got '{next_token.kind}'", next_token.line, next_token.column)

        return obj

    def _skip_value(self):
        """Helper to consume an entire value structure without parsing it."""
        token = self.peek()
        if token.kind == STRING:
            self.consume(STRING)
        elif token.kind == NUMBER:
            self.consume(NUMBER)
        elif token.kind == TRUE:
            self.consume(TRUE)
        elif token.kind == FALSE:
            self.consume(FALSE)
        elif token.kind == NULL:
            self.consume(NULL)
        elif token.kind == LBRACE:
            self._parse_object(0) # Dummy depth, only structure matters here
        elif token.kind == LBRACK:
            self._parse_array(0) # Dummy depth
        else:
            # Should not happen if called correctly mid-object
            raise JSONError(f"Expected value start, got {token.kind}", token.line, token.column)


def loads(text: str, *, duplicate_keys: str = 'last', max_depth: Optional[int] = None, allow_nan: bool = False) -> Any:
    """Parses a JSON string into a Python object."""

    if duplicate_keys not in ('last', 'first', 'error'):
        raise ValueError(f"Invalid duplicate_keys policy: {duplicate_keys}")
    if max_depth is not None and (not isinstance(max_depth, int) or max_depth < 1):
        raise ValueError("max_depth must be None or an integer >= 1")

    tokens = tokenize(text, allow_nan=allow_nan)
    parser = Parser(tokens, duplicate_keys_policy=duplicate_keys, max_depth=max_depth)
    return parser.parse()
