### `js/dump.py`

```python
from typing import Any, Optional, Union
import math

# --- Cycle Checking ---

def _check_cycles(obj: Any, seen: set) -> None:
    """Recursively checks for self-referencing structures using object IDs."""
    if isinstance(obj, dict):
        for k, v in obj.items():
            # Check value for cycle
            if id(v) in seen:
                raise ValueError("Circular structure detected")
            seen.add(id(v))
            _check_cycles(v, seen)
            seen.remove(id(v))
            # Keys are strings, so checking key ID is usually redundant unless keys are complex types,
            # but we only expect string keys in JSON.
    elif isinstance(obj, (list, tuple)):
        for item in obj:
            # Check item for cycle
            if id(item) in seen:
                raise ValueError("Circular structure detected")
            seen.add(id(item))
            _check_cycles(item, seen)
            seen.remove(id(item))

# --- Number Formatting ---

def _format_number(n: Any, allow_nan: bool) -> str:
    """Formats numbers according to JSON rules, respecting NaN/Inf flags."""
    if isinstance(n, int):
        return str(n)
    if isinstance(n, float):
        if math.isnan(n):
            if allow_nan:
                return "NaN"
            else:
                raise ValueError("JSON does not support NaN when allow_nan=False")
        if math.isinf(n):
            if n > 0:
                return "Infinity" if allow_nan else _raise_inf_error(n)
            else:
                return "-Infinity" if allow_nan else _raise_inf_error(n)

        # Finite float
        # We use repr() to get a standard representation, then strip the surrounding quotes if present (shouldn't be)
        return repr(n).replace("'", "")
    raise TypeError(f"Unsupported number type: {type(n)}")

def _raise_inf_error(n: float):
    """Raises the specific error required when NaN/Inf is disallowed."""
    if n > 0:
        raise ValueError("JSON does not support Infinity when allow_nan=False")
    else:
        raise ValueError("JSON does not support -Infinity when allow_nan=False")


# --- String Escaping ---

def _escape_string(s: str, ensure_ascii: bool) -> str:
    """Escapes characters for JSON string representation."""
    escaped = []
    for char in s:
        cp = ord(char)
        if char == '"':
            escaped.append('\\"')
        elif char == '\\':
            escaped.append('\\\\')
        elif char == '\b':
            escaped.append('\\b')
        elif char == '\f':
            escaped.append('\\f')
        elif char == '\n':
            escaped.append('\\n')
        elif char == '\r':
            escaped.append('\\r')
        elif char == '\t':
            escaped.append('\\t')
        elif cp < 0x20:
            # Control characters U+0000–U+001F
            if ensure_ascii:
                # Must use \u00xx
                escaped.append(f"\\u{cp:04x}")
            else:
                # Write raw control character
                escaped.append(chr(cp))
        elif ensure_ascii and cp > 0x7F:
            # Characters above U+007F
            if cp <= 0xFFFF:
                escaped.append(f"\\u{cp:04x}")
            else:
                # Surrogate pair required for characters > U+FFFF
                high = 0xD800 + ((cp - 0x10000) // 0x400)
                low = 0xDC00 + ((cp - 0x10000) % 0x400)
                escaped.append(f"\\u{high:04x}")
                escaped.append(f"\\u{low:04x}")
        else:
            # Normal characters or non-ASCII characters when ensure_ascii=False
            escaped.append(char)

    return "".join(escaped)

# --- Recursive Dumping Logic ---

def _dump_recursive(obj: Any, indent: Optional[int], sort_keys: bool, ensure_ascii: bool, allow_nan: bool, seen: set) -> str:

    if isinstance(obj, dict):
        if not isinstance(obj, dict):
            raise TypeError("Object container must be a dict")

        # Cycle check on object container itself
        if id(obj) in seen:
            raise ValueError("Circular structure detected")
        seen.add(id(obj))

        if not obj:
            return "{}"

        # Prepare keys
        keys = list(obj.keys())
        if sort_keys:
            keys.sort()

        items = []
        for key in keys:
            if not isinstance(key, str):
                raise TypeError("Dictionary key must be a string")

            # Recursively dump key (which should always be a string)
            key_str = _dump_recursive(key, indent, sort_keys, ensure_ascii, allow_nan, seen)

            value = obj[key]
            value_str = _dump_recursive(value, indent, sort_keys, ensure_ascii, allow_nan, seen)

            # JSON format: "key": value
            item = f'"{key_str}": {value_str}'
            items.append(item)

        seen.remove(id(obj))

        if not indent:
            return "{" + ",".join(items) + "}"
        else:
            ind = " " * indent
            body = ",\n".join([f"{ind}  {item}" for item in items])
            return f"{ind}{{\n{body}\n{ind}}}"

    elif isinstance(obj, (list, tuple)):
        # Tuples become lists
        if not isinstance(obj, (list, tuple)):
            raise TypeError(f"Unsupported type for container: {type(obj)}")

        # Cycle check on container itself
        if id(obj) in seen:
            raise ValueError("Circular structure detected")
        seen.add(id(obj))

        elements = []
        for item in obj:
            element_str = _dump_recursive(item, indent, sort_keys, ensure_ascii, allow_nan, seen)
            elements.append(element_str)

        seen.remove(id(obj))

        if not indent:
            return "[" + ",".join(elements) + "]"
        else:
            ind = " " * indent
            body = ",\n".join([f"{ind}  {e}" for e in elements])
            return f"{ind}[\n{body}\n{ind}]"

    # Scalar types
    elif obj is None:
        return "null"
    elif obj is True:
        return "true"
    elif obj is False:
        return "false"
    elif isinstance(obj, (int, float)):
        return _format_number(obj, allow_nan)
    elif isinstance(obj, str):
        return f'"{_escape_string(obj, ensure_ascii)}"'
    else:
        raise TypeError(f"Object of type {type(obj).__name__} is not serializable.")


def dumps(obj: Any, *, indent: Optional[int] = None, sort_keys: bool = False, ensure_ascii: bool = True, allow_nan: bool = False) -> str:
    """Serializes a Python object into a JSON formatted string."""

    if indent is not None and indent < 0:
        raise ValueError("Indent level cannot be negative")

    # Cycle checking requires tracking object identity
    seen: set[int] = set()

    try:
        result = _dump_recursive(obj, indent, sort_keys, ensure_ascii, allow_nan, seen)
        return result
    except (ValueError, TypeError) as e:
        # Re-raise all errors encountered during dumping
        raise e
