# resolve/versions.py
from typing import Tuple

class Version:
    def __init__(self, text: str):
        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Version '{text}' must be in MAJOR.MINOR.PATCH format.")

        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Check for leading zeros unless the part is exactly '0'
        for i, part in enumerate(parts):
            if len(part) > 1 and part.startswith('0'):
                raise ValueError(f"Version part '{part}' in '{text}' cannot have leading zeros.")

        self.major = major
        self.minor = minor
        self.patch = patch

    def __lt__(self, other: 'Version') -> bool:
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __gt__(self, other: 'Version') -> bool:
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch

    def __hash__(self) -> int:
        return hash((self.major, self.minor, self.patch))

    def __str__(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

    def to_tuple(self) -> Tuple[int, int, int]:
        return (self.major, self.minor, self.patch)

class Range:
    def __init__(self, spec: str):
        self._spec = spec.strip()
        self._constraints = self._parse_spec(spec)

    def _parse_spec(self, spec: str) -> list[Tuple[str, Version]]:
        if not spec:
            raise ValueError("Empty range specification.")

        constraints = []
        parts = spec.split(',')

        for part in parts:
            part = part.strip()
            if not part:
                # Empty constraint like in ">=1.0.0,"
                raise ValueError("Empty constraint segment in range specification.")

            # Handle operators and versions
            if part.startswith('=='):
                op = '=='
                version_str = part[2:].strip()
            elif part.startswith('!='):
                op = '!='
                version_str = part[2:].strip()
            elif part.startswith('>='):
                op = '>='
                version_str = part[2:].strip()
            elif part.startswith('<='):
                op = '<='
                version_str = part[2:].strip()
            elif part.startswith('>'):
                op = '>'
                version_str = part[1:].strip()
            elif part.startswith('<'):
                op = '<'
                version_str = part[1:].strip()
            elif part.startswith('^'):
                op = '^'
                version_str = part[1:].strip()
            elif part.startswith('~'):
                op = '~'
                version_str = part[1:].strip()
            else:
                # Must be '*' or an exact version string
                op = '=='
                version_str = part

            if version_str == '*':
                # Wildcard '*' is treated specially later, but for parsing consistency, 
                # we'll handle it as a special constraint if encountered here, 
                # though the prompt implies '*' is a standalone constraint.
                if op == '==':
                    constraints.append(('*', None)) # Placeholder for '*'
                else:
                    raise ValueError(f"Operator {op} cannot be combined with '*' in range specification.")
            else:
                try:
                    version = Version(version_str)
                except ValueError as e:
                    raise ValueError(f"Bad version '{version_str}' in constraint '{part}': {e}")

                if op == '*':
                    # Should not happen based on prompt, but handle defensively
                    constraints.append(('*', None))
                elif op == '^':
                    constraints.append(self._parse_caret(version))
                elif op == '~':
                    constraints.append(self._parse_tilde(version))
                else:
                    constraints.append((op, version))

        return constraints

    def _parse_caret(self, v: Version) -> Tuple[str, Version]:
        # ^1.2.3 is >=1.2.3, <2.0.0 (unless major is 0)
        if v.major > 0:
            # Bump major: >=V, <(V+1).0.0
            next_major_v = Version(f"{v.major + 1}.0.0")
            return ('>=', v), (self._op_less, next_major_v)
        else:
            # Semver 2.0.0: ^0.2.3 is >=0.2.3, <0.3.0
            # ^0.0.3 is >=0.0.3, <0.0.4
            if v.minor > 0:
                # Bump minor: >=V, <V.(M+1).0
                next_minor_v = Version(f"{v.major}.{v.minor + 1}.0")
                return ('>=', v), (self._op_less, next_minor_v)
            else:
                # Bump patch: >=V, <V.V.(P+1)
                next_patch_v = Version(f"{v.major}.{v.minor}.{v.patch + 1}")
                return ('>=', v), (self._op_less, next_patch_v)

    def _parse_tilde(self, v: Version) -> Tuple[str, Version]:
        # ~1.2.3 is >=1.2.3, <1.3.0
        if v.patch > 0:
            # Bump patch: >=V, <V.M.(P+1)
            next_patch_v = Version(f"{v.major}.{v.minor}.{v.patch + 1}")
            return ('>=', v), (self._op_less, next_patch_v)
        else:
            # Bump minor: >=V, <V.(M+1).0
            next_minor_v = Version(f"{v.major}.{v.minor + 1}.0")
            return ('>=', v), (self._op_less, next_minor_v)


    def contains(self, v: Version) -> bool:
        # Convert internal list structure to a sequence of checks for easier iteration

        # Special handling for combined constraints from ^/~
        final_checks = []
        for item in self._constraints:
            if isinstance(item, tuple) and len(item) == 2 and isinstance(item[0], str) and (item[0] == '>=' or item[0] == '<='):
                # This is a combined constraint from ^ or ~
                (op1, v1), (op2, v2) = item

                # Check V1: >= V1
                if self._check_single(v, op1, v1):
                    # Check V2: < V2
                    if self._check_single(v, op2, v2):
                        final_checks.append(True)
                    else:
                        return False # Fails the second check
                else:
                    return False # Fails the first check
            elif isinstance(item, tuple) and len(item) == 2:
                # Standard constraint (op, Version) or ('*', None)
                op, version = item
                if op == '*':
                    return True # '*' always matches
                if version is None: # Should be covered by '*' check, but safety
                    return True 
                if self._check_single(v, op, version):
                    final_checks.append(True)
                else:
                    return False
            elif isinstance(item, tuple) and len(item) == 1 and item[0] == '*':
                return True # Should be handled above, safety net

        # If we reached here without returning False, all constraints passed (or were '*').
        return True

    def _check_single(self, v: Version, op: str, target: Version) -> bool:
        # Helper to check if version v satisfies constraint (op, target)
        if op == '==': return v == target
        if op == '!=': return v != target
        if op == '>=': return v >= target
        if op == '<=': return v <= target
        if op == '>': return v > target
        if op == '<': return v < target
        # Note: '^' and '~' are handled in contains() due to complexity
        raise NotImplementedError(f"Unknown operator {op} in internal check.")


    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

    def __str__(self) -> str:
        # Reconstruct the spec string without internal complexity
        parts = []
        for item in self._constraints:
            if isinstance(item, tuple) and len(item) == 2 and isinstance(item[0], str) and (item[0] == '>=' or item[0] == '<='):
                # Reconstruct ^/~ as they are compound, but we approximate the display
                (op1, v1), (op2, v2) = item
                parts.append(f"{op1}{v1} {op2}{v2}")
            elif isinstance(item, tuple) and len(item) == 2:
                op, version = item
                if op == '*':
                    parts.append('*')
                else:
                    parts.append(f"{op}{version}")

        # Simplified reconstruction for display, matching the requirement
        # This is extremely difficult to do perfectly without storing the original spec.
        # We rely on the structure derived from parsing.

        # A simpler, though less robust, reconstruction:
        original_spec = " ".join([str(c[1]) if isinstance(c[1], Version) else c[0] for c in self._constraints if not (isinstance(c, tuple) and len(c) == 2 and isinstance(c[0], str) and (c[0] == '>=' or c[0] == '<='))])

        # Due to the complexity of reverse engineering the original string from compound constraints,
