# resolve/index.py
from typing import Dict, List, Optional, TYPE_CHECKING
from .versions import Version, Range

if TYPE_CHECKING:
    from .versions import Version, Range

class PackageIndex:
    def __init__(self):
        # {name: {version_str: {'requires': {dep_name: Range, ...}, 'version': Version}}}
        self._releases: Dict[str, Dict[str, dict]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        if name in self._releases and version_str in self._releases[name]:
            raise ValueError(f"Release {name}@{version_str} already exists.")

        try:
            v = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Invalid version string '{version_str}' for {name}: {e}")

        requires_parsed: Dict[str, Range] = {}
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    requires_parsed[dep_name] = Range(spec_str)
                except ValueError as e:
                    raise ValueError(f"Invalid requirement '{spec_str}' for {name}@{version_str}: {e}")

        if name not in self._releases:
            self._releases[name] = {}

        self._releases[name][version_str] = {
            'requires': requires_parsed,
            'version': v
        }

    def versions(self, name: str) -> List[Version]:
        if name not in self._releases:
            return []

        version_objects = [
            self._releases[name][v_str]['version'] 
            for v_str in self._releases[name]
        ]

        # Return newest first (descending order)
        return sorted(version_objects, reverse=True)

    def requirements(self, name: str, version: Version) -> Optional[Dict[str, Range]]:
        if name not in self._releases:
            return None

        version_str = str(version)
        if version_str not in self._releases[name]:
            return None

        return self._releases[name][version_str]['requires']

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict]]):
        index = cls()
        for name, versions_data in data.items():
            for version_str, requirements_data in versions_data.items():
                # In the input dict, requirements_data['dep_name'] should be the spec string
                requires = {}
                for dep, spec in requirements_data.items():
                    requires[dep] = spec

                index.add(name, version_str, requires=requires)
        return index

