from typing import Dict, List, Optional, Tuple, Union
from .versions import Version, Range
from .index import PackageIndex

class ResolutionError(Exception):
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(self.explanation)

    def __str__(self) -> str:
        return self.explanation

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:
    """
    Resolves dependencies using backtracking search.
    """

    # Initial setup
    initial_order = sorted(requirements.keys())

    # State:
    # - order: List of package names to process in sequence (mutable during DFS)
    # - selected: Dict {name: Version} (the final result, built in selection order)
    # - requirements_map: Initial root requirements

    def dfs(order: List[str], selected: Dict[str, Version]) -> Optional[Dict[str, Version]]:
        if not order:
            # Success: All required packages processed
            return selected

        package_name = order[0]
        remaining_order = order[1:]

        # 1. Collect all constraints for package_name

        # Constraints: List of (Requirer, Range)
        constraints: List[Tuple[str, Range]] = []

        # Root requirement constraint
        if package_name in requirements:
            try:
                root_range = Range(requirements[package_name])
                constraints.append(('<root>', root_range))
            except ValueError:
                # This should have been caught by the caller validating requirements upfront, 
                # but we handle it here for safety if we were to modify the entry point.
                pass 

        # Constraints from already selected packages
        for req_name, req_version in selected.items():
            if req_name in index._releases and req_version in index._releases[req_name]:
                # Check if req_name depends on package_name
                req_deps = index.requirements(req_name, req_version)
                if req_deps and package_name in req_deps:
                    dep_range = req_deps[package_name]
                    requirer_id = f"{req_name} {req_version}"
                    constraints.append((requirer_id, dep_range))

        # 2. Determine candidates (Versions, newest first)
        candidates = index.versions(package_name)

        # 3. Iterate through candidates and try to resolve recursively
        for candidate_v in candidates:

            is_acceptable = True
            reasons_for_exclusion = []

            # Check Constraint 1: Does candidate satisfy all constraints?
            for requirer, constraint_range in constraints:
                if not constraint_range.contains(candidate_v):
                    is_acceptable = False
                    reasons_for_exclusion.append(f"{requirer} requires {package_name} {constraint_range}")
                    break

            if not is_acceptable:
                # This version is excluded by a constraint
                continue # Try next candidate

            # Check Constraint 2: Does candidate conflict with already selected dependencies?
            conflicting_dep = None

            # Check dependencies of candidate_v against already selected packages
            candidate_deps = index.requirements(package_name, candidate_v)

            if candidate_deps:
                # Check dependencies in alphabetical order of dependency names
                for dep_name in sorted(candidate_deps.keys()):
                    dep_range = candidate_deps[dep_name]

                    if dep_name in selected:
                        selected_v = selected[dep_name]
                        if not dep_range.contains(selected_v):
                            is_acceptable = False
                            conflicting_dep = dep_name
                            break

            if not is_acceptable:
                # This version conflicts with a selected dependency
                reasons_for_exclusion.append(f"{package_name} {candidate_v} requires {conflicting_dep} {candidate_deps[conflicting_dep]}")
                continue # Try next candidate


            # If acceptable, proceed with DFS

            # Prepare next state
            new_selected = selected.copy()
            new_selected[package_name] = candidate_v

            # Identify new packages to add to the order queue
            new_deps_to_add = []
            candidate_deps = index.requirements(package_name, candidate_v)
            if candidate_deps:
                for dep_name in candidate_deps.keys():
                    if dep_name not in selected and dep_name not in order:
                        new_deps_to_add.append(dep_name)

            # Sort new dependencies alphabetically and append to order
            new_deps_to_add.sort()
            next_order = order + new_deps_to_add

            # Recurse
            result = dfs(next_order, new_selected)

            if result is not None:
                return result # Success found down this path

        # 4. Failure: No candidate worked for this package

        # Construct error explanation
        explanation_lines = [f"cannot resolve {package_name}"]

        # Add constraints that were applied (regardless of whether they caused exclusion)
        for requirer, constraint_range in constraints:
             explanation_lines.append(f"  {requirer} requires {package_name} {constraint_range}")

        if not candidates:
            explanation_lines.append(f"  no versions of {package_name} are known")
        else:
            # List excluded versions
            for candidate_v in candidates:
                is_excluded_by_constraint = any(
                    not constraint_range.contains(candidate_v) 
                    for _, constraint_range in constraints
                )

                if is_excluded_by_constraint:
                    # Excluded by a constraint
                    explanation_lines.append(f"  {package_name} {candidate_v} is excluded by the constraints")
                else:
                    # Must be excluded by a dependency conflict
                    candidate_deps = index.requirements(package_name, candidate_v)
                    conflicting_dep = None
                    for dep_name in sorted(candidate_deps.keys()):
                        dep_range = candidate_deps[dep_name]
                        if dep_name in selected:
                            selected_v = selected[dep_name]
                            if not dep_range.contains(selected_v):
                                conflicting_dep = dep_name
                                break

                    if conflicting_dep:
                        explanation_lines.append(f"  {package_name} {candidate_v} requires {conflicting_dep} {candidate_deps[conflicting_dep]}, but {conflicting_dep} {selected[conflicting_dep]} is selected")
                    # If not excluded by constraints and no dependency conflict, something is fundamentally wrong
                    # or it should have been successful, but we rely on the failure path above.

        return None

