        raise ParseError("Say something.")

    first_word = words[0]

    # Remove articles after the first word
    remaining_words = []
    skip_articles = False
    for i, word in enumerate(words):
        if i == 0:
            remaining_words.append(word)
        else:
            if skip_articles:
                remaining_words.append(word)
            elif word in ('the', 'a', 'an'):
                skip_articles = True
            else:
                remaining_words.append(word)

    # Rebuild the arguments string, excluding the first word if it was an article replacement
    if remaining_words:
        # Check if the first word was an article used as verb (like 'a' or 'an' if the input was 'a north')
        # The logic needs to simplify this: the verb is the first word, args are the rest *after* article removal.

        # A simpler approach adhering strictly to the rules:
        parts = line.split()
        verb = parts[0]

        # Filter out articles after the first word
        args_list = []
        skip = False
        for i, word in enumerate(parts):
            if i == 0:
                continue
            if skip and word in ('the', 'a', 'an'):
                # Keep skipping
                continue
            if word in ('the', 'a', 'an'):
                skip = True
            else:
                args_list.append(word)

        arg_str = " ".join(args_list)
    else:
        arg_str = None

    # --- Command Mapping ---

    if first_word in ('north', 'south', 'east', 'west', 'up', 'down', 'n', 's', 'e', 'w', 'u', 'd'):
        full_direction = first_word
        if first_word in ('n', 's', 'e', 'w', 'u', 'd'):
            # Map single letter shorthand to full direction name
            mapping = {'n': 'north', 's': 'south', 'e': 'east', 'w': 'west', 'u': 'up', 'd': 'down'}
            full_direction = mapping[first_word]

        if arg_str:
            # Anything after a direction word -> I don't understand that.
            raise ParseError("I don't understand that.")

        return Command('go', full_direction)

    if first_word in ('go', 'move'):
        if not arg_str:
            raise ParseError("Go where?")

        # Check if argument is a valid direction
        is_direction = False
        for d in ('north', 'south', 'east', 'west', 'up', 'down'):
            if arg_str == d:
                is_direction = True
                break

        if not is_direction:
            raise ParseError(f'"{arg_str}" is not a direction.')
        return Command('go', arg_str)

    if first_word in ('take', 'get'):
        if not arg_str:
            raise ParseError("Take what?")
        return Command('take', arg_str)

    if first_word in ('drop'):
        if not arg_str:
            raise ParseError("Drop what?")
        return Command('drop', arg_str)

    if first_word in ('look', 'l', 'examine', 'x'):
        if not arg_str:
            return Command('look', None)
        # Handle "look at X" -> X
        if first_word == 'look' and len(words) > 2 and words[1] == 'at':
            arg_str = " ".join(words[2:])
        return Command('look', arg_str)

    if first_word in ('inventory', 'inv', 'i'):
        return Command('inventory', None)

    # Unknown word
    raise ParseError(f'I don\'t know the word "{first_word}".')
