# adventure/game.py
import json
from typing import List, Dict, Any, Tuple
from .world import World, Room, Item
from .parser import Command, ParseError

class SaveError(ValueError):
    pass

class Game:
    def __init__(self, world: World):
        self.world = world
        self.room: str = world.start
        self.inventory: List[str] = []  # List of item IDs
        self.moves: int = 0
        self._initialize_items()

    def _initialize_items(self):
        """Sets up the initial state by moving items listed in rooms into the game state."""
        # We must clone the room items into a mutable structure for tracking

        # Map Room ID -> List of Item IDs currently in that room (mutable copy of initial state)
        self._current_room_items: Dict[str, List[str]] = {}

        for room_id, room in self.world.rooms.items():
            # Items are initially present if listed in the room definition
            self._current_room_items[room_id] = list(room.items)


    def items_in(self, room_id: str) -> List[str]:
        """Returns a new list of item ids currently in that room, in order."""
        return self._current_room_items.get(room_id, [])[:]

    def _find_matching_item(self, search_term: str) -> Tuple[Item | None, str | None, bool]:
        """
        Searches for an item matching search_term.
        Returns (Item object, item_id, is_in_inventory)
        Returns (None, None, False) if not found.
        """
        search_term_lower = search_term.lower()

        # 1. Check Room
        room_items_ids = self.items_in(self.room)
        for item_id in room_items_ids:
            item = self.world.items.get(item_id)
            if item and (item.id.lower() == search_term_lower or item.name.lower() == search_term_lower):
                return item, item.id, False

        # 2. Check Inventory
        for inv_item_id in self.inventory:
            item = self.world.items.get(inv_item_id)
            if item and (item.id.lower() == search_term_lower or item.name.lower() == search_term_lower):
                return item, inv_item_id, True

        return None, None, False

    def do(self, line: str) -> str:
        try:
            command: Command = self.world.parser.parse(line)
        except ParseError as e:
            # Return the specific error message from the parser
            return str(e)

        verb = command.verb
        arg = command.arg

        if verb == 'look':
            return self._handle_look(arg)
        elif verb == 'go':
            return self._handle_go(arg)
        elif verb == 'take':
            return self._handle_take(arg)
        elif verb == 'drop':
            return self._handle_drop(arg)
        elif verb == 'inventory':
            return self._handle_inventory()

        # Should not happen if parser is correct, but for safety:
        return "I don't understand that."

    # --- Command Handlers ---

    def _handle_look(self, arg: Optional[str]) -> str:
        if arg is None:
            # Look (Room description)
            room = self.world.rooms[self.room]

            name_line = room.name
            desc_line = room.description

            # Exits
            exit_parts = []
            for direction in self.world.DIRECTIONS:
                if direction in room.exits:
                    exit_parts.append(direction)

            if exit_parts:
                exits_line = f"Exits: {', '.join(exit_parts)}."
            else:
                exits_line = "Exits: none."

            # Items
            items_in_room = self.items_in(self.room)
            if items_in_room:
                item_names = [self.world.items[i_id].name for i_id in items_in_room]
                items_line = f"You see: {', '.join(item_names)}."
            else:
                items_line = ""

            return "\n".join([name_line, desc_line, exits_line, items_line]).strip()
        else:
            # Look X (Item description)
            item, item_id, in_inventory = self._find_matching_item(arg)

            if item:
                # Room is searched first, so if found, it's in the room
                if not in_inventory:
                    # Found in room, return description
                    return f"It is a {item.name}. {item.description}"
                else:
                    # Found in inventory, return description
                    return f"You look at the {item.name}. {item.description}"
            else:
                return f"You see no {arg} here."


    def _handle_go(self, direction: str) -> str:
        current_room = self.world.rooms[self.room]
        if direction in current_room.exits:
            new_room_id = current_room.exits[direction]
            self.room = new_room_id
            self.moves += 1
            # Return the look text of the new room
            return self._handle_look(None)
        else:
            return "You can't go that way."

    def _handle_take(self, arg: str) -> str:
        item, item_id, in_inventory = self._find_matching_item(arg)

        if not item:
            return f"You see no {arg} here."

        if in_inventory:
            return f"You already have the {item.name}."

        # Item is in the room
        room_items = self.items_in(self.room)
        if item_id not in room_items:
             # This case should ideally not happen if _find_matching_item is correct, 
             # but it means the item was already taken or removed by another mechanic.
            return f"You see no {arg} here."

        if not item.portable:
            return f"You can't take the {item.name}."

        # Take it
        room_items_list = self._current_room_items[self.room]
        try:
            # Remove from room list
            room_items_list.remove(item_id)

            # Add to inventory
            self.inventory.append(item_id)
            return f"Taken: {item.name}."
        except ValueError:
            # Should not happen if room_items_list matched item_id
            return "Error processing take action."


    def _handle_drop(self, arg: str) -> str:
        item, item_id, in_inventory = self._find_matching_item(arg)

        if not item:
            return f"You aren't carrying that."

        if not in_inventory:
            # Item was found, but not in inventory (must be in room)
            return "You aren't carrying that."

        # Drop it
        try:
            self.inventory.remove(item_id)

            # Add to current room's item list (at the end)
            room_items_list = self._current_room_items[self.room]
            room_items_list.append(item_id)

            return f"Dropped: {item.name}."
        except ValueError:
            # Item ID was in inventory list but failed removal (internal inconsistency)
            return "Error processing drop action."

    def _handle_inventory(self) -> str:
        if not self.inventory:
            return "You are carrying nothing."

        item_names = [self.world.items[i_id].name for i_id in self.inventory]
        return f"You are carrying: {', '.join(item_names)}."

    # --- Serialization ---

    def save(self) -> str:
        """Returns a JSON string of the current game state."""

        # 1. Inventory (list of item IDs)
        inventory_state = self.inventory

        # 2. Items in rooms (dict: room_id -> list of item IDs)
        items_state: Dict[str, List[str]] = {}
        for room_id, item_list in self._current_room_items.items():
            items_state[room_id] = item_list[:]

        state = {
            "version": 1,
            "room": self.room,
            "inventory": inventory_state,
            "items": items_state,
            "moves": self.moves
        }
        return json.dumps(state)

    @classmethod
    def load(cls, world: World, text: str) -> 'Game':
        """Loads a game state from a JSON string."""
        try:
            data: Dict[str, Any] = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON format.")

        if not isinstance(data, dict):
            raise SaveError("Save data must be a JSON object.")

        required_keys = ["version", "room", "inventory", "items", "moves"]
        for key in required_keys:
            if key not in data:
                raise SaveError(f"Missing required key in save data: '{key}'.")

        if data["version"] != 1:
            raise SaveError(f"Unsupported save file version: {data['version']}. Expected 1.")

        room_id = data["room"]
        inventory_ids = data["inventory"]
        items_state = data["items"]
        moves = data["moves"]

        if room_id not in world.rooms:
            raise SaveError(f"Saved room '{room_id}' not found in the world.")

        if not isinstance(moves, int) or moves < 0:
            raise SaveError("Moves count must be a non-negative integer.")

        # Validation: Check if all item IDs are valid
        all_item_ids_in_save = set(inventory_ids)
        for item_list in items_state.values():
            for item_id in item_list:
                all_item_ids_in_save.add(item_id)

        for item_id in all_item_ids_in_save:
            if item_id not in world.items:
                raise SaveError(f"Saved item ID '{item_id}' does not exist in the world.")

        # Validation: Check for duplicates (inventory + all rooms)
        seen_ids = set()
        for item_id in inventory_ids:
            if item_id in seen_ids:
                raise SaveError(f"Item ID '{item_id}' appears multiple times in inventory.")
            seen_ids.add(item_id)

        for room_id, item_list in items_state.items():
            for item_id in item_list:
                if item_id in seen_ids:
                    raise SaveError(f"Item ID '{item_id}' appears in inventory and a room.")
                if item_id in seen_ids: # Should be caught above, but safety check
                    raise SaveError(f"Item ID '{item_id}' appears multiple times in the same room/state.")
                seen_ids.add(item_id)


        # Create the game instance
        game = cls(world)
        game.room = room_id
        game.inventory = inventory_ids[:]
        game.moves = moves

        # Re-initialize the internal room item tracking based on the loaded state
        game._current_room_items = {}
        for room_id, item_list in items_state.items():
             game._current_room_items[room_id] = item_list[:]

        return game
