class Room:
    id: str
    name: str
    description: str
    # Exits now maps direction to target: Room ID (str) or Lock Dict
    exits: Dict[str, ExitTarget] 
    # Locks: Direction -> Item ID required to unlock this specific exit
    locks: Dict[str, str] 
    items: Tuple[str, ...]  # Tuple of Item IDs currently in the room

class WorldError(ValueError):
    pass

class World:
    def __init__(self, start: str, rooms: Dict[str, Room], items: Dict[str, Item]):
        self.start = start
        self.rooms = rooms
        self.items = items

    @classmethod
    def from_dict(cls, data: Dict[str, Any]):
        start_id = data.get("start")
        rooms_data = data.get("rooms", {})
        items_data = data.get("items", {})

        if not start_id:
            raise WorldError("World dictionary missing 'start' key.")
        if start_id not in rooms_data:
            raise WorldError(f"Start room '{start_id}' not found in rooms.")

        rooms: Dict[str, Room] = {}
        processed_items: Dict[str, Item] = {}
        all_item_ids_in_world = set()

        # 1. Process Items
        for item_id, item_props in items_data.items():
            name = item_props.get("name")
            description = item_props.get("description")
            portable = item_props.get("portable", True)
            treasure = item_props.get("treasure", 0)

            if name is None or description is None:
                raise WorldError(f"Item '{item_id}' is missing 'name' or 'description'.")
            if not isinstance(treasure, int) or treasure < 0:
                raise WorldError(f"Item '{item_id}' treasure must be a non-negative integer.")

            item = Item(id=item_id, name=name, description=description, portable=portable, treasure=treasure)
            processed_items[item_id] = item
            all_item_ids_in_world.add(item_id)


        # 2. Process Rooms
        for room_id, r_data in rooms_data.items():
            name = r_data.get("name")
            description = r_data.get("description")
            exits_raw = r_data.get("exits", {})
            items_data_list = r_data.get("items", [])
            locks_raw = r_data.get("locks", {})

            if name is None or description is None:
                raise WorldError(f"Room '{room_id}' is missing 'name' or 'description'.")

            exits: Dict[str, ExitTarget] = {}
            locks: Dict[str, str] = {}

            # Process Exits and Locks
            for direction, target in exits_raw.items():
                if direction not in DIRECTIONS:
                    raise WorldError(f"Room '{room_id}' has invalid direction '{direction}' in exits.")

                if isinstance(target, str):
                    # Unlocked exit (points to Room ID)
                    target_id = target
                    exits[direction] = target_id
                    # No lock entry needed
                elif isinstance(target, dict):
                    # Locked exit (dict structure)
                    to_room = target.get("to")
                    required_key = target.get("key")

                    if to_room is None or required_key is None:
                        raise WorldError(f"Locked exit in room '{room_id}' missing 'to' or 'key'.")

                    if to_room not in rooms_data:
                        raise WorldError(f"Locked exit in room '{room_id}' points to unknown room '{to_room}'.")

                    if required_key not in processed_items:
                        raise WorldError(f"Locked exit in room '{room_id}' requires unknown item '{required_key}'.")

                    exits[direction] = target # Keep dict structure for reference
                    locks[direction] = required_key

            # Validate Room Items
            room_item_id_set = set()
            for item_id in items_data_list:
                if item_id not in processed_items:
                    raise WorldError(f"Room '{room_id}' lists unknown item '{item_id}'.")
                if item_id in room_item_id_set:
                    raise WorldError(f"Item '{item_id}' listed more than once in room '{room_id}'.")
                room_item_id_set.add(item_id)

                # Global uniqueness check
                if item_id in all_item_ids_in_world and item_id not in room_item_id_set:
                     # Check if this item is already assigned to another room's initial listing
                     # This requires a slightly more complex check, but for simplicity matching the spirit:
                     pass # We rely on the final check below for global duplication if item is listed twice across rooms

            rooms[room_id] = Room(
                id=room_id,
                name=name,
                description=description,
                exits=exits,
                locks=locks,
                items=tuple(items_data_list)
            )

        # Final check for global item duplication across all initial room listings
        listed_items = set()
        for room in rooms.values():
            for item_id in room.items:
                if item_id in listed_items:
                    raise WorldError(f"Item '{item_id}' listed more than once across different rooms.")
                listed_items.add(item_id)


        return cls(start=start_id, rooms=rooms, items=processed_items)
