            name_line = room.name
            desc_line = room.description

            # Exits
            exit_parts = []
            for direction in DIRECTIONS:
                if direction in room.exits:
                    target = room.exits[direction]
                    if isinstance(target, str):
                        # Unlocked exit
                        exit_parts.append(f"{direction}.")
                    elif isinstance(target, dict):
                        # Locked exit
                        is_locked = (self.room, direction) not in self._unlocked_exits
                        status = "(locked)" if is_locked else "."
                        exit_parts.append(f"{direction} {status}")

            exits_line = f"Exits: {', '.join(exit_parts)}"

            # Items
            items_in_room = self.items_in(self.room)
            if items_in_room:
                item_names = [self.world.items[i_id].name for i_id in items_in_room]
                items_line = f"You see: {', '.join(item_names)}."
            else:
                items_line = ""

            return "\n".join([name_line, desc_line, exits_line, items_line]).strip()
        else:
            # Look X (Item description)
            item, item_id, in_inventory = self._find_matching_item(arg)

            if item:
                if not in_inventory:
                    # Found in room
                    return f"It is a {item.name}. {item.description}"
                else:
                    # Found in inventory
                    return f"You look at the {item.name}. {item.description}"
            else:
                return f"You see no {arg} here."


    def _handle_go(self, direction: str) -> str:
        current_room = self.world.rooms[self.room]
        if direction not in current_room.exits:
            return "You can't go that way."

        target = current_room.exits[direction]

        if isinstance(target, str):
            # Always unlocked exit
            new_room_id = target
        elif isinstance(target, dict):
            # Locked exit structure
            is_locked = (self.room, direction) not in self._unlocked_exits
            if is_locked:
                return f"The way {direction} is locked."
            else:
                # Unlocked locked exit
                new_room_id = target["to"]
        else:
            # Should not happen
            return "An internal error occurred trying to move."


        # Successful move logic
        self.room = new_room_id
        self.moves += 1
        self._mark_visited(self.room)

        # Check for treasure collection upon entering room
        for item_id in self.items_in(self.room):
            item = self.world.items[item_id]
            if item.treasure > 0 and item_id not in self._scored_items:
                self.score += item.treasure
                self._scored_items.add(item_id)
                # Note: Treasure is awarded upon first entry, not when picked up.

        return self._handle_look(None)

    def _handle_take(self, arg: str) -> str:
        item, item_id, in_inventory = self._find_matching_item(arg)

        if not item:
            return f"You see no {arg} here."

        if in_inventory:
            return f"You already have the {item.name}."

        # Item is in the room
        room_items = self.items_in(self.room)
        if item_id not in room_items:
            return f"You see no {arg} here."

        if not item.portable:
            return f"You can't take the {item.name}."

        # Take it
        room_items_list = self._current_room_items[self.room]
        try:
            # Remove from room list
            room_items_list.remove(item_id)

            # Add to inventory
            self.inventory.append(item_id)
            return f"Taken: {item.name}."
        except ValueError:
            return "Error processing take action."


    def _handle_drop(self, arg: str) -> str:
        item, item_id, in_inventory = self._find_matching_item(arg)

        if not item:
            return "You aren't carrying that."

        if not in_inventory:
            return "You aren't carrying that."

        # Drop it
        try:
            self.inventory.remove(item_id)

            # Add to current room's item list (at the end)
            room_items_list = self._current_room_items[self.room]
            room_items_list.append(item_id)

            return f"Dropped: {item.name}."
        except ValueError:
            return "Error processing drop action."

    def _handle_use(self, arg: str) -> str:
        item, item_id, in_inventory = self._find_matching_item(arg)

        if not item or not in_inventory:
            return "You aren't carrying that."

        # Check if this key unlocks anything
        unlocked_directions = []
        room = self.world.rooms[self.room]

        for direction, target in room.exits.items():
            if isinstance(target, dict) and target["key"] == item_id:
                # This is a relevant locked exit
                if (self.room, direction) not in self._unlocked_exits:
                    unlocked_directions.append(direction)

        if unlocked_directions:
            # Unlock all relevant exits
            for direction in unlocked_directions:
                self._unlocked_exits.add((self.room, direction))

            return f"Unlocked: {', '.join(unlocked_directions)}."
        else:
            return f"Nothing here to use the {item.name} on."

    def _handle_inventory(self) -> str:
        if not self.inventory:
            return "You are carrying nothing."

        item_names = [self.world.items[i_id].name for i_id in self.inventory]
        return f"You are carrying: {', '.join(item_names)}."

    def _handle_score(self) -> str:
        return f"Your score is {self.score}."

    # --- Serialization ---

    def save(self) -> str:
        """Returns a JSON string of the current game state (Version 2)."""

        # 1. Inventory (list of item IDs)
        inventory_state = self.inventory

        # 2. Items in rooms (dict: room_id -> list of item IDs)
        items_state: Dict[str, List[str]] = {}
        for room_id, item_list in self._current_room_items.items():
            items_state[room_id] = item_list[:]

        # 3. Unlocked Exits (list of [room_id, direction])
        unlocked_state = sorted([list(pair) for pair in self._unlocked_exits])

        # 4. Visited Rooms (sorted list of room IDs)
        visited_state = sorted(list(self._is_visited))

        # 5. Scored Items (sorted list of item IDs)
        scored_state = sorted(list(self._scored_items))

        state = {
            "version": 2,
            "room": self.room,
            "inventory": inventory_state,
            "items": items_state,
            "moves": self.moves,
            "unlocked": unlocked_state,
            "visited": visited_state,
            "scored": scored_state,
            "score": self.score
        }
        return json.dumps(state)

    @classmethod
    def load(cls, world: World, text: str) -> 'Game':
        """Loads a game state from a JSON string, handling V1 and V2."""
        try:
            data: Dict[str, Any] = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON format.")

        if not isinstance(data, dict):
            raise SaveError("Save data must be a JSON object.")

        version = data.get("version")

        if version is None:
            raise SaveError("Save data is missing 'version'.")

        if version == 2:
            required_keys = ["version", "room", "inventory", "items", "moves", "unlocked", "visited", "scored", "score"]
            for key in required_keys:
                if key not in data:
                    raise SaveError(f"Missing required key in version 2 save data: '{key}'.")

            room_id = data["room"]
            inventory_ids = data["inventory"]
            items_state = data["items"]
            moves = data["moves"]
            unlocked_list = data["unlocked"]
            visited_list = data["visited"]
            scored_list = data["scored"]
            score = data["score"]

            # V2 Validation
            if room_id not in world.rooms:
                raise SaveError(f"Saved room '{room_id}' not found in the world.")
            if not isinstance(moves, int) or moves < 0:
                raise SaveError("Moves count must be a non-negative integer.")
            if not isinstance(score, int) or score < 0:
                raise SaveError("Score must be a non-negative integer.")

            # Check item existence
            all_item_ids_in_save = set(inventory_ids)
            for item_list in items_state.values():
                for item_id in item_list:
                    all_item_ids_in_save.add(item_id)

            for item_id in all_item_ids_in_save:
                if item_id not in world.items:
                    raise SaveError(f"Saved item ID '{item_id}' does not exist in the world.")

            # Check uniqueness
            seen_ids = set()
            for item_id in inventory_ids:
                if item_id in seen_ids: raise SaveError(f"Item ID '{item_id}' duplicates in inventory.")
                seen_ids.add(item_id)
            for item_list in items_state.values():
                for item_id in item_list:
                    if item_id in seen_ids: raise SaveError(f"Item ID '{item_id}' duplicates across inventory/rooms.")
                    seen_ids.add(item_id)

            # Validate Unlocked Exits
            for room_id_u, direction_u in unlocked_list:
                if room_id_u not in world.rooms:
                    raise SaveError(f"Unlocked exit references unknown room '{room_id_u}'.")
                room_u = world.rooms[room_id_u]
                if direction_u not in room_u.exits:
                    raise SaveError(f"Unlocked direction '{direction_u}' does not exist in room '{room_id_u}'.")

                target = room_u.exits[direction_u]
                if isinstance(target, str):
                    raise SaveError(f"Attempted to unlock an already open exit in room '{room_id_u}'.")

                # Check if the lock key exists
                if direction_u not in room_u.locks:
                    raise SaveError(f"Exit '{direction_u}' in room '{room_id_u}' is not registered as locked.")

            # Validate Visited Rooms
            for room_id_v in visited_list:
                if room_id_v not in world.rooms:
                    raise SaveError(f"Visited room '{room_id_v}' not found in the world.")

            # Validate Scored Items
            for item_id_s in scored_list:
                if item_id_s not in world.items:
                    raise SaveError(f"Scored item ID '{item_id_s}' not found in the world.")


            game = cls(world)
            game.room = room_id
            game.inventory = inventory_ids[:]
            game.moves = moves
            game.score = score

            game._current_room_items = {rid: item_list[:] for rid, item_list in items_state.items()}
            game._is_visited = set(visited_list)
            game._scored_items = set(scored_list)
            game._unlocked_exits = set(tuple(pair) for pair in unlocked_list)

            return game

        elif version == 1:
            # V1 Load (Backward Compatibility)
            required_keys = ["version", "room", "inventory", "items", "moves"]
            for key in required_keys:
                if key not in data:
                    raise SaveError(f"Missing required key in version 1 save data: '{key}'.")

            room_id = data["room"]
            inventory_ids = data["inventory"]
            items_state = data["items"]
            moves = data["moves"]

            # V1 Validation (simplified)
            if room_id not in world.rooms:
                raise SaveError(f"Saved room '{room_id}' not found in the world.")
            if not isinstance(moves, int) or moves < 0:
                raise SaveError("Moves count must be a non-negative integer.")

            # Check item existence and uniqueness (same checks as V2, but without lock/score validation)
            seen_ids = set()
            for item_id in inventory_ids:
                if item_id not in world.items: raise SaveError(f"Saved item ID '{item_id}' not found in the world.")
                if item_id in seen_ids: raise SaveError(f"Item ID '{item_id}' duplicates in inventory.")
                seen_ids.add(item_id)
            for item_list in items_state.values():
                for item_id in item_list:
                    if item_id not in world.items: raise SaveError(f"Saved item ID '{item_id}' not found in the world.")
                    if item_id in seen_ids: raise SaveError(f"Item ID '{item_id}' duplicates across inventory/rooms.")
                    seen_ids.add(item_id)


            game = cls(world)
            game.room = room_id
            game.inventory = inventory_ids[:]
            game.moves = moves
            game.score = 0 # V1 starts with 0 score
            game._is_visited = {room_id} # Only the saved room is marked visited (start room handled by init)
            game._current_room_items = {rid: item_list[:] for rid, item_list in items_state.items()}
            game._unlocked_exits = set() # All locks reset
            game._scored_items = set()
            return game

        else:
            raise SaveError(f"Unsupported save file version: {version}. Must be 1 or 2.")
