from posixpath import join as posix_join, normpath
import os

def normalize(path: str, cwd: str = '/') -> str:
    """
    Returns an absolute path with no . or .. parts, no repeated /, and no trailing / 
    (except the root, /).
    """
    if not path:
        raise ValueError("Path cannot be empty")

    # 1. Resolve relative to CWD first
    if not os.path.isabs(path):
        # Ensure CWD is normalized absolute path
        cwd_normalized = normalize(cwd)
        # Join relative path to normalized CWD
        full_path = posix_join(cwd_normalized, path)
    else:
        full_path = path

    # 2. Use os.path.normpath logic adapted for POSIX style
    # We must handle the specific requirement: "An empty path raises ValueError." (checked above)

    # Clean up path segments: resolve ., .., and multiple slashes
    parts = []
    for part in full_path.split('/'):
        if not part or part == '.':
            continue
        elif part == '..':
            if parts:
                parts.pop()
        else:
            parts.append(part)

    normalized = '/' + '/'.join(parts)

    # Ensure root returns '/'
    if not normalized:
        return '/'

    # Ensure no trailing slash unless it is the root
    if normalized != '/' and normalized.endswith('/'):
        return normalized.rstrip('/')

    return normalized

def join(base: str, *parts) -> str:
    """Joins paths like posixpath.join, where a part starting with / starts over."""
    if not base:
        base = '/'

    # If base is not normalized, normalize it first.
    base = normalize(base)

    result_parts = []
    if base != '/':
        result_parts.extend(base.split('/')[1:]) # Skip leading '/'

    for part in parts:
        if part.startswith('/'):
            # Starts over from root
            result_parts = [part.lstrip('/')]
        else:
            result_parts.append(part)

    # Rebuild the path and normalize
    if not result_parts:
        return '/'

    # The first part might be an absolute path if one of the subsequent parts started with '/'
    if result_parts[0].startswith('/'):
        return normalize(result_parts[0])

    return normalize('/' + '/'.join(result_parts))

def split(path: str) -> tuple[str, str]:
    """Takes an absolute normalised path and returns (parent, name); split('/') is ('/', '')."""
    if path == '/':
        return ('/', '')

    # Ensure path is absolute and normalized before splitting
    path = normalize(path)

    if path == '/':
        return ('/', '')

    parent = path.rsplit('/', 1)[0]
    name = path.rsplit('/', 1)[-1]

    return (parent, name)

def is_within(path: str, ancestor: str) -> bool:
    """Tells whether the normalised path is ancestor itself or lies below it."""
    path = normalize(path)
    ancestor = normalize(ancestor)

    if path == ancestor:
        return True

    # Check if path starts with ancestor followed by a separator
    # E.g., path='/a/b', ancestor='/a'. '/a/b'.startswith('/a/') -> True
    return path.startswith(ancestor + '/')

