# --- Errors ---
class FSError(Exception):
    """Base filesystem error."""
    pass

class NotFound(FSError):
    pass

class AlreadyExists(FSError):
    pass

class NotADirectory(FSError):
    pass

class IsADirectory(FSError):
    pass

class InvalidOperation(FSError):
    pass

# Helper to format errors exactly as required
def _format_error(error_class: type[FSError], path: str) -> str:
    """Formats the error message exactly as required: ErrorClassName: PATH"""
    return f"{error_class.__name__}: {path}"

# --- Core Implementation ---

class FileSystem:
    """In-memory filesystem."""

    def __init__(self):
        # Structure: {'name': 'type', ...}
        # Type: 'dir' or 'file'
        self._structure: Dict[str, str] = {'/': 'dir'}
        # Content: {path: text_content}
        self._contents: Dict[str, str] = {}
        self._cwd: str = '/'

    @property
    def current_dir(self) -> str:
        return self._cwd

    def _resolve_path(self, rel_path: str) -> str:
        """Resolves a relative path against the current working directory and normalizes."""
        if not rel_path:
            return self._cwd

        # Use join to combine CWD and the path, then normalize
        return normalize(join(self._cwd, rel_path))

    def _get_path_components(self, path: str) -> List[str]:
        """Returns the components of a normalized path (e.g., '/a/b' -> ['', 'a', 'b'])."""
        return path.split('/')

    def _get_parent(self, path: str) -> str:
        """Returns the parent directory of a normalized path."""
        parent, _ = split(path)
        return parent

    def _find_entry_type(self, path: str) -> Tuple[str, str, str]:
        """
        Finds the type ('dir'/'file') and the absolute path of the direct parent.
        Returns (type, absolute_path, parent_path)
        """
        if path == '/':
            return 'dir', '/', '/'

        parent_path = self._get_parent(path)

        # Check if parent exists first
        if parent_path not in self._structure:
             # This case should be caught by NotFound in FS methods, 
             # but we handle it defensively here.
             return 'unknown', path, parent_path

        entry_type = self._structure[path]
        return entry_type, path, parent_path

    def pwd(self) -> str:
        return self._cwd

    def cd(self, path: str):
        target_path = self._resolve_path(path)

        if target_path not in self._structure:
            raise NotFound(target_path)

        target_type = self._structure[target_path]

        if target_type == 'file':
            raise NotADirectory(target_path)

        # If it's a directory, update CWD
        self._cwd = target_path

    def mkdir(self, path: str, parents: bool = False):
        path = self._resolve_path(path)

        if path in self._structure:
            if self._structure[path] == 'file':
                raise AlreadyExists(path)
            # If it's already a directory, no error is raised per spec
            return

        if not parents:
            # Check if parent exists
            parent_path = self._get_parent(path)
            if parent_path not in self._structure:
                raise NotFound(parent_path)
        else:
