            current = '/'
            path_components = self._get_path_components(path)[1:] # Skip initial empty string

            for i, component in enumerate(path_components):
                # Build the path up to this component
                temp_path = join(current, component)

                if temp_path in self._structure:
                    # Check if it's a file where we expected a directory
                    if self._structure[temp_path] == 'file':
                        # Only raise if we are creating a directory at this level
                        if i < len(path_components) - 1:
