        if parent_path not in self._structure or self._structure[parent_path] != 'dir':
            raise NotFound(parent_path)

        if target_path in self._structure and self._structure[target_path] == 'dir':
            raise IsADirectory(target_path)

        if target_path not in self._structure:
            # Creating a new file, mark it in structure
            self._structure[target_path] = 'file'
            self._contents[target_path] = ""

        if append:
            self._contents[target_path] += text
        else:
            self._contents[target_path] = text

    def read(self, path: str) -> str:
        target_path = self._resolve_path(path)

        if target_path not in self._structure:
            raise NotFound(target_path)

        if self._structure[target_path] == 'dir':
            raise IsADirectory(target_path)

        return self._contents[target_path]

    def ls(self, path: str = '.'):
