        # If dst exists and is a directory, we append the name
        final_dst = dst_path
        if dst_path in self._structure and self._structure[dst_path] == 'dir':
            name = split(src_path)[1]
            final_dst = join(dst_path, name)

        # Final checks on final_dst
        if final_dst in self._structure:
             raise AlreadyExists(final_dst)

        # Actual relocation
        self._structure[final_dst] = src_type
        self._contents.pop(src_path, None)

        # If it was a directory, we need to remove its entry from the parent structure
        parent_src_path = self._get_parent(src_path)
        if parent_src_path in self._structure:
            # The actual structure entry for the directory is now gone, 
            # but we don't need to clean up the parent directory itself unless it becomes empty.
            pass 

        # If it was a file, content moves
        if src_type == 'file':
            self._contents[final_dst] = self._contents.pop(src_path)

    def _recursive_move(self, src_path, dst_path):
        """Helper for mv, moves contents if src is a directory."""
        src_type = self._structure[src_path]
        if src_type != 'dir':
            return True # File move handled by main mv logic

        # Iterate over all children of src_path
        children_to_move = []
        for path in self._structure:
            if path.startswith(src_path + '/') and path != src_path:
                children_to_move.append(path)

        for child_path in children_to_move:
            child_type = self._structure[child_path]
            child_name = split(child_path)[1]

            # Calculate the corresponding new path inside dst_path
            new_child_path = join(dst_path, child_name)

            # Recursively move the child
            try:
                 # We use mv logic here, but simplified since we know the parent structure is correct
                 self._structure[new_child_path] = child_type
                 if child_type == 'file':
                     self._contents[new_child_path] = self._contents[child_path]
                 # We don't need to worry about the parent directory structure of the child, 
                 # as we are moving it entirely.
                 self._structure.pop(child_path)
                 self._contents.pop(child_path, None)
            except Exception:
                 # In a real system, this would be complex error handling. 
                 # For this scope, we assume basic move succeeds if the target parent is ready.
                 return False

        # Finally, move the directory entry itself (this is handled by the main mv logic, 
        # but we remove the structure entry here if we are moving the directory)
        return True

    def find(self, path: str = '.', pattern: str = '*') -> List[str]:
        start_path = self._resolve_path(path)

        if start_path not in self._structure:
            raise NotFound(start_path)

        if self._structure[start_path] == 'file':
            if split(start_path)[1] == pattern:
                return [start_path]
            return []

        results = []
        queue = [start_path]

        while queue:
            current_path = queue.pop(0)

            # Find direct children
            children = []
            for k in self._structure:
                if k.startswith(current_path + '/') and k != current_path:
                    children.append(k)

            for child_path in children:
                name = split(child_path)[1]

                if fnmatch.fnmatchcase(name, pattern):
                    results.append(child_path)

                if self._structure[child_path] == 'dir':
                    queue.append(child_path)

        return sorted(results)

    def exists(self, path: str) -> bool:
        target_path = self._resolve_path(path)
        return target_path in self._structure

    def is_dir(self, path: str) -> bool:
        target_path = self._resolve_path(path)
        if target_path not in self._structure:
            return False
        return self._structure[target_path] == 'dir'


