from dataclasses import dataclass, field
from typing import Any, NamedTuple, Iterable, Tuple
import hashlib
import struct

class CorruptObject(ValueError):
    """Raised when an object's serialization is invalid."""
    pass

@dataclass(frozen=True)
class Blob:
    data: bytes

@dataclass(frozen=True)
class TreeEntry(NamedTuple):
    name: str
    kind: str  # 'blob' or 'tree'
    oid: str

@dataclass(frozen=True)
class Tree:
    entries: Tuple[TreeEntry, ...]

@dataclass(frozen=True)
class Commit:
    tree: str
    parents: Tuple[str, ...]
    author: str
    timestamp: int
    message: str

def _validate_name(name: str):
    """Validates tree entry names."""
    if not name:
        raise ValueError("Name cannot be empty.")
    if name in (".", ".."):
        raise ValueError("Name cannot be '.' or '..'.")
    if any(c in name for c in ["/", "\0", "\t", "\n"]):
        raise ValueError("Name contains invalid characters.")

def serialize(obj: Any) -> bytes:
    """Serializes an object into a content-addressed format."""
    obj_type: str
    body: bytes

    if isinstance(obj, Blob):
        obj_type = "blob"
        body = obj.data
    elif isinstance(obj, Tree):
        obj_type = "tree"
        entries: Iterable[TreeEntry] = obj.entries

        # Ensure entries are sorted by name for consistent serialization
        sorted_entries = tuple(sorted(entries, key=lambda e: e.name.encode('utf-8')))

        body_parts = []
        for entry in sorted_entries:
            # f"{kind} {oid}\t{name}\n"
            line = f"{entry.kind} {entry.oid}\t{entry.name}\n"
            body_parts.append(line.encode('utf-8'))
        body = b"".join(body_parts)
    elif isinstance(obj, Commit):
        obj_type = "commit"

        # 1. tree <oid>\n
        tree_part = f"tree {obj.tree}\n".encode('utf-8')

        # 2. parent <oid>\n for each parent
        parent_parts = [f"parent {p}\n".encode('utf-8') for p in obj.parents]

        # 3. author <str>\n
        # Author must not contain "\n"
        if "\n" in obj.author:
            raise ValueError("Commit author cannot contain newline characters.")
        author_part = f"author {obj.author}\n".encode('utf-8')

        # 4. time <int>\n
        time_part = f"time {obj.timestamp}\n".encode('utf-8')

        # 5. blank line "\n"
        blank_line = b"\n"

        # 6. message
        message_part = obj.message.encode('utf-8')

        body = b"".join([tree_part] + parent_parts + [author_part, time_part, blank_line, message_part])
    else:
        raise TypeError(f"Unsupported object type: {type(obj)}")

    # Header: TYPE LENGTH\x00
    length_bytes = struct.pack('>I', len(body)) # Big-endian unsigned int (4 bytes)
    header = f"{obj_type} {len(body)}\x00".encode('ascii')

    return header + body

def object_id(obj: Any) -> str:
    """Returns the SHA-1 oid of the serialized object."""
    raw = serialize(obj)
    return hashlib.sha1(raw).hexdigest()

def parse_object(raw: bytes) -> Any:
    """Parses raw bytes back into an object instance."""

    # 1. Parse Header (TYPE LENGTH\x00)
    try:
        header_end = raw.index(b'\x00')
    except ValueError:
        raise CorruptObject("Missing null byte terminator in header.")

    header_data = raw[:header_end].split(b'\x00')[0]
    parts = header_data.decode('ascii').split()

    if len(parts) != 2:
        raise CorruptObject("Malformed header format.")

    obj_type = parts[0]
    try:
        length = int(parts[1])
    except ValueError:
        raise CorruptObject("Invalid length specified in header.")

    # Check if raw length matches specified length
    if len(raw) != (header_end + 1) + length:
        raise CorruptObject(f"Declared length ({length}) does not match actual body size.")

    body = raw[header_end + 1: header_end + 1 + length]

    # 2. Parse Body
    if obj_type == "blob":
        return Blob(data=body)

    elif obj_type == "tree":
        entries: list[TreeEntry] = []

        # Entries are one per line: "kind oid\tname\n"
        lines = body.split(b'\n')

        for line in lines:
            if not line:
                continue

            try:
                # Split by first tab: "kind oid\tname"
                parts = line.split(b'\t', 1)
                if len(parts) != 2:
                    raise CorruptObject("Tree entry missing tab separator.")

                metadata, name_bytes = parts
                kind, oid = metadata.decode('ascii').split()
                name = name_bytes.decode('utf-8')

                # Validate entry constraints
                if kind not in ('blob', 'tree'):
                    raise CorruptObject(f"Unknown kind '{kind}' in tree entry.")

                # Name validation is handled by Tree constructor, but we check basic constraints here
                _validate_name(name)

                entries.append(TreeEntry(name=name, kind=kind, oid=oid))
            except Exception as e:
                raise CorruptObject(f"Error parsing tree entry: {e}")

        # Tree constructor handles sorting and final validation
        return Tree(entries=tuple(entries))

    elif obj_type == "commit":
        # Parsing Commit is complex due to variable structure
        lines = body.split(b'\n')

        tree_oid = None
        parents_oids: list[str] = []
        author_str = None
        timestamp = None
        message_start_index = -1

        i = 0
        while i < len(lines):
            line = lines[i]
            if not line.strip():
                # Found the blank line separator
                message_start_index = i + 1
                break

            try:
                prefix, data = line.split(b' ', 1)
                data_str = data.decode('utf-8').strip()
            except ValueError:
                raise CorruptObject("Malformed commit line.")

            if prefix == b"tree":
                tree_oid = data_str
            elif prefix == b"parent":
                parents_oids.append(data_str)
            elif prefix == b"author":
                author_str = data_str
            elif prefix == b"time":
                try:
                    timestamp = int(data_str)
                except ValueError:
                    raise CorruptObject("Invalid timestamp format.")
            i += 1

        if tree_oid is None or author_str is None or timestamp is None:
            raise CorruptObject("Missing required commit fields (tree, author, or time).")

        if message_start_index == -1:
             raise CorruptObject("Missing blank line separator before message.")

        # Reconstruct message: everything from the blank line onwards
        message_lines = lines[message_start_index:]
        message = b"".join(message_lines).decode('utf-8')

        # Validate commit constraints
        if timestamp < 0:
            raise ValueError("Commit timestamp must be non-negative.")
        if "\n" in author_str:
            raise ValueError("Commit author cannot contain newline characters.")

        # Commit constructor handles parent/tree oid validation
        return Commit(
            tree=tree_oid,
            parents=tuple(parents_oids),
            author=author_str,
            timestamp=timestamp,
            message=message
        )

    else:
        raise CorruptObject(f"Unknown object type: {obj_type}")

