class ObjectStore:
    def __init__(self):
        # Stores objects mapped by oid (SHA-1 hex string)
        self._store: Dict[str, Any] = {}

    def put(self, obj: Any) -> str:
        """Stores an object and returns its oid."""
        oid = object_id(obj)
        if oid not in self._store:
            self._store[oid] = obj
        return oid

    def put_raw(self, raw: bytes) -> str:
        """Stores an object from raw bytes, validating it first."""
        try:
            obj = parse_object(raw)
            oid = object_id(obj)
            # Ensure the stored object matches the parsed object structure
            if self._store.get(oid) is None:
                self._store[oid] = obj
            return oid
        except (CorruptObject, ValueError) as e:
            raise ValueError(f"Failed to parse and store object: {e}")

    def get(self, oid: str) -> Any:
        """Returns the object associated with the oid."""
        try:
            return self._store[oid]
        except KeyError:
            raise ObjectNotFound(f"Object with oid {oid} not found.")

