    def resolve(self, prefix: str) -> str:
        """
        Returns the single stored oid starting with the prefix.
        Raises ObjectNotFound or AmbiguousPrefix.
        """
        if not (4 <= len(prefix) <= 40 and all(c in '0123456789abcdef' for c in prefix)):
            raise ValueError("Prefix must be 4 to 40 lowercase hex characters.")

        matching_oids = [oid for oid in self._store.keys() if oid.startswith(prefix)]

        if not matching_oids:
            raise ObjectNotFound(f"No object found matching prefix {prefix}.")
        if len(matching_oids) > 1:
            raise AmbiguousPrefix(f"Multiple objects found matching prefix {prefix}.")

        return matching_oids[0]

