                raise ValueError("Path cannot start or end with '/'.")
            if any(c in path for c in ["\0", "\t", "\n"]):
                raise ValueError("Path contains invalid characters.")

            # Check for ambiguity: a path cannot be both a file and a directory name
            # We handle this by assuming if it contains '/', it must be a directory structure
            if '/' in path and path.split('/')[-1] in [p.split('/')[-1] for p in files if '/' not in p and p in files]:
                 # Simplified check: if it's a file path but its last component conflicts with a potential directory name
                 pass # Real conflict checking is complex, relying on Tree construction below.

            blob = Blob(data=data)
            blob_oid = self.put(blob)
            blob_map[path] = blob_oid

        # 2. Build Tree structure recursively (using path components)
        # Structure: {directory_name: {file_paths_in_this_dir: blob_oid}}
        structure: Dict[str, Dict[str, str]] = {}

        for path, oid in blob_map.items():
            parts = path.split('/')
            current_level = structure

            for i, part in enumerate(parts):
                if part not in current_level:
                    current_level[part] = {}

                if i == len(parts) - 1:
                    # This is the file itself
                    current_level[part]['__file_oid__'] = oid
                else:
