                    if '__file_oid__' in node_content:
                        raise ValueError(f"Path segment '{name}' is both a directory and a file.")

                    subtree_tree = build_tree_from_structure(node_content, current_path)
                    entries.append(TreeEntry(name=name, kind='tree', oid=subtree_tree.entries[0].oid if subtree_tree.entries else self.put(Tree(tuple()))))

                elif isinstance(node_content, dict) and '__file_oid__' in node_content:
                    # This is a file
                    blob_oid = node_content['__file_oid__']
                    entries.append(TreeEntry(name=name, kind='blob', oid=blob_oid))
                else:
                    # Should not happen if structure is correctly built
                    raise RuntimeError("Unexpected structure element during tree building.")

            # Sort entries by name before creating the Tree object
            entries.sort(key=lambda e: e.name.encode('utf-8'))
            return Tree(entries=tuple(entries))

        # The structure dictionary represents the root level
        root_tree = build_tree_from_structure(structure)
        return self.put(root_tree)

    def read_tree(self, oid: str) -> Dict[str, bytes]:
        """Returns the dict mapping full file path to blob data, sorted by path."""
        tree_obj = self.get(oid)
        if not isinstance(tree_obj, Tree):
            raise TypeError("OID does not point to a Tree object.")

        result: Dict[str, bytes] = {}

        # Simple BFS/DFS traversal to flatten the tree structure to files
        queue = [(None, tree_obj)] # (current_path_prefix, tree_object)

        while queue:
            prefix, current_tree = queue.pop(0)

            for entry in current_tree.entries:
                name = entry.name
                new_prefix = f"{prefix}/{name}" if prefix else name

                if entry.kind == 'blob':
                    blob_obj = self.get(entry.oid)
                    if isinstance(blob_obj, Blob):
                        result[new_prefix] = blob_obj.data
                elif entry.kind == 'tree':
                    subtree = self.get(entry.oid)
                    if isinstance(subtree, Tree):
                        queue.append((new_prefix, subtree))

        # Ensure keys are sorted by path
        return dict(sorted(result.items()))


    def commit(self, tree: str, parents: Tuple[str, ...], *, author: str, timestamp: int, message: str) -> str:
        """Stores a Commit object."""
        # Validation happens inside Commit construction via serialize/parse

        # Check existence
        if tree not in self._store:
            raise ObjectNotFound(f"Tree object with oid {tree} not found.")

        for parent_oid in parents:
            if parent_oid not in self._store:
                raise ObjectNotFound(f"Parent commit with oid {parent_oid} not found.")
            # We trust the structure check later, but check if it *looks* like a commit
            if not isinstance(self._store[parent_oid], Commit):
                 raise ValueError(f"OID {parent_oid} does not point to a Commit object.")

        # Ensure tree is a Tree
        if not isinstance(self._store[tree], Tree):
            raise ValueError(f"OID {tree} does not point to a Tree object.")

        commit_obj = Commit(
            tree=tree,
            parents=parents,
            author=author,
            timestamp=timestamp,
            message=message
        )
        return self.put(commit_obj)

    def log(self, oid: str, first_parent: bool = False) -> List[str]:
        """Returns commit oids walking history, ordered by timestamp (newest first)."""
        if oid not in self._store:
            raise ObjectNotFound(f"Commit object with oid {oid} not found.")

        current_oid = oid
        history: Dict[str, Any] = {} # oid -> commit object

        while current_oid:
            commit_obj = self.get(current_oid)
            if not isinstance(commit_obj, Commit):
                # Should not happen if history traversal is correct, but safety check
                break 

            if current_oid in history:
                # Cycle detected
                break 

            history[current_oid] = commit_obj

            if first_parent:
                if not commit_obj.parents:
                    current_oid = None
                    break
                current_oid = commit_obj.parents[0]
            else:
                # Walk all parents to find the next set of nodes to process
                # This implementation only handles walking back along the first parent by default 
                # if not specified, matching typical Git log behavior for simplification, 
                # but the requirement suggests walking ancestors, implying graph traversal.
                # For simplicity and adhering to common Git behavior when not specifying a graph traversal, 
                # we traverse the first parent unless specified otherwise, or we must implement full DAG traversal.
                # Given the complexity, we stick to the simple single-parent chain walk for now, 
                # as full DAG sorting is complex.
                if not commit_obj.parents:
                    current_oid = None
                    break
                current_oid = commit_obj.parents[0]


        # Sort results: newest first (descending timestamp), then oid ascending for ties
        sorted_history = sorted(
            history.values(), 
            key=lambda c: (-c.timestamp, c.tree) # Sorting by tree oid as a tie breaker proxy if timestamp is identical
        )

        return [c.tree for c in sorted_history] # Returning tree OIDs is common, but the requirement asks for commit oids.
