```python
from typing import NamedTuple, Optional, Tuple, Dict, Any
from .objects import Blob, Tree, TreeEntry
from .store import ObjectStore
import sys

class Change(NamedTuple):
    status: str  # 'A', 'D', 'M'
    path: str
    old: Optional[str]  # Blob oid
    new: Optional[str]  # Blob oid

def diff_trees(store: ObjectStore, old_oid: Optional[str], new_oid: Optional[str]) -> list[Change]:
    """
    Compares two trees.
    """

    # Handle empty tree cases (None oid)
    def get_tree_data(oid: Optional[str]) -> Optional[Tree]:
        if oid is None:
            return Tree(entries=tuple())
        try:
            return store.get(oid)
        except Exception:
            return None

    old_tree = get_tree_data(old_oid)
    new_tree = get_tree_data(new_oid)

    # Internal recursive comparison function
    def recurse_diff(old_entries: tuple[TreeEntry, ...], new_entries: tuple[TreeEntry, ...], current_path: str) -> list[Change]:
        changes: list[Change] = []

        # Map names to entries for O(1) lookup during iteration
        old_map: Dict[str, TreeEntry] = {e.name: e for e in old_entries}
        new_map: Dict[str, TreeEntry] = {e.name: e for e in new_entries}

        all_names = sorted(list(set(old_map.keys()) | set(new_map.keys())))

        for name in all_names:
            old_entry = old_map.get(name)
            new_entry = new_map.get(name)

            path = f"{current_path}/{name}" if current_path else name

            # Case 1: Added (New entry exists, Old does not)
            if new_entry and not old_entry:
                if new_entry.kind == 'blob':
                    changes.append(Change('A', path, None, new_entry.oid))
                elif new_entry.kind == 'tree':
                    # Added directory: report all contents as added
                    # This requires reading the new subtree, which is complex.
                    # Following the prompt: "every file under the directory is added"
                    # We must recursively list everything in the new tree.
                    subtree_changes = list_all_contents_changes(store, new_entry.oid, path, 'A')
                    changes.extend(subtree_changes)

            # Case 2: Deleted (Old entry exists, New does not)
            elif old_entry and not new_entry:
                if old_entry.kind == 'blob':
                    changes.append(Change('D', path, old_entry.oid, None))
                elif old_entry.kind == 'tree':
                    # Deleted directory: report all contents as deleted
                    # We must recursively list everything in the old tree.
                    subtree_changes = list_all_contents_changes(store, old_entry.oid, path, 'D')
                    changes.extend(subtree_changes)

            # Case 3: Exists in both (Check for modification or subtree equality)
            elif old_entry and new_entry:

                # 3a: Name/Kind mismatch (e.g., file changed to directory)
                if old_entry.kind != new_entry.kind:
                    # Treat as Delete old structure, Add new structure
                    changes.append(Change('D', path, old_entry.oid, None))
                    if new_entry.kind == 'blob':
                         changes.append(Change('A', path, None, new_entry.oid))
                    elif new_entry.kind == 'tree':
                        subtree_changes = list_all_contents_changes(store, new_entry.oid, path, 'A')
                        changes.extend(subtree_changes)
                    return sorted(changes, key=lambda c: c.path) # Return immediately if structure changes drastically

                # 3b: Both are blobs (Check content)
                elif old_entry.kind == 'blob' and new_entry.kind == 'blob':
                    if old_entry.oid != new_entry.oid:
                        changes.append(Change('M', path, old_entry.oid, new_entry.oid))

                # 3c: Both are trees (Recurse)
                elif old_entry.kind == 'tree' and new_entry.kind == 'tree':
                    # Skip if oids match (content is the same)
                    if old_entry.oid == new_entry.oid:
                        continue 

                    # Recurse
                    sub_changes = recurse_diff(
                        old_entry.entries, 
                        new_entry.entries, 
                        path
                    )
                    changes.extend(sub_changes)

        return changes

    def list_all_contents_changes(store: ObjectStore, oid: str, current_path: str, status: str) -> list[Change]:
        """Recursively lists all files within a tree OID with a given status ('A' or 'D')."""
        try:
            tree = store.get(oid)
        except Exception:
            return [] # Failed to resolve tree

        if not isinstance(tree, Tree):
            return []

        changes: list[Change] = []

        for entry in tree.entries:
            name = entry.name
            path = f"{current_path}/{name}" if current_path else name

            if entry.kind == 'blob':
                changes.append(Change(status, path, None, entry.oid if status == 'A' else None))
            elif entry.kind == 'tree':
                subtree_changes = list_all_contents_changes(store, entry.oid, path, status)
                changes.extend(subtree_changes)

        return changes


def diff_commits(store: ObjectStore, old_oid: Optional[str], new_oid: Optional[str]) -> list[Change]:
    """Diffs the trees of two commits."""
    old_tree_oid = None
    new_tree_oid = None

    if old_oid:
        try:
            commit = store.get(old_oid)
            if not isinstance(commit, Commit):
                raise ValueError("Old OID is not a Commit.")
            old_tree_oid = commit.tree
        except Exception:
            pass # Old commit not found, treat as empty base

    if new_oid:
        try:
            commit = store.get(new_oid)
            if not isinstance(commit, Commit):
                raise ValueError("New OID is not a Commit.")
            new_tree_oid = commit.tree
        except Exception:
            pass # New commit not found, treat as empty base

    # diff_trees handles None oids correctly
    return diff_trees(store, old_tree_oid, new_tree_oid)


def format_changes(changes: list[Change]) -> str:
    """Returns one line per change: f"{status}\t{path}\n"."""
    output = []
    for change in changes:
        # The specification implies format "status\tpath\n". 
        # Since old/new are omitted from the output format, we only print status and path.
        output.append(f"{change.status}\t{change.path}\n")
    return "".join(output)
